local config = {
  ui_story_5058_50580101_1_dialog_content = "\"Bagaimana kabarmu, teman lama? Sudah lama aku tidak mendengar kabar darimu.\"",
  ui_story_5058_50580101_2_dialog_content = "\"Aku masih sama. Seperti yang kamu tahu, kami tentara bayaran sering mendapat tugas-tugas aneh.\"",
  ui_story_5058_50580101_3_dialog_content = "\"Tidak banyak waktu luang di tangan, tapi cukup bisa melukis beberapa goresan sehari saja sudah cukup untukku.\"",
  ui_story_5058_50580101_4_dialog_content = "\"Hanya saja, saya belum bisa bertemu orang lain yang memiliki ketertarikan pada serangga seperti kamu.\"",
  ui_story_5058_50580101_X4_dialog_content = "\"Itu membuat saya merasa agak kesepian.\"",
  ui_story_5058_50580101_5_dialog_content = "\"Namun, saya telah berteman baru, seperti PlayerName.\"",
  ui_story_5058_50580101_X5_dialog_content = "\"Saya akan memperkenalkan kalian berdua saat saya mendapat kesempatan.\"",
  ui_story_5058_50580101_6_dialog_content = "\"Tapi saya menyimpang. Akhir-akhir ini saya mendengar kabar tentang kupu-kupu yang disebut <color=#FFB400>Dewi Denuo</color>.\"",
  ui_story_5058_50580101_7_dialog_content = "\"Sebuah tempat bernama <color=#FFB400>Denuo Valley Resort</color> mengiklankan bahwa kupu-kupu yang menakjubkan dapat dilihat di sana...\"",
  ui_story_5058_50580101_8_dialog_content = "\"Itu juga mengklaim bahwa melihat satu akan membawa keberuntungan dan berkat dari dewi.\"",
  ui_story_5058_50580101_9_dialog_content = "\"Tentu saja ini jelas hanya sensasi belaka, tapi aku ingat kamu pernah menyebutkan spesies kupu-kupu ini.\"",
  ui_story_5058_50580101_10_dialog_content = "\"Eveeskipun kamu tidak pernah mengungkapkan hubungan antara mereka dan kota kelahiranmu yang misterius...\"",
  ui_story_5058_50580101_11_dialog_content = "\"Terlepas dari itu, semoga berita ini bermanfaat untuk kamu, dan kita memiliki kesempatan untuk bertemu lagi.\"",
  ui_story_5058_50580101_12_dialog_content = "\"Menantikan balasan Anda.\"",
  ui_story_5058_50580101_13_dialog_content = "Tidak bisa percaya ada yang merindukan seseorang seperti aku.",
  ui_story_5058_50580101_14_dialog_content = "Tapi bagaimana cara saya menjelaskan kepada kamu apa yang sedang saya lakukan sekarang, Luke...?",
  ui_story_5058_50580101_15_dialog_content = "Mau mampir sebentar, Cena?",
  ui_story_5058_50580101_16_dialog_content = "Undangan <color=#FFB400>yang</color> saya sebutkan sudah selesai. Tolong kirimkan untuk saya!",
  ui_story_5058_50580101_17_dialog_content = "Tentu, bos, akan melakukan!",
  ui_story_5058_50580101_18_dialog_content = "<color=#e8d9bb>Wuuss—</color>",
  ui_story_5058_50580101_19_dialog_content = "Apakah kamu yakin kita berada di tempat yang benar, PlayerName? Saya bahkan tidak melihat sesuatu yang mirip rumah normal...",
  ui_story_5058_50580101_20_dialog_content = "Ini hanya tidak menjerit \"resor premium untuk melihat Dewi Denuo!\" bagi saya.",
  ui_story_5058_50580101_21_dialog_content = "Nah, ini adalah tempat yang ditunjukkan oleh koordinat...",
  ui_story_5058_50580101_22_dialog_content = "Apakah kamu membeli tiket melalui saluran yang sah?",
  ui_story_5058_50580101_23_option_content = "Saya sudah pastikan itu!",
  ui_story_5058_50580101_24_dialog_content = "Lalu apa maksud <color=#FFB400>undangan</color> yang kamu pegang itu?",
  ui_story_5058_50580101_25_dialog_content = "Resort itu mengirimkannya ke saya, jadi seharusnya sah, kan?",
  ui_story_5058_50580101_26_option_content = "Hmm…",
  ui_story_5058_50580101_27_dialog_content = "Saya mendapat <color=#FFB400>undangan</color> ini untuk saya melalui pesan, jadi seharusnya ini sah, kan?",
  ui_story_5058_50580101_28_dialog_content = "Hah? Biar kulihat...",
  ui_story_5058_50580101_29_dialog_content = "\"Yang terhormat PlayerName, kami dengan senang hati mengumumkan bahwa Denuo Valley Resort yang sangat dinantikan akhirnya selesai!\"",
  ui_story_5058_50580101_30_dialog_content = "\"Lokasinya mencakup taman hiburan yang sangat besar dan hotel premium.\"",
  ui_story_5058_50580101_31_dialog_content = "\"Kami dengan tulus mengundang Anda untuk mencoba semua fasilitas dan layanan yang kami tawarkan secara gratis, sebelum kami buka untuk umum!\"",
  ui_story_5058_50580101_32_dialog_content = "\"Terlampir dalam undangan ini ada tiga tiket VIP. Silakan ajak keluarga atau teman untuk ikut serta.\"",
  ui_story_5058_50580101_33_dialog_content = "\"Seluruh staf Denuo Valley Resort menantikan kedatangan Anda!\"",
  ui_story_5058_50580101_34_dialog_content = "Pemilik Utama: Lorelei Cardogon",
  ui_story_5058_50580101_35_dialog_content = "Saya penasaran mengapa kamu memiliki tiket ke resor yang belum dibuka, PlayerName.",
  ui_story_5058_50580101_36_dialog_content = "Jadi sebenarnya itu tiket gratis... Saya kira kamu menggali tabunganmu.",
  ui_story_5058_50580101_37_dialog_content = "Tapi ini terdengar terlalu bagus untuk menjadi kenyataan. Saya rasa ini salah satu penipuan baru, atau...",
  ui_story_5058_50580101_38_dialog_content = "Tunggu, bagaimana jika ada perampok yang bersembunyi untuk menghadang kita?",
  ui_story_5058_50580101_39_dialog_content = "Hei, tunggu. Bukankah ini wilayah Rediesel Wrench?",
  ui_story_5058_50580101_40_dialog_content = "<color=#e8d9bb>Jepret!</color>",
  ui_story_5058_50580101_41_dialog_content = "Kita benar-benar mendapatkan perampok sungguhan?!",
  ui_story_5058_50580101_42_dialog_content = "Bandit? Yah, kamu benar dalam arti bahwa seorang bandit ada untuk mencuri hati wanita... tapi itu bukan intinya.",
  ui_story_5058_50580101_43_dialog_content = "Kami telah menantikan kunjungan Anda, PlayerName, dan akhirnya, hari ini Anda di sini.",
  ui_story_5058_50580101_44_dialog_content = "Wanita muda cantik yang bersama kamu pasti Vice dan Carleen, bukan?",
  ui_story_5058_50580101_45_dialog_content = "Siapa kau?",
  ui_story_5058_50580101_46_dialog_content = "Mohon maaf karena belum memperkenalkan diri dengan baik. Saya adalah Cena, <color=#FFB400>manajer umum</color> dari Denuo Valley Resort.",
  ui_story_5058_50580101_47_dialog_content = "Oh, untunglah, tiketnya asli! Tapi apakah tempat ini benar-benar sebuah resor? Tidak terlalu cocok dengan deskripsi di brosur...",
  ui_story_5058_50580101_48_dialog_content = "Hahaha, Lembah Denuo bisa cukup berbahaya bahkan untuk Eclipsite. Bukan tempat yang mudah untuk ditemukan.",
  ui_story_5058_50580101_49_dialog_content = "EveMeskipun kami menyediakan antar-jemput untuk tamu kami dari keempat penjuru dunia...",
  ui_story_5058_50580101_50_dialog_content = "Bos secara khusus memerintahkan saya untuk menjemput kamu secara pribadi, karena kamu adalah VIP utama kami.",
  ui_story_5058_50580101_X50_dialog_content = "Apakah tamu terhormat kita memiliki pertanyaan?",
  ui_story_5058_50580101_51_option_content = "Bosnya?",
  ui_story_5058_50580101_52_dialog_content = "Apakah itu Nyonya Lorelei Cardogon yang ada di undangan?",
  ui_story_5058_50580101_53_dialog_content = "Ya. Nona Lorelei adalah putri tertua dari keluarga Cardogon dan terkenal di bidang real estat, serta pemilik utama dari Denuo Valley Resort.",
  ui_story_5058_50580101_54_dialog_content = "Dibutuhkan seseorang yang mengesankan untuk membangun resor raksasa, namun ini adalah pertama kalinya saya mendengar nama ini.",
  ui_story_5058_50580101_55_dialog_content = "Yang sebenarnya tidak aneh. Cardogons itu low-key, tetapi memiliki investasi di seluruh Astra. Nama mereka biasanya hanya dikenal oleh orang dalam bisnis.",
  ui_story_5058_50580101_56_dialog_content = "Tapi Nona Lorelei tidak mengandalkan keluarganya untuk usaha ini. Dia merekrut investasi dari luar sendiri untuk meluncurkan fasilitas tersebut.",
  ui_story_5058_50580101_57_dialog_content = "Dia menyelesaikan semua ini secara mandiri tanpa keluarganya? Itu berani!",
  ui_story_5058_50580101_X57_dialog_content = "Benar sekali.",
  ui_story_5058_50580101_58_option_content = "Saya VIP premier?",
  ui_story_5058_50580101_X59_dialog_content = "Itu terlalu jauh...",
  ui_story_5058_50580101_59_dialog_content = "PlayerName, reputasimu dikenal di seluruh Astra dan bahkan telah menyebar ke timur jauh.",
  ui_story_5058_50580101_60_dialog_content = "Bos sudah jadi penggemar Anda... Tidak, apa kata itu lagi?",
  ui_story_5058_50580101_61_dialog_content = "Ah, mengerti, Lovegator!",
  ui_story_5058_50580101_62_dialog_content = "Saya tersanjung! Tapi bos Anda tentu memiliki wawasan yang luas bahkan untuk mengetahui hal-hal seperti itu.",
  ui_story_5058_50580101_X61_dialog_content = "Memang!",
  ui_story_5058_50580101_X62_dialog_content = "Oh, kamu juga menyebutkan...",
  ui_story_5058_50580101_63_option_content = "Sebuah antar-jemput?",
  ui_story_5058_50580101_64_dialog_content = "Itu berarti kita harus naik kendaraan... Apakah resor itu jauh dari sini?",
  ui_story_5058_50580101_65_dialog_content = "Saya tidak akan bilang jauh, tapi pergi ke sana bisa sedikit petualangan. Cukup siap saja. Saya kira Anda bisa menyebut perjalanan ini sebagai perjalanan penuh sensasi juga.",
  ui_story_5058_50580101_66_dialog_content = "Kita tidak balapan seratus mil per jam di tempat kering dan sepi ini lagi, bukan? Di mana air terjun dan danau? Di mana liburan musim panas yang sejuk yang aku inginkan?",
  ui_story_5058_50580101_67_dialog_content = "EveSemua yang kamu cari ada di Lembah Denuo. Karena kamu sudah tidak sabar untuk kesana, ayo masuk ke dalam shuttle sekarang juga!",
  ui_story_5058_50580101_68_dialog_content = "Semakin cepat kita sampai di sana, semakin cepat kita bisa mulai bersenang-senang, benar, 'kan?",
  ui_story_5058_50580101_69_dialog_content = "Ayo, jangan tampak seperti kamu akan muntah sebelum masuk mobil! Agar kamu tahu, setiap orang suka dengan cara saya mengemudi.",
  ui_story_5058_50580101_70_dialog_content = "Oh, satu lagi... Lihat ke sini, para tamu terhormat, dan katakan, \"Cheese!\"",
  ui_story_5058_50580101_71_dialog_content = "Hah?",
  ui_story_5058_50580101_72_dialog_content = "Kamu harus mengambil foto untuk mengenang liburan ini!",
  ui_story_5058_50580101_73_dialog_content = "Sangat penuh pertimbangan... Saya punya firasat kita akan bersenang-senang di sini!",
  ui_story_5058_50580101_74_dialog_content = "Semoga saja.",
  ui_story_5058_50580101_75_dialog_content = "Hei, Carleen, jangan kasih aku tatapan itu! Kali ini tidak akan ada yang salah, kan? Hei!",
  ui_story_5058_50580101_76_dialog_content = "<color=#e8d9bb>Kriek...</color>",
  ui_story_5058_50580101_77_dialog_content = "Kami di sini, semua orang. Silakan keluar dari kendaraan.",
  ui_story_5058_50580101_78_dialog_content = "Eh... itu... itu kah yang disebut \"kemampuan mengemudi hebat\" yang kamu sebutkan tadi?",
  ui_story_5058_50580101_79_dialog_content = "La-la-la, la-ta-ta-la-la... ♪",
  ui_story_5058_50580101_80_dialog_content = "Tempat apa itu?",
  ui_story_5058_50580101_81_dialog_content = "La-la-la, la-ta-ta-la-la ♪ Denuo Valley Resort menyambut kamu ♪",
  ui_story_5058_50580101_82_dialog_content = "Wow, sama persis dengan gambar di brosur!",
  ui_story_5058_50580101_83_dialog_content = "Kami baru saja berada di gurun tandus dan sekarang begitu hidup di sekitar... Rasanya seperti kita berada di dunia yang berbeda.",
  ui_story_5058_50580101_84_dialog_content = "Terima kasih banyak kepada kalian semua yang luar biasa karena memilih Denuo Valley Resort untuk memulai liburan fantastis kalian! Bersiaplah untuk keseruan tanpa henti dan petualangan epik!",
  ui_story_5058_50580101_85_dialog_content = "Ya, tepat sekali, keseruan tanpa henti dan petualangan epik! Tapi itu masih terdengar sangat sederhana!",
  ui_story_5058_50580101_86_dialog_content = "\"Selain itu, kami akan menawarkan layanan paling premium dan pesta mewah?\"",
  ui_story_5058_50580101_87_dialog_content = "Hmm. Cena, ingatkan tim publisitas untuk mengerjakan slogan pintu masuk.",
  ui_story_5058_50580101_88_dialog_content = "Mengerti, Nona Lorelei.",
  ui_story_5058_50580101_89_dialog_content = "Kangen Lorelei? Jadi kamu adalah Miss Lorelei Cardogon, pemiliknya?",
  ui_story_5058_50580101_90_dialog_content = "<size=45>PlayerName, akhirnya kamu di sini!</size>",
  ui_story_5058_50580101_91_dialog_content = "Wow, ekor yang indah! Kamu pasti Vice.",
  ui_story_5058_50580101_92_dialog_content = "Dan wanita muda anggun di sini pasti Carleen!",
  ui_story_5058_50580101_93_dialog_content = "Senang saya memiliki kecerdasan untuk menyertakan tiga tiket. Saya punya firasat kamu akan membawa mereka berdua, PlayerName!",
  ui_story_5058_50580101_94_dialog_content = "Saya sangat berterima kasih karena Anda meluangkan waktu dari jadwal sibuk untuk menghadiri pembukaan lembut kami.",
  ui_story_5058_50580101_95_dialog_content = "Silakan merasa di rumah. Nikmati dan lepaskan kegembiraan!",
  ui_story_5058_50580101_96_dialog_content = "Nah, terima kasih atas undangannya, Nona Lorelei. Saya belum pernah ke taman yang seindah ini!",
  ui_story_5058_50580101_97_dialog_content = "Tolong, panggil saja saya Lorelei.",
  ui_story_5058_50580101_98_dialog_content = "Hmm, Teeny seharusnya menunjukkan sekitar... Di mana dia?",
  ui_story_5058_50580101_99_dialog_content = "Pokoknya, silakan masuk!",
  ui_story_5058_50580101_100_dialog_content = "...",
  ui_story_5058_50580101_101_dialog_content = "Hei, gadis berambut merah di sana...",
  ui_story_5058_50580101_102_option_content = "Saya rasa saya kenal dia!",
  ui_story_5058_50580101_103_dialog_content = "Bukankah itu Bopper?",
  ui_story_5058_50580101_104_dialog_content = "PlayerName... Tentu saja. Tidak ada siapa-siapa selain kamu yang akan langsung menyadari keberadaan saya...",
  ui_story_5058_50580101_105_option_content = "Dia terlihat familiar.",
  ui_story_5058_50580101_106_dialog_content = "Sudah kuduga... Mungkin sudah terlalu lama bagi kamu untuk mengingat aku.",
  ui_story_5058_50580101_107_dialog_content = "Aku Bopper, PlayerName. Kamu punya burung raksasa, dan aku punya Kadal Raksasa!",
  ui_story_5058_50580101_108_dialog_content = "Bopper, dari Rediesel Wrench?!",
  ui_story_5058_50580101_109_dialog_content = "Di sana kamu, Teeny. Aku sudah mencari kamu dengan sungguh-sungguh!",
  ui_story_5058_50580101_110_dialog_content = "Tapi saya selalu di sisi Anda sepanjang waktu, Nona Lorelei...",
  ui_story_5058_50580101_111_dialog_content = "Kamu juga di sini untuk pembukaan lunak, Bopper?",
  ui_story_5058_50580101_112_dialog_content = "Dia adalah spesialis teknis yang saya minta khusus dari Rediesel Wrench!",
  ui_story_5058_50580101_113_dialog_content = "Sebenarnya, saya lebih merupakan mekanik umum daripada ahli yang digambarkan oleh Miss Lorelei... Lainnya dari Rediesel Wrench juga di sini untuk membantu.",
  ui_story_5058_50580101_114_dialog_content = "Orang-orang Rediesel Wrench bekerja di pekerjaan reguler sekarang? Ini bisa jadi kesempatan saya untuk menangkap beberapa buronan yang dicari.",
  ui_story_5058_50580101_115_dialog_content = "Uh, Carleen, ayo jangan terpaku pada itu saat liburan kita, oke?",
  ui_story_5058_50580101_116_dialog_content = "Personalia resort kami telah melalui pemeriksaan latar belakang dan pelatihan yang ekstensif. Kami akan menangani masalah apa pun yang mungkin muncul tanpa kamu perlu mengangkat jari.",
  ui_story_5058_50580101_117_dialog_content = "Maaf mengganggu, Pak. Tiga pelanggan di luar sana secara khusus meminta untuk bertemu dengan Anda...",
  ui_story_5058_50580101_118_dialog_content = "Saya percaya saya sudah selesai di sini, Nona Lorelei. Saya akan pergi untuk mengurus urusan lainnya.",
  ui_story_5058_50580101_119_dialog_content = "PlayerName, Nona Vice, dan Nona Carleen, saya mengharapkan kalian semua menikmati kunjungan yang menyenangkan sebelumnya!",
  ui_story_5058_50580101_120_dialog_content = "Jangan bilang lagi sekelompok wanita cantik baru saja datang? Saya tidak tahu harus berbuat apa dengan dia...",
  ui_story_5058_50580101_121_dialog_content = "Meskipun aku tidak percaya waktu ini... Kenapa meeting harus dijadwalkan sekarang?",
  ui_story_5058_50580101_122_dialog_content = "Nah, teman-teman, senang rasanya kalian semua ada di sini!",
  ui_story_5058_50580101_123_dialog_content = "Tapi saya harus pergi sekarang. Setelah selesai, saya akan check-in kan kamu ke hotel dan menunjukkan tempat-tempat menarik!",
  ui_story_5058_50580101_124_dialog_content = "Kamu bisa melanjutkannya dari sini, Teeny!",
  ui_story_5058_50580101_125_dialog_content = "Ehem... panggil saja saya Bopper...",
  ui_story_5058_50580101_126_dialog_content = "Mengetahui bahwa kamu akan datang, aku begadang semalaman dan menyusun tiga puluh tiga rencana perjalanan.",
  ui_story_5058_50580101_127_dialog_content = "Saya menggabungkan preferensi pribadi PlayerName, Vice, dan Carleen untuk menurunkan langkah dan rute terbaik...",
  ui_story_5058_50580101_128_dialog_content = "Uh, kamu tidak perlu terlalu teliti, Bopper. Kita bisa santai saja.",
  ui_story_5058_50580101_129_dialog_content = "Santai saja? Untungnya, saya juga punya rencana untuk itu.",
  ui_story_5058_50580101_130_dialog_content = "Oke, jadi. Ikuti saya, setiap orang.",
  ui_story_5058_50580101_131_dialog_content = "Kami akan memulai rencana perjalanan paling kasual!",
  ui_story_5058_50580201_1_dialog_content = "Ini adalah foto-foto PlayerName yang diambil Caelestite dalam perjalanan menuju resort.",
  ui_story_5058_50580201_2_dialog_content = "Kami juga akan memotret Caelestite dengan berbagai atraksi dan fasilitas hotel.",
  ui_story_5058_50580201_3_dialog_content = "Kemudian kita bisa menaruh fitur panjang penuh dalam publikasi Anda!",
  ui_story_5058_50580201_4_dialog_content = "Hal tersebut akan menjual isu tersebut dan meningkatkan eksposur untuk resor.",
  ui_story_5058_50580201_5_dialog_content = "Hmm... Harus aku akui Lovegators memang punya kekuatan pembelian.",
  ui_story_5058_50580201_6_dialog_content = "Berdasarkan temuan kami, tempat-tempat yang dikunjungi Caelestite cenderung menjadi viral, seperti Pulau Awan, Kota Pelabuhan...",
  ui_story_5058_50580201_7_dialog_content = "Evedi tempat seperti Euphoria meledak!",
  ui_story_5058_50580201_8_dialog_content = "Benar, Harbor City kini menjadi tujuan wisata paling populer di Astra.",
  ui_story_5058_50580201_9_dialog_content = "Kota Pelabuhan? Kenapa terdengar familiar?",
  ui_story_5058_50580201_10_dialog_content = "Kamu, dalam misi, memutuskan untuk bergabung dalam kompetisi di tengah jalan dan hampir jatuh ke dalam air.",
  ui_story_5058_50580201_11_dialog_content = "AHHH! Kenangan tentang para rakyat jelata yang berlarian tanpa aturan kembali muncul! Diam! DIAM!",
  ui_story_5058_50580201_12_dialog_content = "Lorelei, Saya senang kamu mengikuti saran kami dan menggunakan Denuo Goddess sebagai terobosan dalam pemasaran resor.",
  ui_story_5058_50580201_13_dialog_content = "Dan saya sangat menghargai ide Anda untuk memanfaatkan ketenaran Caelestite untuk promosi.",
  ui_story_5058_50580201_14_dialog_content = "Tapi jujur saja, ini semua strategi pemasaran sementara, dan mungkin tidak akan bertahan dalam jangka panjang.",
  ui_story_5058_50580201_15_dialog_content = "Kita semua sadar bahwa Dewi Denuo hanyalah sebuah cerita. Siapa tahu apakah itu benar-benar ada?",
  ui_story_5058_50580201_16_dialog_content = "Belum lagi, popularitas Caelestite mungkin tidak akan bertahan, dan suatu hari nanti bisa berubah menjadi masalah besar.",
  ui_story_5058_50580201_17_dialog_content = "Uang yang telah kita tuangkan ke dalam resor ini bukanlah jumlah yang sepele...",
  ui_story_5058_50580201_18_dialog_content = "Saya mengerti apa yang semua dari kalian inginkan sebagai investor.",
  ui_story_5058_50580201_19_dialog_content = "Untuk menjadikan resor ini operasi yang berkelanjutan, kita harus memastikan layanan berkualitas dan menyediakan—",
  ui_story_5058_50580201_20_dialog_content = "Tidak, yang saya maksud adalah kita harus menyediakan sesuatu yang lebih \"menggoda\"...",
  ui_story_5058_50580201_21_dialog_content = "...",
  ui_story_5058_50580201_22_dialog_content = "Apakah kamu yakin ini adalah rencana perjalanan paling kasualmu, Bopper?",
  ui_story_5058_50580201_23_dialog_content = "Ya... Ini adalah rute yang saya tempuh saat ingin bersantai, sendiri.",
  ui_story_5058_50580201_24_dialog_content = "Ini benar-benar membuatmu rileks?!",
  ui_story_5058_50580201_25_dialog_content = "Death's Door adalah wahana favoritku. Beberapa orang di Rediesel Wrench bisa menaikinya selusin kali sehari!",
  ui_story_5058_50580201_26_dialog_content = "Kita beruntung kamu datang lebih awal. Kalau tidak, kita harus menunggu di antrian panjang.",
  ui_story_5058_50580201_27_dialog_content = "Wow, saya tidak sabar menunggu! Cepatlah, PlayerName.",
  ui_story_5058_50580201_28_dialog_content = "Saya rasa lutut saya sudah mulai lemas...",
  ui_story_5058_50580201_29_dialog_content = "Apa? Saya kira kamu sudah terbiasa dengan ketinggian ini mengingat seberapa sering kamu mengendarai Elang Raksasa...",
  ui_story_5058_50580201_30_dialog_content = "Dia benar. Kamu bahkan pernah mengalami kecelakaan beberapa kali, jadi ini seharusnya menjadi permainan anak-anak sekarang.",
  ui_story_5058_50580201_31_dialog_content = "Melakukan sesuatu seperti ini secara aktif dibandingkan tidak memiliki pilihan sama sekali sangat berbeda...",
  ui_story_5058_50580201_32_dialog_content = "Santai, aku rasa kamu akan baik-baik saja!",
  ui_story_5058_50580201_33_dialog_content = "Dalam hal ini, saya rasa PlayerName harus menghadapi tantangan terberat!",
  ui_story_5058_50580201_34_dialog_content = "Setelah kamu melompat, boneka Eclipsite yang bisa mengembang akan dilepaskan di sekitar kamu.",
  ui_story_5058_50580201_35_dialog_content = "Tangkap mereka saat turun untuk memenangkan stiker peringatan.",
  ui_story_5058_50580201_36_dialog_content = "Dan, kamu juga bisa membawa Eclipsites yang bisa diisi angin ini ke rumah!",
  ui_story_5058_50580201_37_dialog_content = "Siapa yang mau boneka angin yang terlihat seperti Eclipsite?!",
  ui_story_5058_50580201_38_dialog_content = "Saya, saya, mau!",
  ui_story_5058_50580201_39_dialog_content = "Tolong bawakan satu kembali untuk saya!",
  ui_story_5058_50580201_40_dialog_content = "Apa?",
  ui_story_5058_50580201_41_dialog_content = "Arghhhh—!",
  ui_story_5058_50580201_42_dialog_content = "Kamu setidaknya bisa memberi aku peringatan!",
  ui_story_5058_50580202_1_dialog_content = "Kau baik-baik saja? Kamu terus mengusap matamu... kamu menangis?",
  ui_story_5058_50580202_2_dialog_content = "Tidak, bukan itu!",
  ui_story_5058_50580202_3_dialog_content = "Ada semua lampu ini berkedip di mataku saat jatuh...",
  ui_story_5058_50580202_4_dialog_content = "Oh, itu kamera yang mengambil foto. Mau lihat fotonya?",
  ui_story_5058_50580202_5_dialog_content = "Lupakan saja, mungkin aku terlihat canggung...",
  ui_story_5058_50580202_6_dialog_content = "Lihat semua stiker yang aku dapatkan!",
  ui_story_5058_50580202_7_dialog_content = "Hah? Kalian berdua berhasil? Selamat berhasil melewati permainan!",
  ui_story_5058_50580202_8_dialog_content = "EveSetiap wahana di taman memiliki tantangan, dan kamu akan mendapatkan stiker jika menyelesaikannya.",
  ui_story_5058_50580202_9_dialog_content = "Semakin banyak stiker yang kamu dapatkan, semakin bagus hadiah yang bisa kamu tukar.",
  ui_story_5058_50580202_10_dialog_content = "Hei, Carleen, ingin melihat siapa yang mendapatkan hadiah lebih baik?",
  ui_story_5058_50580202_11_dialog_content = "Tentu, tapi kenapa tidak minta PlayerName untuk membantu kamu.",
  ui_story_5058_50580202_12_dialog_content = "Akan menjadi keajaiban jika saya tidak perlu membantu PlayerName, apalagi sebaliknya.",
  ui_story_5058_50580202_13_dialog_content = "Hei, aku bisa mendengarmu, tahu kan.",
  ui_story_5058_50580202_14_dialog_content = "Katakan, kupu-kupu di stiker ini tentu sangat cantik!",
  ui_story_5058_50580202_15_dialog_content = "Itu bukan kupu-kupu biasa, melainkan Dewi Denuo yang unik untuk Lembah Denuo.",
  ui_story_5058_50580202_16_dialog_content = "Apakah Dewi Denuo benar-benar ada?",
  ui_story_5058_50580202_17_dialog_content = "Saya percaya begitu! Seseorang baru saja mengatakan bahwa mereka menemukannya di resor baru-baru ini...",
  ui_story_5058_50580202_18_dialog_content = "Dan banyak turis menghabiskan uang yang cukup untuk soft opening kami hanya untuk kesempatan melihatnya sebelum orang lain.",
  ui_story_5058_50580202_19_dialog_content = "Terima kasih kepada PlayerName, kami tidak perlu menghabiskan apa pun! Tapi aku bertanya-tanya apakah kita akan melihatnya kali ini...",
  ui_story_5058_50580202_20_dialog_content = "Jika itu nyata, kenapa tidak langsung ditampilkan ke publik?",
  ui_story_5058_50580202_21_dialog_content = "Semua sensasi itu hanya untuk ditinggalkan pada pertemuan kebetulan... Itu terdengar seperti penipuan bagi saya.",
  ui_story_5058_50580202_22_dialog_content = "Oh, kamu pasti Caelestite yang Cena sebutkan. Aku bisa melihatmu dari jauh di keramaian!",
  ui_story_5058_50580202_23_dialog_content = "Mengapa kamu menggosok mata? Apakah sakit atau ada masalah lain?",
  ui_story_5058_50580202_24_dialog_content = "Nah, eh...",
  ui_story_5058_50580202_25_dialog_content = "Sepertinya ini kali pertama Anda mencoba bungee jumping.",
  ui_story_5058_50580202_26_dialog_content = "Pertama kali mungkin sedikit tidak nyaman. Apakah orang-orang di sebelah kamu itu keluarga atau teman? Mengapa mereka terlihat begitu acuh tak acuh?",
  ui_story_5058_50580202_27_dialog_content = "Kasihan. Nah, karena mereka tidak peduli tentang kamu... mari kita beri kamu pijat yang menenangkan dan membantu kamu rileks.",
  ui_story_5058_50580202_28_dialog_content = "T-Tidak apa-apa, terima kasih...",
  ui_story_5058_50580202_29_dialog_content = "Santai saja! Kemampuan pijat kami sangat hebat.",
  ui_story_5058_50580202_30_dialog_content = "V-Vice, Carleen... Apakah salah satu dari kalian...",
  ui_story_5058_50580202_31_dialog_content = "Aku penasaran kemana wanita-wanita itu pergi. Kamu tidak bisa hanya menguasai mereka untuk dirimu sendiri, PlayerName!",
  ui_story_5058_50580202_32_dialog_content = "Apa kabar, manis? Apakah kamu cemburu?",
  ui_story_5058_50580202_33_dialog_content = "Huh, tak pernah menyangka akan ada hari di mana aku menjadi yang terbaik kedua.",
  ui_story_5058_50580202_34_dialog_content = "Ayo, sejak kapan kamu mulai bertindak posesif? Di sini, biarkan aku memberimu pijatan juga, oke?",
  ui_story_5058_50580202_35_dialog_content = "Aku tahu aku adalah favorit Lina...",
  ui_story_5058_50580202_36_dialog_content = "S-Selamatkan aku, Cena...",
  ui_story_5058_50580202_37_dialog_content = "Apa itu, PlayerName? Kamu akan membuat wanita merasa tidak enak.",
  ui_story_5058_50580202_38_dialog_content = "Apa yang kau bicarakan? Saya bahkan tidak tahu siapa mereka!",
  ui_story_5058_50580202_39_dialog_content = "Kamu hanya ingin tahu nama mereka. Hahaha, aku harus mengakomodasi kamu.",
  ui_story_5058_50580202_40_dialog_content = "Saya bertemu ketiga wanita tersebut pada perjalanan sebelumnya. Mereka semua suka bepergian.",
  ui_story_5058_50580202_41_dialog_content = "Jangan tertipu oleh sopan santun mereka. Mereka sangat pemilih dalam hal perjalanan.",
  ui_story_5058_50580202_42_dialog_content = "Itulah mengapa saya secara khusus mengundang mereka ke resor sebagai konsultan.",
  ui_story_5058_50580202_43_dialog_content = "Wanita berpenutup kepala itu adalah Winona. Kami menghabiskan banyak waktu bersama di Northland mencari-cari reruntuhan kuno. Kami sangat akrab satu sama lain.",
  ui_story_5058_50580202_44_dialog_content = "Winona bertindak sebagai konsultan keamanan kami.",
  ui_story_5058_50580202_45_dialog_content = "Senang berkenalan denganmu.",
  ui_story_5058_50580202_46_dialog_content = "Pijat dengan tangan yang luar biasa itu adalah Lastelle. Saya pernah mengawalnya sebelumnya ketika saya bekerja sebagai pengaman rahasia di Lumopolis.",
  ui_story_5058_50580202_47_dialog_content = "Lastelle adalah konsultan perhotelan yang mengkhususkan diri dalam relaksasi. Selain itu—",
  ui_story_5058_50580202_48_dialog_content = "Baiklah, itu sudah cukup. Jangan ungkap semua rahasia, sayang. Itu hanya akan menghilangkan elemen kejutan.",
  ui_story_5058_50580202_49_dialog_content = "Ketika saya menjadi pembersih di pedesaan Umbraton, saya menyelamatkan Lina dari tiga puluh pembunuh bayaran. Dia adalah konsultan kuliner kami.",
  ui_story_5058_50580202_50_dialog_content = "Saya tidak tahu mengapa begitu banyak orang mencoba membunuh Lina. Dia jelas wanita paling baik hati dan lembut yang pernah saya temui.",
  ui_story_5058_50580202_51_dialog_content = "Hee-hee... Cena, kamu selalu berhasil membuat kesan dengan kata-kata halusmu, ya?",
  ui_story_5058_50580202_52_dialog_content = "Jangan hanya berdiri di sana! Sekarang kamu di sini, ayo kita lanjut ke bagian yang seru!",
  ui_story_5058_50580202_53_dialog_content = "Kau benar. Setelah semua pembicaraan itu, kita harus melihat-lihat atraksinya!",
  ui_story_5058_50580202_54_dialog_content = "Mengapa kita tidak mencoba sesuatu yang lebih santai... Seperti bianglala di sana?",
  ui_story_5058_50580202_55_dialog_content = "Tetapi... Saya memiliki bianglala terakhir di dalam rencana perjalanan.",
  ui_story_5058_50580202_56_dialog_content = "Pemandangan dari sini bahkan lebih indah di malam hari karena adanya kembang api malam!",
  ui_story_5058_50580202_57_dialog_content = "Kembang api dari atas bianglala? Betapa romantis!",
  ui_story_5058_50580202_58_dialog_content = "Kembang api, hah...",
  ui_story_5058_50580202_59_dialog_content = "Apa yang salah, Cena? Kamu tidak suka pertunjukan kembang api?",
  ui_story_5058_50580202_60_dialog_content = "Tidak... Saya, eh, hanya...",
  ui_story_5058_50580202_61_dialog_content = "Baru saja terpikirkan tempat yang sangat spesial di pikiran yang ingin saya ajak wanita-wanita ke sana.",
  ui_story_5058_50580202_62_dialog_content = "Semoga kamu tidak mengecewakanku nanti.",
  ui_story_5058_50580202_63_dialog_content = "Tentu saja tidak. Ikuti saya, wanita-wanita cantikku!",
  ui_story_5058_50580202_64_dialog_content = "D-Dia pergi, begitu saja?",
  ui_story_5058_50580202_65_dialog_content = "Tidak apa-apa. Cena mungkin mengatakan hal-hal yang tidak pantas, tapi dia tetap orang yang dapat diandalkan!",
  ui_story_5058_50580202_66_dialog_content = "Dia membantu Lorelei memulihkan ekologi di Lembah Denuo agar resor dapat meluncurkan.",
  ui_story_5058_50580202_67_dialog_content = "Kembalikan ekologi?",
  ui_story_5058_50580202_68_dialog_content = "Tidak lama yang lalu, Lembah Denuo masih tandus.",
  ui_story_5058_50580202_69_dialog_content = "Tetapi Lorelei fokus pada tanah tersebut, menginvestasikan jumlah besar untuk meningkatkan lingkungan dan mengembalikannya seperti dulu.",
  ui_story_5058_50580202_70_dialog_content = "Sepertinya itu banyak pekerjaan.",
  ui_story_5058_50580202_71_dialog_content = "Dan Cena selalu dapat menemukan solusi untuk menyelesaikan setiap permintaan gila dari Lorelei.",
  ui_story_5058_50580202_72_dialog_content = "Even Sinsa cukup menyukai dia untuk mencoba merekrutnya...",
  ui_story_5058_50580202_73_dialog_content = "Tidakkah Sinsa mengatakan itu kepada siapa pun yang ia temui?",
  ui_story_5058_50580202_74_dialog_content = "Tapi meskipun begitu... Oke, mungkin saya seharusnya tidak menilai buku dari covernya.",
  ui_story_5058_50580202_75_dialog_content = "<color=#e8d9bb>Bercipratan—</color>",
  ui_story_5058_50580202_76_dialog_content = "Jadi, ini kah tempat spesial yang kamu bicarakan?",
  ui_story_5058_50580202_77_dialog_content = "Ya. Bukankah kalian wanita lebih suka berenang dan berjemur di tempat yang tenang?",
  ui_story_5058_50580202_78_dialog_content = "Kebanyakan tamu berada di taman hiburan, jadi hampir tidak ada orang di Kolam Oasis. Silakan menikmati waktu Anda.",
  ui_story_5058_50580202_79_dialog_content = "Cena, kenapa tidak ikut berenang bersama kami juga?",
  ui_story_5058_50580202_80_dialog_content = "Terima kasih, tapi saya harus pergi untuk saat ini.",
  ui_story_5058_50580202_81_dialog_content = "Rapat Miss Lorelei hampir selesai. Saya harus segera mencari tahu hasilnya.",
  ui_story_5058_50580202_82_dialog_content = "Astaga. Cena, sejak kapan kamu mulai menyukai gadis-gadis yang lebih muda?",
  ui_story_5058_50580202_83_dialog_content = "Aku bisa mengerti jika itu datang dari orang lain, tapi jangan bilang kamu masih belum tahu selera ku?",
  ui_story_5058_50580202_84_dialog_content = "Saya hanya seorang karyawan yang ingin membuat bos senang agar bisa menghasilkan uang besar untuk memanjakanmu!",
  ui_story_5058_50580202_85_dialog_content = "Sungguh?",
  ui_story_5058_50580202_86_dialog_content = "Cena, jelas ada sesuatu di pikiranmu yang tidak ingin kamu bagikan dengan kami.",
  ui_story_5058_50580202_87_dialog_content = "Nah, kapanpun kamu mau, kamu bisa datang ke kami dan ngobrol, oke?",
  ui_story_5058_50580202_88_dialog_content = "Tentu. Nikmati dan bersenang-senang, wanita. Tentu saja, jangan pelit dalam memberikan kritik dan saran!",
  ui_story_5058_50580301_1_dialog_content = "Hei, ini jarang, sudah lama aku nggak lihat kamu sedih seperti ini.",
  ui_story_5058_50580301_2_dialog_content = "Apa yang dikatakan investor dalam rapat dewan?",
  ui_story_5058_50580301_3_dialog_content = "Pernahkah kamu mendengar tentang <color=#FFB400>Denuo Incense</color>?",
  ui_story_5058_50580301_4_dialog_content = "Denuo Incense...",
  ui_story_5058_50580301_5_dialog_content = "Hmm, tidak bisa bilang pernah sebelumnya.",
  ui_story_5058_50580301_6_dialog_content = "Jadi bahkan kamu juga tidak tahu tentang itu? Papan bilang itu adalah rempah khusus di Denuo dan pernah menjadi tren besar.",
  ui_story_5058_50580301_7_dialog_content = "Mereka ingin kita memproduksi dan mendorongnya ke bulan sebagai produk bintang dari resor tersebut, sehingga kita akan mendapatkan bisnis berulang.",
  ui_story_5058_50580301_8_dialog_content = "Wow, itu akan sulit... Apa yang kamu katakan pada mereka?",
  ui_story_5058_50580301_9_dialog_content = "Saya akan mempertimbangkannya. Anda tahu sendiri bagaimana mereka telah mendorong saya untuk mengembangkan resor dan mengembangkan lebih banyak area di The Valley dalam fase dua.",
  ui_story_5058_50580301_10_dialog_content = "Tapi mereka berjanji padaku bahwa jika kita memproduksi Dupa Denuo, mereka akan berhenti mengganggu pengembangan di masa depan.",
  ui_story_5058_50580301_11_dialog_content = "Itu terdengar sangat menggoda, mengingat pembatasan dan syarat yang mereka minta saat kita memulai proyek.",
  ui_story_5058_50580301_12_dialog_content = "Namun, mereka juga tidak menawarkan bantuan tentang cara membuat dupa tersebut.",
  ui_story_5058_50580301_13_dialog_content = "Berbicara tentang itu, Denuo Village sempat berdagang dengan dunia luar untuk sementara waktu. Maymungkin ada seseorang di sana yang membuatnya.",
  ui_story_5058_50580301_14_dialog_content = "Tapi desa itu sudah lama hilang sekarang. Bagaimana kita akan menemukan rumusnya?",
  ui_story_5058_50580301_15_dialog_content = "Itu benar…",
  ui_story_5058_50580301_16_dialog_content = "Jangan khawatir, saya juga mengutak-atik rempah-rempah. Maymungkin saya bisa mencobanya.",
  ui_story_5058_50580301_17_dialog_content = "Kamu bahkan tahu tentang rempah-rempah? Bagaimana nasib resor tanpa kamu!",
  ui_story_5058_50580301_18_dialog_content = "Haha, semoga aku bisa mengeluarkan kelinci dari topi.",
  ui_story_5058_50580301_19_dialog_content = "Kumohon! Even meskipun tidak sempurna, ini tetap akan memberi manfaat bagi lembah.",
  ui_story_5058_50580301_20_dialog_content = "Kita tidak bisa meninggalkan rencana pemasaran awal kita, bagaimanapun. Caelestite masih menjadi fokus.",
  ui_story_5058_50580301_21_dialog_content = "Apa, kamu tidak memenangkan stiker Dewi Denuo pada Naga Malam Putih?",
  ui_story_5058_50580301_22_dialog_content = "...",
  ui_story_5058_50580301_23_dialog_content = "Carleen terlihat agak pucat... Apakah roller coaster terlalu menakutkan untukmu?",
  ui_story_5058_50580301_24_dialog_content = "Bagaimana mungkin seseorang bisa menangani bungee jump tapi tidak roller coaster?",
  ui_story_5058_50580301_25_dialog_content = "Maysepertinya ada masalah dengan rencana perjalanan. Seharusnya saya memisahkan kategorinya...",
  ui_story_5058_50580301_26_dialog_content = "Tapi Fantasy Matrix yang akan datang selanjutnya seharusnya menawarkan sensasi yang benar-benar berbeda!",
  ui_story_5058_50580301_27_dialog_content = "Fantasy Matrix? Akhirnya, itu terdengar seperti perjalanan yang sederhana dan mudah. Di mana itu?",
  ui_story_5058_50580301_28_dialog_content = "Ta-ra! Tepat di depan kita. Lihat ke atas, PlayerName!",
  ui_story_5058_50580301_29_dialog_content = "Lihat ke atas...?",
  ui_story_5058_50580301_30_dialog_content = "Astaga... Ngomong-ngomong soal gergaji raksasa! Itu jalan-jalan? Yang benar?",
  ui_story_5058_50580301_31_dialog_content = "Ya, Sinsa yang mendesain ini, dan seperti yang dia dulu katakan...",
  ui_story_5058_50580301_32_dialog_content = "Baiklah, kalian bajingan, siap-siap terkena gergaji jika tidak cukup cepat untuk menghindar!",
  ui_story_5058_50580301_33_dialog_content = "Eve? Tidak, itu tidak berlaku untuk kamu, Eve...!",
  ui_story_5058_50580301_34_dialog_content = "Ya, itu sesuatu yang akan dia katakan.",
  ui_story_5058_50580301_35_dialog_content = "Ini gampang banget. Aku paham ini lebih banyak stiker untuk aku.",
  ui_story_5058_50580301_36_dialog_content = "Itulah Carleen yang aku tahu. Oke, ayo kita mulai, aku tidak sabar!",
  ui_story_5058_50580301_37_dialog_content = "Jadi, sebelum kita mulai, jangan lupa langkah-langkah keselamatan!",
  ui_story_5058_50580301_38_dialog_content = "<color=#e8d9bb>Bergegas—</color>",
  ui_story_5058_50580301_39_dialog_content = "Cepatlah, Carleen, atau aku akan mengalahkanmu!",
  ui_story_5058_50580301_40_dialog_content = "Aku sudah siap. Kamu hati-hati saja!",
  ui_story_5058_50580301_41_dialog_content = "Hei, tunggu aku... Kenapa aku ditinggal lagi?",
  ui_story_5058_50580301_42_dialog_content = "Hei, kalian—",
  ui_story_5058_50580301_43_dialog_content = "Mereka semua pergi... Sepertinya aku akan berjalan-jalan sendirian.",
  ui_story_5058_50580301_44_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_5058_50580301_45_dialog_content = "Beri tepuk tangan untuk penembak terbaik dalam pertandingan ini: Miss Smokey!",
  ui_story_5058_50580301_46_dialog_content = "Selamat, Anda baru saja memenangkan stiker Dewi Denuo lainnya, 'ol Direktur hebat Smokey!",
  ui_story_5058_50580301_47_dialog_content = "Kamu membiarkan aku mengambil dua tembakan terakhir, bukan, <color=#FFB400>Shashona</color>?",
  ui_story_5058_50580301_48_dialog_content = "Apa? Tidak mungkin! Kamu seorang penembak jitu muda, Direktur Smokey. Aku hanya mengelabui sedikit.",
  ui_story_5058_50580301_49_dialog_content = "Seperti kamu mungkin juga bisa mengakali sedikit pada Dewan Direksi.",
  ui_story_5058_50580301_50_dialog_content = "Ah, aku paham tentang apa ini.",
  ui_story_5058_50580301_51_dialog_content = "Nah, Dewan memberi tekanan pada Lorelei untuk mengembangkan proyek.",
  ui_story_5058_50580301_52_dialog_content = "Tapi seperti yang diketahui setiap pengusaha, terburu-buru membuat sia-sia.",
  ui_story_5058_50580301_53_dialog_content = "Mengapa kita tidak bisa membangun merek resor, lalu menginvestasikan kembali uangnya ke lebih banyak proyek?",
  ui_story_5058_50580301_54_dialog_content = "Saya hampir tidak tertarik menjalankan bisnis atau mendengarkan saran mereka.",
  ui_story_5058_50580301_55_dialog_content = "Selama wahana cukup seru dan menyenangkan untuk saya, saya tidak peduli tentang sisanya.",
  ui_story_5058_50580301_56_dialog_content = "Mengenai hal itu, semua atraksi tidak cukup menantang. Pastikan kamu memberi tahu Lorelei...",
  ui_story_5058_50580301_57_dialog_content = "Buat semuanya lebih sulit dan tambahkan lebih banyak trik penilaian. Tidak semua harus menembak Eclipsite besar seperti Halo Shots. Itu membosankan.",
  ui_story_5058_50580301_58_dialog_content = "Menurutmu begitu? Aku pikir seru bermain itu bersamamu. Putaran lagi?",
  ui_story_5058_50580301_59_dialog_content = "Sasaran terlihat—",
  ui_story_5058_50580301_60_dialog_content = "Target apa? Aku?",
  ui_story_5058_50580301_61_dialog_content = "Sedang apa kau di sini?",
  ui_story_5058_50580301_62_dialog_content = "Saya mendapat undangan dari Lorelei untuk awal pembukaan. Kamu juga dapat satu?",
  ui_story_5058_50580301_63_dialog_content = "Tidak seperti kamu, saya adalah Direktur untuk resor ini, di sini untuk meninjau kemajuan.",
  ui_story_5058_50580301_64_dialog_content = "Kau... anggota Dewan Direksi?",
  ui_story_5058_50580301_65_dialog_content = "Mengapa itu kejutan? Tentu, saya belum pernah melakukannya, tetapi saya pikir akan menarik untuk berinvestasi di resor.",
  ui_story_5058_50580301_66_dialog_content = "Dan baru saja saya menang di kasino dengan uang yang terbakar di kantong, jadi sebaiknya saya menghabiskannya.",
  ui_story_5058_50580301_67_dialog_content = "Terasa sangat bagus menjadi kaya...",
  ui_story_5058_50580301_68_dialog_content = "Apa kamu... si Caelestite? Saya terkesan bahwa Lorelei berhasil membawa kamu ke sini.",
  ui_story_5058_50580301_69_dialog_content = "Uh, kamu terlalu baik. Panggil saja aku PlayerName.",
  ui_story_5058_50580301_70_dialog_content = "Keren! Senang bertemu denganmu, PlayerName, aku Shashona.",
  ui_story_5058_50580301_71_dialog_content = "Silakan menikmati! Mari kita bicara lagi setelah Anda mencoba semua wahana.",
  ui_story_5058_50580301_72_dialog_content = "Dewan seharusnya sangat tertarik dengan komentar dari PlayerName, bukan?",
  ui_story_5058_50580301_73_dialog_content = "Ngomong-ngomong, kamu sudah mencoba Fantasy Matrix belum? Sepertinya itu menyenangkan.",
  ui_story_5058_50580301_74_dialog_content = "Mengapa semua orang menginginkan itu? Saya lebih suka mencoba hal lain.",
  ui_story_5058_50580301_75_dialog_content = "Nah, coba ini. Ini tidak sulit dan seharusnya mudah untukmu.",
  ui_story_5058_50580301_76_dialog_content = "Cukup arahkan senjata ke Eclipsite dan tembak saja.",
  ui_story_5058_50580301_77_dialog_content = "<color=#e8d9bb>Der, der!</color>",
  ui_story_5058_50580301_78_dialog_content = "Wah, sudah mulai? Ngomong-ngomong, Eclipsite itu nyata banget lho!",
  ui_story_5058_50580301_79_dialog_content = "Ini adalah kontes. Jika kamu menang, kamu bisa naik Fantasy Matrix bersamaku!",
  ui_story_5058_50580301_80_dialog_content = "Tidak, tidak apa-apa, yang saya inginkan hanya stiker...",
  ui_story_5058_50580402_1_dialog_content = "Hei, kau membuatku terkesan sejak terakhir kali aku melihatmu! Meskipun kamu tidak di liga ku.",
  ui_story_5058_50580402_2_dialog_content = "Uh, saya yakin sangat sedikit orang yang bisa menembak lebih baik darimu.",
  ui_story_5058_50580402_3_dialog_content = "Saya bermain dengan hampir semua hal dan mendapatkan semua stiker... Apa lagi yang harus dilakukan?",
  ui_story_5058_50580402_4_dialog_content = "Ada banyak fasilitas hotel yang layak untuk dicoba. Bagaimana dengan mencoba pijat minyak?",
  ui_story_5058_50580402_5_dialog_content = "Saya mengirim Lorelei untuk memohon Sang Guru di tempat paling terkenal agar membuat esensi khusus untuk resor. Kamu tidak bisa mendapatkan itu di tempat lain.",
  ui_story_5058_50580402_6_dialog_content = "Tentu, akan kuperiksa. Sampai jumpa.",
  ui_story_5058_50580402_7_dialog_content = "Apakah kamu juga tertarik, teman lama dari Smokey?",
  ui_story_5058_50580402_8_dialog_content = "Yah, kita memang teman, tapi mungkin belum cukup dekat untuk pijat bersama...",
  ui_story_5058_50580402_9_dialog_content = "Heheh, nggak ada masalah. Teman-teman sering pergi ke hot-tub, apalagi pijat.",
  ui_story_5058_50580402_10_dialog_content = "Maykamu bahkan bisa membahas kolaborasi potensial...",
  ui_story_5058_50580402_11_dialog_content = "Wow, kamu masih memikirkan bisnis di pusat kotamu... Jauh lebih seperti direktur daripada Smokey.",
  ui_story_5058_50580402_12_dialog_content = "Terima kasih atas pujian, tetapi saya bukan direktur, hanya kerabat dari Lorelei, untuk memberikan uluran bantuan.",
  ui_story_5058_50580402_13_dialog_content = "Kerabat Lorelei, saya mengerti...",
  ui_story_5058_50580402_14_dialog_content = "PlayerName!",
  ui_story_5058_50580402_15_dialog_content = "Ini dia! Tidak ada yang bisa menemukan kamu dan kami khawatir...",
  ui_story_5058_50580402_16_dialog_content = "Oh, maaf. Ketika kamu naik ke Fantasy Matrix, aku—",
  ui_story_5058_50580402_17_dialog_content = "... Sedang apa kau di sini?",
  ui_story_5058_50580402_18_dialog_content = "Oh, Laurie, kenapa kamu tidak memberi tahu aku bahwa resor sudah buka?",
  ui_story_5058_50580402_19_dialog_content = "Jumlah tamu tampaknya rendah untuk operasi skala ini.",
  ui_story_5058_50580402_20_dialog_content = "Ini hanya pembukaan lembut sebelum pembukaan besar yang sesungguhnya. Everyone di sini hanya untuk undangan saja.",
  ui_story_5058_50580402_21_dialog_content = "Ah, jadi tebakan saya benar bahwa orang ini di sini untuk mempromosikan taman?",
  ui_story_5058_50580402_22_dialog_content = "Kamu mendapatkan izin untuk menjadikan Caelestite sebagai juru bicara taman.",
  ui_story_5058_50580402_23_dialog_content = "Tapi jika kamu memberi tahu saya lebih awal, saya akan datang lebih awal dan secara pribadi menunjukkan PlayerName di sekitar sehingga tidak ada orang yang kesepian...",
  ui_story_5058_50580402_24_dialog_content = "Aku tahu kamu akan melakukan itu, makanya—",
  ui_story_5058_50580402_25_dialog_content = "Lihat warna kulitmu, kamu pasti tidak terhidrasi dengan baik.",
  ui_story_5058_50580402_26_dialog_content = "Saya membawa beberapa suplemen dari rumah. Nanti malam saya akan memasaknya untuk kamu.",
  ui_story_5058_50580402_27_dialog_content = "Mama, tolong jangan membahas itu di depan tamu. Saya sudah cukup dewasa untuk mengurus diri sendiri.",
  ui_story_5058_50580402_28_dialog_content = "(A-Apa? Shashona adalah ibu dari Lorelei?!)",
  ui_story_5058_50580402_29_dialog_content = "Pokoknya, saya harus pergi dan mengantar tamu kita ini untuk mendaftar.",
  ui_story_5058_50580402_30_dialog_content = "Ke sini, silakan, PlayerName.",
  ui_story_5058_50580402_31_dialog_content = "Pelankan, Laurie. Kenapa kamu tidak memakai sepatu yang kupbeli untukmu? Sepatu itu bukan untuk bekerja...",
  ui_story_5058_50580402_32_dialog_content = "Fyuh…",
  ui_story_5058_50580402_33_dialog_content = "Ibu kamu sangat baik padamu, Lorelei.",
  ui_story_5058_50580402_34_dialog_content = "Dia pasti begitu.",
  ui_story_5058_50580501_1_dialog_content = "Oke, kamu sudah selesai check-in.",
  ui_story_5058_50580501_2_dialog_content = "Terima kasih, Lorelei.",
  ui_story_5058_50580501_3_dialog_content = "Sebagai bagian dari pekerjaan saya, dan sejujurnya, saya harus melakukan lebih banyak lagi karena kamu adalah VIP utama kami.",
  ui_story_5058_50580501_4_dialog_content = "Hmm, apakah saya sudah menjelaskan fitur fasilitas hotel kepada kamu?",
  ui_story_5058_50580501_5_dialog_content = "Ahem, selain kamar tamu yang nyaman dan hangat, hotel ini juga memiliki gym, kolam renang, mata air panas, spa...",
  ui_story_5058_50580501_6_dialog_content = "Terdapat tanda di tangga setiap level, jadi tidak perlu khawatir tentang tersesat.",
  ui_story_5058_50580501_7_dialog_content = "Interior juga dilengkapi dengan sistem ventilasi terbaru, jadi saat cuaca buruk seperti badai pasir, kami akan menjalankannya untuk menyediakan udara segar.",
  ui_story_5058_50580501_8_dialog_content = "Kamu tidak akan mengalami ketidaknyamanan selama menginap jangka panjang.",
  ui_story_5058_50580501_9_dialog_content = "Juga, sarapan dan makan siang disajikan dengan gaya prasmanan, cukup pergi ke restoran dan kamu akan baik-baik saja...",
  ui_story_5058_50580501_10_dialog_content = "PlayerName!",
  ui_story_5058_50580501_11_dialog_content = "Kemana kamu? Kami tidak bisa menemukanmu setelah kami turun dari wahana.",
  ui_story_5058_50580501_12_dialog_content = "Maaf tentang itu... Saya sedang mencoba Halo Shots dan bertemu dengan seorang wanita bernama Shashona.",
  ui_story_5058_50580501_13_dialog_content = "Jadi Shashona di sini.",
  ui_story_5058_50580501_14_dialog_content = "Kamu kenal dia?",
  ui_story_5058_50580501_15_dialog_content = "Bagaimana ya menjelaskannya... Dia bukan seseorang yang bisa kita anggap remeh.",
  ui_story_5058_50580501_16_dialog_content = "Mengapa? Apakah dia orang penting?",
  ui_story_5058_50580501_17_dialog_content = "Shashona sebenarnya adalah ibu Lorelei.",
  ui_story_5058_50580501_18_dialog_content = "Ibu dari Lorelei juga di sini? Bagaimana kita bisa merayakan waktu Lorelei dalam hal ini?",
  ui_story_5058_50580501_19_dialog_content = "Yah, kita harus bersyukur memiliki Bopper bersama kita.",
  ui_story_5058_50580501_20_dialog_content = "Ehem... Terima kasih, semua. Harap ketahui bahwa misi saya adalah untuk memberikan layanan berkualitas kepada para tamu kami. Sedangkan untuk ibu saya... Sebenarnya, dia sering datang untuk menjenguk saya.",
  ui_story_5058_50580501_21_dialog_content = "Oh, dan aku ingin tahu bagaimana perasaanmu tentang atraksi-atraksi tersebut?",
  ui_story_5058_50580501_22_dialog_content = "Sejujurnya, banyak dari hal-hal tersebut terlalu berlebihan untukku.",
  ui_story_5058_50580501_23_dialog_content = "Saya rasa mereka sangat menyenangkan. Saya banyak bersenang-senang.",
  ui_story_5058_50580501_24_dialog_content = "Saya bisa tahu... Tapi saya merasa lelah hanya dengan melihat mereka dan ingin istirahat sekarang juga.",
  ui_story_5058_50580501_25_dialog_content = "Ah, ah, begitu rupanya.",
  ui_story_5058_50580501_26_dialog_content = "Dewan Direksi selalu menginginkan lebih banyak wahana seru. Aku paham kita perlu lebih banyak atraksi untuk semua usia.",
  ui_story_5058_50580501_27_dialog_content = "(Orang dari segala usia? Kita seumuran...!)",
  ui_story_5058_50580501_28_dialog_content = "Terima kasih atas masukan yang berharga, PlayerName!",
  ui_story_5058_50580501_29_dialog_content = "Apakah semua orang lain berhenti untuk saat ini, atau harus kita lanjutkan untuk melihat wahana?",
  ui_story_5058_50580501_30_dialog_content = "Kami berlari cukup banyak dan saya merasa sedikit lelah.",
  ui_story_5058_50580501_31_dialog_content = "Iya, setuju... Tapi kita belum mengumpulkan semua stiker Dewi Denuo lho!",
  ui_story_5058_50580501_32_dialog_content = "Tidak apa-apa, kamu masih punya beberapa hari lagi untuk melakukannya.",
  ui_story_5058_50580501_33_dialog_content = "Keren, aku ingin mengumpulkan semua stiker Dewi Denuo yang cantik!",
  ui_story_5058_50580501_34_dialog_content = "Ngomong-ngomong soal itu, kalian mau ikut jalan-jalan keliling lembah?",
  ui_story_5058_50580501_35_dialog_content = "Ini memiliki banyak kupu-kupu, dan mungkin kita akan melihat Dewi Denuo yang sebenarnya!",
  ui_story_5058_50580501_36_dialog_content = "Saat kamu istirahat, nanti aku bisa ajak kamu melihat-lihat The Valley.",
  ui_story_5058_50580501_37_dialog_content = "Area ini masih belum dikembangkan tetapi bisa menjadi bagian dari resor di masa depan.",
  ui_story_5058_50580501_38_dialog_content = "Bagus! Perjalanan ini akan lebih berharga jika kita melihat Dewi Denuo!",
  ui_story_5058_50580501_39_dialog_content = "Mengapa kita tidak pergi sekarang?",
  ui_story_5058_50580501_40_dialog_content = "Aku setuju.",
  ui_story_5058_50580501_41_dialog_content = "Kamu tidak ingin istirahat sebentar?",
  ui_story_5058_50580501_42_dialog_content = "Kami dengar Nona Lorelei menghabiskan banyak tenaga untuk mengubah Lembah Denuo menjadi hijau.",
  ui_story_5058_50580501_43_dialog_content = "Saya menjadi bersemangat hanya dengan membayangkan pemandangan hijau dan subur!",
  ui_story_5058_50580501_44_dialog_content = "Iya, aku juga.",
  ui_story_5058_50580501_45_dialog_content = "Aku tahu. Kenapa tidak, ayo berangkat sekarang!",
  ui_story_5058_50580501_46_dialog_content = "<color=#e8d9bb>Setelah beberapa saat...</color>",
  ui_story_5058_50580501_47_dialog_content = "Bernapas...",
  ui_story_5058_50580501_48_dialog_content = "Udara sangat bersih. Aku menghirup dalam-dalam, dan bahkan mulutku pun terasa segar.",
  ui_story_5058_50580501_49_dialog_content = "Aroma menyenangkan rumput mengingatkan saya akan Eraveil.",
  ui_story_5058_50580501_50_dialog_content = "Ya, tanaman tampak tumbuh secara alami tanpa tanda-tanda kebuatan.",
  ui_story_5058_50580501_51_dialog_content = "Itulah yang seharusnya menjadi alam. Cukup tanam benih, beri nutrisi, dan mereka akan membuat kita terkejut.",
  ui_story_5058_50580501_52_dialog_content = "Ini sangat mengesankan, Lorelei, membangun resor seperti ini di Rediesel Desert. Tapi darimana ide ini muncul?",
  ui_story_5058_50580501_53_dialog_content = "Lembah Denuo sendiri memiliki hambatan geografis untuk mengisolasi serangan Eclipsite.",
  ui_story_5058_50580501_54_dialog_content = "Dan landscape alam di sini benar-benar berbeda dari tempat wisata lainnya di Astra.",
  ui_story_5058_50580501_55_dialog_content = "Dengan demikian, sebuah resor akan menyediakan pengalaman yang berbeda bagi pengunjung.",
  ui_story_5058_50580501_56_dialog_content = "Ini juga tempat yang sangat penting bagi aku. Keinginanku untuk membangkitkan sekitarnya...",
  ui_story_5058_50580501_57_dialog_content = "...",
  ui_story_5058_50580501_58_dialog_content = "Aku mengerti perasaanmu. Itu persis seperti yang aku rasakan tentang Eraveil.",
  ui_story_5058_50580501_59_dialog_content = "(Apakah itu berarti ini adalah tempat asal Lorelei?)",
  ui_story_5058_50580501_60_dialog_content = "Pidato bagus, tapi Nyonya Lorelei adalah seorang pengusaha di hati, jadi semuanya tentang keuntungan.",
  ui_story_5058_50580501_61_dialog_content = "Tentu saja. Saya sangat yakin dengan proyek ini!",
  ui_story_5058_50580501_62_dialog_content = "Hei, aku lihat kupu-kupu.",
  ui_story_5058_50580501_63_dialog_content = "Ya! Aku juga melihat beberapa di sana!",
  ui_story_5058_50580501_64_dialog_content = "Saya penasaran apakah Dewi Denuo ada di antara mereka.",
  ui_story_5058_50580501_65_dialog_content = "Nona Lorelei, b-bisakah saya mencari Dewi Denuo?",
  ui_story_5058_50580501_66_dialog_content = "Kamu bahkan sudah siap dengan jaring, Bopper?!",
  ui_story_5058_50580501_67_dialog_content = "Banyak orang yang bertanya padaku apakah benar Dewi Denuo ada di lembah itu... Aku ingin membuktikannya kepada mereka!",
  ui_story_5058_50580501_68_dialog_content = "Baiklah, tapi jika kamu menemui mereka, hati-hati untuk tidak menyakiti mereka.",
  ui_story_5058_50580501_69_dialog_content = "Mengapa kita tidak melihat juga? Ada kekuatan dalam jumlah!",
  ui_story_5058_50580501_70_dialog_content = "Kita bahkan bisa berpisah untuk menjangkau lebih banyak area!",
  ui_story_5058_50580501_71_dialog_content = "Kamu menjadikannya kompetisi lain, bukan?",
  ui_story_5058_50580501_72_dialog_content = "Heehee, jangan lihat aku seperti itu... Kenapa tidak aku bergabung dengan Carleen kali ini saja?",
  ui_story_5058_50580501_73_dialog_content = "Ayo, mari pergi! Mari kita lihat siapa yang menemukan Dewi pertama kali!",
  ui_story_5058_50580501_74_dialog_content = "Hoamm—",
  ui_story_5058_50580501_75_dialog_content = "Anak-anak... Hari yang indah seperti ini sangat cocok untuk tidur siang.",
  ui_story_5058_50580501_76_dialog_content = "Zzzz—Zzzz—",
  ui_story_5058_50580501_77_dialog_content = "Kemari, Carleen, Aku menemukannya!",
  ui_story_5058_50580501_78_dialog_content = "Begitu cepat?",
  ui_story_5058_50580501_79_dialog_content = "Ta-ra!",
  ui_story_5058_50580501_80_dialog_content = "Hah? Apa itu?",
  ui_story_5058_50580501_81_dialog_content = "Saya belum pernah melihat ngengat sebesar ini sebelumnya!",
  ui_story_5058_50580501_82_dialog_content = "Tinggal jauh dari saya!!!",
  ui_story_5058_50580501_83_dialog_content = "Sudahkah kamu melihat Dewi Denuo, kupu-kupu kecil?",
  ui_story_5058_50580501_84_dialog_content = "Kamu berputar searah jarum jam di sekelilingku... Apa maksudmu?",
  ui_story_5058_50580501_85_dialog_content = "Hmm, sepertinya saya hanya bisa membaca pikiran Lepidoz...",
  ui_story_5058_50580501_86_dialog_content = "Kamu sedang apa, PlayerName?",
  ui_story_5058_50580501_87_dialog_content = "A-Aku hanya menunggu waktu yang tepat...",
  ui_story_5058_50580501_88_dialog_content = "Jangan bergerak... Ada kupu-kupu di kepalamu.",
  ui_story_5058_50580501_89_dialog_content = "Cena, ayo ambil foto kami!",
  ui_story_5058_50580501_90_dialog_content = "Hoamm—",
  ui_story_5058_50580501_91_dialog_content = "Aku datang...",
  ui_story_5058_50580501_92_dialog_content = "<color=#e8d9bb>Jepret!</color>",
  ui_story_5058_50580501_93_dialog_content = "Yah, semua usaha itu dan masih belum ada Dewi Denuo.",
  ui_story_5058_50580501_94_dialog_content = "Saya juga pernah meragukan keberadaan Dewi Denuo, jujur saja.",
  ui_story_5058_50580501_95_dialog_content = "Saya juga tidak yakin. Bukankah kamu bilang pernah melihat satu sebelumnya, Cena?",
  ui_story_5058_50580501_96_dialog_content = "Saya bilang begitu? Tidak begitu ingat...",
  ui_story_5058_50580501_97_dialog_content = "Beberapa orang mengklaim mereka melihat Dewi Denuo, tetapi Dewi sebenarnya lebih merupakan mitos daripada yang lainnya.",
  ui_story_5058_50580501_98_dialog_content = "Banyak investor yang menginvestasikan di resor itu hanya karena mereka mendengar bahwa resor tersebut berada di lembah.",
  ui_story_5058_50580501_99_dialog_content = "Mereka ingin itu menjadi trik untuk menarik wisatawan... Saya tidak bisa menentang keputusan Dewan.",
  ui_story_5058_50580501_100_dialog_content = "Tapi ketika saya menyaksikan cinta dan dukungan yang luar biasa dari para pelanggan untuk stiker Dewi Denuo dan bagaimana mereka bahkan bersedia membayar uang besar hanya untuk melihat satu di sini, itu membuat saya sedikit panik.",
  ui_story_5058_50580501_101_dialog_content = "Karena sejak pembangunan hingga sekarang, tidak ada satupun dari kita yang pernah melihat satu di sini.",
  ui_story_5058_50580501_102_dialog_content = "Jika Dewi Denuo tidak nyata, itu adalah iklan palsu dan saya tidak ingin berbohong kepada para tamu...",
  ui_story_5058_50580501_103_dialog_content = "Tapi jika ini nyata, bukankah apa yang sedang saya lakukan akan menarik mereka yang mungkin membahayakan Dewi...",
  ui_story_5058_50580501_104_dialog_content = "Aku tidak bermaksud menutupinya. Aku hanya tidak bisa menemukan solusi untuk masalah yang rumit ini... Maafkan aku!",
  ui_story_5058_50580501_105_dialog_content = "Kami seharusnya yang meminta maaf karena sikap kami yang ceroboh dan kasar.",
  ui_story_5058_50580501_106_dialog_content = "Tidak masalah. Jika Dewi bisa ditemukan, mungkin kita bisa memperbanyak mereka.",
  ui_story_5058_50580501_107_dialog_content = "Selain itu, saya tahu kamu tidak akan pernah menyakiti kupu-kupu. Dan saya juga menikmati waktu itu.",
  ui_story_5058_50580501_108_dialog_content = "Saya agak cemas tentang orang lain...",
  ui_story_5058_50580501_109_dialog_content = "Saya bisa katakan kamu tidak mudah menyerah, Lorelei. Kita bisa mencari tahu bersama-sama.",
  ui_story_5058_50580501_110_dialog_content = "Ya! Saya telah menemukan seorang ahli binatang yang mungkin dapat memberikan saran bermanfaat.",
  ui_story_5058_50580501_111_dialog_content = "(Ahli binatang? Bukan Vic, bukan?)",
  ui_story_5058_50580501_112_dialog_content = "Saya masih berharap kupu-kupu cantik seperti itu benar-benar nyata.",
  ui_story_5058_50580501_113_dialog_content = "Kupu-kupu pada stiker tersebut konon merupakan yang muda.",
  ui_story_5058_50580501_114_dialog_content = "Kabarnya Dewi-dewi dewasa itu besar, ramping, dan putih di seluruh tubuhnya.",
  ui_story_5058_50580501_115_dialog_content = "Seberapa besar itu? Ukuran kadal, mungkin saja?",
  ui_story_5058_50580501_116_dialog_content = "Teman-teman, lihat semak itu di sana... Apakah itu Dewi Denuo?",
  ui_story_5058_50580501_117_dialog_content = "Di mana?",
  ui_story_5058_50580501_118_dialog_content = "Di sana, sepenuhnya putih...",
  ui_story_5058_50580501_119_dialog_content = "*Meraung*",
  ui_story_5058_50580501_120_dialog_content = "Eclipsite?",
  ui_story_5058_50580501_121_dialog_content = "Bagaimana bisa ada Eclipsite di Lembah Denuo?",
  ui_story_5058_50580502_1_dialog_content = "Oh tidak, aku terpisah...",
  ui_story_5058_50580502_2_dialog_content = "Hiss—",
  ui_story_5058_50580502_3_dialog_content = "Suara berisik apa itu?",
  ui_story_5058_50580502_4_dialog_content = "Mendesis-!",
  ui_story_5058_50580502_5_dialog_content = "PlayerName... PlayerName?",
  ui_story_5058_50580502_6_dialog_content = "Seseorang... memanggil namaku?",
  ui_story_5058_50580502_7_dialog_content = "Ketemu! Nakal kecil! Waktunya pulang sama Mama buat makan malam. Kamu tahu kan orang harus makan biar tumbuh, kanan?",
  ui_story_5058_50580502_8_dialog_content = "I-Ibu…",
  ui_story_5058_50580502_9_dialog_content = "Perasaan ini... Sangat nyaman, hangat, dan akrab...",
  ui_story_5058_50580502_10_dialog_content = "Ikut Mama yuk. Ayo pulang.",
  ui_story_5058_50580502_11_dialog_content = "Tentu saja…",
  ui_story_5058_50580502_12_dialog_content = "... tidak!",
  ui_story_5058_50580502_13_dialog_content = "Saya pikir saya berada di resor...? Dan kita baru saja bertemu dengan Eclipsite, bahkan.",
  ui_story_5058_50580502_14_dialog_content = "Apakah saya sedang bermimpi? Atau mengalami visi?",
  ui_story_5058_50580502_15_dialog_content = "Apa yang salah, PlayerName? Kenapa kamu tidak datang?",
  ui_story_5058_50580502_16_dialog_content = "Aku benar-benar ingin terus bermimpi...",
  ui_story_5058_50580502_17_dialog_content = "Tapi tikus, kenapa aku tidak bisa bangun?",
  ui_story_5058_50580502_18_dialog_content = "Jika ini terus berlanjut, saya hanya bisa...",
  ui_story_5058_50580502_19_option_content = "Force Boost!",
  ui_story_5058_50580502_20_dialog_content = "Hiss—",
  ui_story_5058_50580502_21_dialog_content = "Apakah saya terjaga sekarang?",
  ui_story_5058_50580502_22_dialog_content = "...",
  ui_story_5058_50580502_23_dialog_content = "Siapa kau?",
  ui_story_5058_50580502_24_dialog_content = "<color=#e8d9bb>Wuuss—</color>",
  ui_story_5058_50580502_25_dialog_content = "Kota itu... berpasir dan berdebu... Apakah ini koloni Eclipsite?",
  ui_story_5058_50580502_26_dialog_content = "Apakah saya ada di mimpi orang lain?",
  ui_story_5058_50580502_27_dialog_content = "<color=#e8d9bb>Whoosh—Whoosh—</color>",
  ui_story_5058_50580502_28_dialog_content = "Badai pasir ini... semakin parah...",
  ui_story_5058_50580502_29_dialog_content = "Aku...",
  ui_story_5058_50580502_30_dialog_content = "...tercekik...",
  ui_story_5058_50580601_1_dialog_content = "PlayerName!",
  ui_story_5058_50580601_2_dialog_content = "Ibu...?",
  ui_story_5058_50580601_3_dialog_content = "Bangun, PlayerName!",
  ui_story_5058_50580601_4_dialog_content = "Vice... Carleen... Teman-teman?",
  ui_story_5058_50580601_5_dialog_content = "Bagus, kamu sudah bangun! Maaf meninggalkan kamu di belakang. Kami tidak menyadarinya sampai kami sudah jauh.",
  ui_story_5058_50580601_6_dialog_content = "Maaf, mungkin saya kelelahan karena semua kegiatan hari ini...",
  ui_story_5058_50580601_7_dialog_content = "Saya merasa mengantuk saat berlari dan tidak bisa menahan untuk tidur, bahkan bermimpi aneh yang membuat saya tidak bisa bangun.",
  ui_story_5058_50580601_8_dialog_content = "Kamu bikin aku kaget...",
  ui_story_5058_50580601_9_dialog_content = "Senang melihat PlayerName baik-baik saja. Ini akan menjadi kerugian bagi Astra yang tidak bisa ditutupi bahkan jika saya menjual semua aset saya.",
  ui_story_5058_50580601_10_dialog_content = "Tapi bagaimana bisa ada Eclipsite di sini?",
  ui_story_5058_50580601_11_dialog_content = "Aku juga tidak yakin... Biasanya, ngarai itu cukup kontroversial untuk mereka coba masuki.",
  ui_story_5058_50580601_12_dialog_content = "Saya hanya menyewa tim keamanan kecil untuk berpatroli di sekitar perimeter luar.",
  ui_story_5058_50580601_13_dialog_content = "Saya pikir itu sudah cukup untuk menjaga keamananmu... Maaf sekali!",
  ui_story_5058_50580601_14_dialog_content = "Cena, kita harus segera mendapatkan senjata anti-Eclipsite saat kita kembali.",
  ui_story_5058_50580601_15_dialog_content = "Aku paham. Jadi, apa yang harus kita lakukan sekarang...?",
  ui_story_5058_50580601_16_dialog_content = "Mari kembali ke taman. Kita perlu rencana untuk ini.",
  ui_story_5058_50580601_17_dialog_content = "Graagh!",
  ui_story_5058_50580601_18_dialog_content = "Wah, ini sangat menakutkan!",
  ui_story_5058_50580601_19_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_5058_50580601_20_dialog_content = "Sekali tembak, satu musuh mati!",
  ui_story_5058_50580601_21_dialog_content = "Sekarang itulah yang saya suka dengar! Pertunjukan ini dimulai dengan sangat otentik dan menarik.",
  ui_story_5058_50580601_22_dialog_content = "Sudah mulai acaranya?",
  ui_story_5058_50580601_23_dialog_content = "Pernahkah Anda mendengar sepatah kata pun yang saya katakan, Guru? Saya tidak melihat binatang yang menakjubkan di sini... Seberapa sahkah tugas yang Anda dapatkan ini?",
  ui_story_5058_50580601_24_dialog_content = "Ah, sudahlah. Aku nggak mau buang waktu lagi. Aku akan kembali untuk menonton pertunjukan!",
  ui_story_5058_50580601_25_dialog_content = "Senang rasanya masih muda... Tidak seperti rangka tulang tua yang kumiliki. Lebih baik aku tidur sambil menggunakan bola bulu kecil sebagai bantal.",
  ui_story_5058_50580601_26_dialog_content = "Aahhhh!",
  ui_story_5058_50580601_27_dialog_content = "Wow, Eclipsite kali ini benar-benar terlihat seperti aslinya, bahkan gigi gerahamnya terlihat otentik...",
  ui_story_5058_50580601_28_dialog_content = "Groar!",
  ui_story_5058_50580601_29_dialog_content = "Tidak, Guru bodoh, itu benar-benar Eclipsite!",
  ui_story_5058_50580601_30_dialog_content = "Eclipsite menyerbu taman, memang...",
  ui_story_5058_50580601_31_dialog_content = "Cena, evakuasi tamu-tamu. Bopper, antar setiap orang ke hotel. Aku harus mendapatkan keamanan untuk membuang Eclipsite.",
  ui_story_5058_50580601_32_dialog_content = "Tidak masalah, bos, meskipun Dewan mungkin lebih sulit untuk dihadapi daripada Eclipsite.",
  ui_story_5058_50580601_33_dialog_content = "...",
  ui_story_5058_50580601_34_dialog_content = "Siapa yang berjanji bahwa Eclipsite tidak akan pernah muncul di sini?",
  ui_story_5058_50580601_35_dialog_content = "Kamu berhutang penjelasan kepada kami, Lorelei!",
  ui_story_5058_50580601_36_dialog_content = "Sekarang bukan waktunya untuk membahas masalah itu.",
  ui_story_5058_50580601_37_dialog_content = "Kamu di sini, Lady Carleen?",
  ui_story_5058_50580601_38_dialog_content = "Saya hanya membantu ayah saya dengan investasinya di hari libur saya, tidak lebih!",
  ui_story_5058_50580601_39_dialog_content = "Klarifikasi yang tidak perlu.",
  ui_story_5058_50580601_40_dialog_content = "Eclipsite benar-benar kesalahan dan kelalaian saya, Direktur, tetapi keselamatan Anda adalah kepentingan utama...",
  ui_story_5058_50580601_41_dialog_content = "Silakan ikuti staf kembali ke hotel untuk berlindung. Saya akan mengurus semuanya dan menjelaskannya nanti!",
  ui_story_5058_50580601_42_dialog_content = "Bopper, aku akan tinggalkan PlayerName dan teman-temannya bersamamu.",
  ui_story_5058_50580601_43_dialog_content = "Oke!",
  ui_story_5058_50580601_44_dialog_content = "Tapi kami tidak bisa dan tidak seharusnya meninggalkan kamu menghadapi semua ini sendirian, Lorelei...",
  ui_story_5058_50580601_45_dialog_content = "Ya. Akan jauh lebih cepat bagi kita untuk menghilangkan Eclipsite bersama-sama.",
  ui_story_5058_50580601_46_dialog_content = "Benar, kita semua berpengalaman, kamu tahu!",
  ui_story_5058_50580601_47_dialog_content = "Ini tak terduga. Saya tidak menyangka kamu akan...",
  ui_story_5058_50580601_48_dialog_content = "Hei, apakah itu Vic dan Fia? Mereka juga sedang bertarung!",
  ui_story_5058_50580601_49_dialog_content = "Mari kita singkirkan Eclipsite di sekitar kita, lalu bergabung dengan mereka!",
  ui_story_5058_50580601_50_dialog_content = "Ya!",
  ui_story_5058_50580601_51_dialog_content = "Aku paham bahwa aku terpaksa berjuang bersama kalian para petani demi Lady Carleen.",
  ui_story_5058_50580702_1_dialog_content = "Semua Eclipsite di sekitar segera telah diatasi. Terima kasih semua atas bantuan kalian.",
  ui_story_5058_50580702_2_dialog_content = "Tapi saya harus meminta Anda untuk berlindung di hotel dan biarkan saya mengurus sisanya.",
  ui_story_5058_50580702_3_dialog_content = "Kamu selalu bilang \"Biarkan aku mengurus sisanya\", tapi tidak ada yang sesederhana itu.",
  ui_story_5058_50580702_4_dialog_content = "Shashona...",
  ui_story_5058_50580702_5_dialog_content = "Aku tidak ingin kamu datang ke sini dan membangun resor. Memang benar, sesuatu yang buruk sedang terjadi!",
  ui_story_5058_50580702_6_dialog_content = "Kamu juga melihat wajah para direktur. Mereka tidak yakin kamu bisa melakukannya sama sekali.",
  ui_story_5058_50580702_7_dialog_content = "Lakukan seperti yang saya katakan dan tutup taman sekarang.",
  ui_story_5058_50580702_8_dialog_content = "Mama, bagaimana bisa kamu begitu tidak bertanggung jawab sekarang?",
  ui_story_5058_50580702_9_dialog_content = "Saya tidak bisa meninggalkan staf dan tamu, dan juga tidak bisa mengkhianati para investor.",
  ui_story_5058_50580702_10_dialog_content = "Tahu kah kamu apa yang telah saya lalui untuk membangun resor ini?",
  ui_story_5058_50580702_11_dialog_content = "Kamu ingin aku mematikannya saat akhirnya akan meluncur?",
  ui_story_5058_50580702_12_dialog_content = "Aku tahu kamu telah banyak berkorban, makanya aku merasa ini tidak sebanding!",
  ui_story_5058_50580702_13_dialog_content = "Keluarga akan membantu kamu dalam hal apapun yang ingin kamu lakukan, namun kamu tetap bersikeras untuk pergi sendiri...",
  ui_story_5058_50580702_14_dialog_content = "Jangan khawatirkan aku, Bu. Kembali ke hotel dan saya akan menangani semuanya.",
  ui_story_5058_50580702_15_dialog_content = "Tapi tidak peduli apa pun, saya tidak akan menutup taman ini.",
  ui_story_5058_50580702_16_dialog_content = "Dengarkan aku, Laurie...",
  ui_story_5058_50580702_17_dialog_content = "Nyonya Shashona!",
  ui_story_5058_50580702_18_dialog_content = "Cena ada di sini. Dia bisa mengantarmu. Aku masih punya banyak urusan yang harus diurus.",
  ui_story_5058_50580702_19_dialog_content = "Sudah lama sekali, Nyonya Shashona.",
  ui_story_5058_50580702_20_dialog_content = "...",
  ui_story_5058_50580702_21_dialog_content = "Ini adalah lelucon!",
  ui_story_5058_50580702_22_dialog_content = "Hotelnya ada di sana...",
  ui_story_5058_50580702_23_dialog_content = "Bopper, saya khawatir beberapa tamu mungkin masih berada di taman. Saya akan kirim keamanan untuk memeriksa lagi.",
  ui_story_5058_50580702_24_dialog_content = "Kamu dan staf hotel memeriksa dengan tamu untuk memenuhi kebutuhan mereka.",
  ui_story_5058_50580702_25_dialog_content = "Aku akan menemui kamu setelah aku memeriksa langkah darurat hotel.",
  ui_story_5058_50580702_26_dialog_content = "Hah? Tapi itu bukan di deskripsi pekerjaanku...",
  ui_story_5058_50580702_27_dialog_content = "PlayerName, Vice, Carleen, kalian harus kembali ke kamar masing-masing. Saya akan bertemu kembali dengan kalian setelah keadaan tenang.",
  ui_story_5058_50580702_28_dialog_content = "Anda kekurangan orang saat ini, Nona Lorelei. Mari kami membantu.",
  ui_story_5058_50580702_29_dialog_content = "Saya sendiri tidak ingin diperlakukan seperti turis biasa! Kita mengejar kupu-kupu dan melawan Eclipsite bersama, dan itu membuat kita menjadi teman!",
  ui_story_5058_50580702_30_dialog_content = "Terima kasih, tapi saya harus melakukan ini sendiri. Kamu melihat apa yang terjadi...",
  ui_story_5058_50580702_31_dialog_content = "Karena ibumu keberatan? Saya benar-benar mendapatkan seberapa banyak Anda ingin melakukan ini sendiri.",
  ui_story_5058_50580702_32_dialog_content = "Apakah aku terlalu keras pada ibuku?",
  ui_story_5058_50580702_33_dialog_content = "Ada yang ingin kamu sampaikan, Lorelei? Kami akan mendengarkan kalau kamu tak keberatan...",
  ui_story_5058_50580702_34_dialog_content = "Ya, jangan simpan itu dalam dirimu.",
  ui_story_5058_50580702_35_dialog_content = "Yah, aku tidak ingin bertingkah seperti itu, tapi untuk beberapa alasan, aku tidak pernah berhubungan baik dengan ibuku sejak aku melakukannya sendiri.",
  ui_story_5058_50580702_36_dialog_content = "Saya tahu dia sangat mencintai saya. Dia mentolerir dan menerima semua yang saya lakukan kecuali memulai bisnis saya sendiri...",
  ui_story_5058_50580702_37_dialog_content = "Dan itulah mengapa saya harus membuktikan bahwa saya bisa menangani segalanya sendiri.",
  ui_story_5058_50580702_38_dialog_content = "Semakin dia mencoba menghentikanku, semakin aku melawan...",
  ui_story_5058_50580702_39_dialog_content = "Mungkin itu terdengar kekanak-kanakan, tapi aku benar-benar tidak bisa mengendalikan diri...",
  ui_story_5058_50580702_40_dialog_content = "Sulit bagi seseorang untuk introspeksi seperti yang baru saja kamu lakukan. Saya mengerti ibumu, meskipun begitu, dia takut kamu akan terluka...",
  ui_story_5058_50580702_41_dialog_content = "Ya, dia tidak menyalahkan kamu atau apa pun. Dia hanya khawatir tentang kamu.",
  ui_story_5058_50580702_42_dialog_content = "EveSetiap orang kadang-kadang kehilangan kontrol, tetapi sedikit pengertian bersama akan cukup.",
  ui_story_5058_50580702_43_dialog_content = "Saya juga berharap itu kasusnya.",
  ui_story_5058_50580702_44_dialog_content = "Tapi untuk mencegahnya mencoba menghentikan saya melakukan sesuatu di masa depan, saya harus mengatasi krisis yang sedang dihadapi ini.",
  ui_story_5058_50580702_45_dialog_content = "Setelah semuanya reda, minta maaflah padanya.",
  ui_story_5058_50580702_46_dialog_content = "Ya! Saya merasa beban di pundak hilang.",
  ui_story_5058_50580702_47_dialog_content = "Maka izinkan kami menjadi bagian dari rencana penanganan krisis Anda!",
  ui_story_5058_50580702_48_dialog_content = "Kami akan mengendarainya bersama, dan kemudian dia pasti akan melihat Anda dalam cahaya baru!",
  ui_story_5058_50580702_49_dialog_content = "Jangan lupa pekerja Rediesel Wrench Anda juga.",
  ui_story_5058_50580702_50_dialog_content = "Terima kasih.",
  ui_story_5058_50580702_51_dialog_content = "Jadi, apa instruksi Anda, bos?",
  ui_story_5058_50580702_52_dialog_content = "Pertama, kita harus menjaga tamu tetap tenang dan menjamin keselamatan mereka.",
  ui_story_5058_50580702_53_dialog_content = "Setelah kita mengamankan perimeter hotel, temukan semua kebocoran dan ambil langkah yang tepat untuk memperbaikinya.",
  ui_story_5058_50580702_54_dialog_content = "Ada pekerjaan untuk staf Rediesel Wrench Anda, Bopper.",
  ui_story_5058_50580702_55_dialog_content = "Tidak masalah selama mereka dibayar.",
  ui_story_5058_50580801_1_dialog_content = "Jangan terburu-buru, Nyonya Shashona...",
  ui_story_5058_50580801_2_dialog_content = "Whoa, bagaimana kalau kita tenang dan menyimpan senjata itu?",
  ui_story_5058_50580801_3_dialog_content = "Tidak ada yang perlu dibicarakan dengan seorang tukang tipu seperti kamu.",
  ui_story_5058_50580801_4_dialog_content = "Mengapa kamu kembali ke Lorelei kali ini?",
  ui_story_5058_50580801_5_dialog_content = "Kamu salah besar, ini hanya kebetulan...",
  ui_story_5058_50580801_6_dialog_content = "Kebetulan? Saya menduga kamu mengetahui Lorelei adalah gadis kaya sekarang dan ingin menipunya?",
  ui_story_5058_50580801_7_dialog_content = "Kamu hanyalah seorang pelayan yang kami pekerjakan dari salah satu perjalanan suami dan saya.",
  ui_story_5058_50580801_8_dialog_content = "Suatu hari, kamu membawa Lorelei kepadaku dan meminta uang muka agar bisa membawanya ke dokter.",
  ui_story_5058_50580801_9_dialog_content = "Saya tidak tahan melihatnya menangis, jadi saya memutuskan untuk mengasuhnya.",
  ui_story_5058_50580801_10_dialog_content = "Apakah kamu benar-benar berniat membantu dia, saya sudah membayar kamu jumlah yang cukup besar.",
  ui_story_5058_50580801_11_dialog_content = "Dan kamu juga berjanji padaku bahwa kamu tidak akan pernah berada di sekitar dia lagi.",
  ui_story_5058_50580801_12_dialog_content = "Hanya untuk kamu yang muncul kembali lebih dari sepuluh tahun kemudian, dan kemudian dia mempermasalahkan peluncuran resor di Lembah Denuo segera. Kamu menyebut itu kebetulan?",
  ui_story_5058_50580801_13_dialog_content = "Dengarkan saya, Ny. Shashona, saya benar-benar bertemu Lorelei secara kebetulan.",
  ui_story_5058_50580801_14_dialog_content = "Dan saya memutuskan untuk membantu karena saya mengagumi ide-nya untuk membuat lembah menjadi hijau.",
  ui_story_5058_50580801_15_dialog_content = "Kamu juga tahu betul bahwa aku bekerja serabutan dan aku perlu mencari nafkah.",
  ui_story_5058_50580801_16_dialog_content = "Lalu apa yang kamu lakukan selain mendapatkan bayaran? Lembah ini benar-benar tidak aman.",
  ui_story_5058_50580801_17_dialog_content = "Baru tersadar setelah melihat stiker kupu-kupu hari ini... Ini sebenarnya tempat asal kamu dan Lorelei, benar, 'kan?",
  ui_story_5058_50580801_18_dialog_content = "Desa yang dikutuk oleh Dewi Denuo, seperti yang kamu jelaskan dulu...",
  ui_story_5058_50580801_19_dialog_content = "Hype tentang Dewi di seluruh taman membuat saya merasa ada yang akan mengambil Lorelei...",
  ui_story_5058_50580801_20_dialog_content = "\"Terkutuk oleh Dewi Denuo\"... Bagaimana kamu bisa mengatakannya begitu ringan?",
  ui_story_5058_50580801_21_dialog_content = "Saya tidak pernah ingin menyebutkan desa itu.",
  ui_story_5058_50580801_22_dialog_content = "Even saat aku menginjakkan kaki di tanah ini lagi, kehancuran masa lalunya masih menghantui aku...",
  ui_story_5058_50580801_23_dialog_content = "Tetapi ketika saya melihat betapa tekun dan berdedikasi Lorelei untuk secara bertahap membalikkan keadaan lembah, akhirnya saya juga melihat harapan...",
  ui_story_5058_50580801_24_dialog_content = "Jadi kamu akui kamu membantu Lorelei membangun kembali rumahmu?",
  ui_story_5058_50580801_25_dialog_content = "Apakah dia tahu kamu yang menyelamatkannya?",
  ui_story_5058_50580801_26_dialog_content = "...",
  ui_story_5058_50580801_27_dialog_content = "Dan itulah rencana komprehensif untuk resor dan penghijauan seluruh ngarai. Bagaimana menurutmu?",
  ui_story_5058_50580801_28_dialog_content = "Itu bukan rencana, wanita muda.",
  ui_story_5058_50580801_29_dialog_content = "Mengembalikan alam, mengabadikan pengalaman pergi ke taman bersama orang tua... Itu hanya buang-buang waktu saya.",
  ui_story_5058_50580801_30_dialog_content = "Dengarkan aku, Bos Sinsa, aku janji akan memberikan bayaran terbaik untuk semua orang yang bekerja di proyek ini!",
  ui_story_5058_50580801_31_dialog_content = "Sebanyak apapun orang berbakat yang dimiliki Rediesel Wrench, mereka memerlukan sebuah panggung untuk memamerkan...",
  ui_story_5058_50580801_32_dialog_content = "Tidak ada yang perlu dibahas. Kami bekerja untuk orang lain? Tidak mau...",
  ui_story_5058_50580801_33_dialog_content = "Saya tertarik. Maysemoga saya bisa membantu.",
  ui_story_5058_50580801_34_dialog_content = "Hei, bukankah kamu Cena?",
  ui_story_5058_50580801_35_dialog_content = "Kamu masih ingat aku?",
  ui_story_5058_50580801_36_dialog_content = "Jangan bilang kamu saudara yang lama hilang atau sesuatu seperti itu!",
  ui_story_5058_50580801_37_dialog_content = "Tentu saja aku ingat kamu. Bagaimana bisa aku melupakan orang yang menyelamatkan aku?",
  ui_story_5058_50580801_38_dialog_content = "Kemana kamu pergi? Aku terus berharap bisa bertemu kamu lagi.",
  ui_story_5058_50580801_39_dialog_content = "...",
  ui_story_5058_50580801_40_dialog_content = "Aku mengerti. Mungkin Mama tidak ingin kamu di sekitar aku.",
  ui_story_5058_50580801_41_dialog_content = "Tapi senang sekali bisa bertemu kamu lagi!",
  ui_story_5058_50580801_42_dialog_content = "Ehem... Maaf, hampir lupa saya datang ke sini untuk urusan bisnis.",
  ui_story_5058_50580801_43_dialog_content = "Mari kita mulai lagi. Nama saya Lorelei Cardogon. Senang bertemu denganmu!",
  ui_story_5058_50580801_44_dialog_content = "Oh, dan jangan bilang ke ibu bahwa aku masih ingat kamu.",
  ui_story_5058_50580801_45_dialog_content = "Tentu. Semoga sukses dengan kesepakatan tersebut.",
  ui_story_5058_50580801_46_dialog_content = "Tunggu, kamu bilang ingin membantu, tapi saya sangat ketat dalam hal merekrut.",
  ui_story_5058_50580801_47_dialog_content = "Kamu harus lulus evaluasi sebelum bisa mulai!",
  ui_story_5058_50580801_48_dialog_content = "Hei, apakah itu cara kamu memperlakukan seseorang yang menyelamatkanmu?",
  ui_story_5058_50580801_49_dialog_content = "Hmm, ternyata kamu orang yang menarik, Lorelei. Maymungkin aku bisa merancang beberapa wahana untukmu juga.",
  ui_story_5058_50580801_50_dialog_content = "Itu akan sangat bagus, Honcho Sinsa! Aku tahu Rediesel Desert sebenarnya adalah tempat yang keren.",
  ui_story_5058_50580801_51_dialog_content = "Jangan khawatir, saya tidak mengatakan apa-apa. Baginya, saya hanya seorang karyawan.",
  ui_story_5058_50580801_52_dialog_content = "Dan tolong rileks, Lorelei adalah anak yang hebat. Kamu khawatir tentang hal-hal yang tidak akan terjadi.",
  ui_story_5058_50580801_53_dialog_content = "Tidak akan terjadi? Lalu apa itu gerhana-gerhana itu?",
  ui_story_5058_50580801_54_dialog_content = "Wow, stres yang aku rasakan... Kamu tidak percaya dia bisa menanganinya? Atau...",
  ui_story_5058_50580801_55_dialog_content = "Apakah kamu takut jika dia menyelesaikan krisis ini, dia akan cukup kuat untuk... meninggalkan kamu?",
  ui_story_5058_50580801_56_dialog_content = "Hmm, aku bahkan bertanya-tanya apakah kamu sengaja membawa Eclipsite...",
  ui_story_5058_50580801_57_dialog_content = "Dan biarkan mereka menyakiti anak saya? Apakah itu sesuatu yang akan dilakukan oleh seorang ibu?",
  ui_story_5058_50580801_58_dialog_content = "Saya selalu memperlakukannya seperti anak sendiri. Mengapa saya tidak ingin melihat dia sukses?",
  ui_story_5058_50580801_59_dialog_content = "Berdiri di atas kakinya sendiri... Jalani hidupnya sendiri...",
  ui_story_5058_50580801_60_dialog_content = "Aku tahu itu akan terjadi lebih cepat atau lambat.",
  ui_story_5058_50580801_61_dialog_content = "Semua yang bisa kuharapkan adalah semoga ini terjadi nanti agar aku bisa membuka jalan yang lebih baik untuknya...",
  ui_story_5058_50580801_62_dialog_content = "Heh, begitu pengertian tapi sulit untuk biarkan dia pergi!",
  ui_story_5058_50580801_63_dialog_content = "<size=45>Astaga!</size>",
  ui_story_5058_50580801_64_dialog_content = "Kita akan membahas itu nanti. Mari selesaikan dulu Eclipsite, Nyonya Shashona.",
  ui_story_5058_50580802_1_dialog_content = "Selesai.",
  ui_story_5058_50580802_2_dialog_content = "Kamu benar-benar ahli menembak, Nyonya Shashona.",
  ui_story_5058_50580802_3_dialog_content = "Tunggu... Perasaan ini... Sama seperti sebelumnya...",
  ui_story_5058_50580802_4_dialog_content = "Apa mungkin...",
  ui_story_5058_50580802_5_dialog_content = "Apa yang kamu katakan, Cena?",
  ui_story_5058_50580802_6_dialog_content = "Nah, nggak mungkin, semuanya udah selesai...",
  ui_story_5058_50580802_7_dialog_content = "Maaf, Nyonya Shashona, saya tidak bisa mengantar Anda pulang. Ada sesuatu yang baru saja muncul.",
  ui_story_5058_50580802_8_dialog_content = "Kamu mau ke mana?",
  ui_story_5058_50580802_9_dialog_content = "Kamu tahu lembah dan Lorelei dalam bahaya, kan?",
  ui_story_5058_50580802_10_dialog_content = "<size=45>Hai...!</size>",
  ui_story_5058_50580901_1_dialog_content = "Kamu kembali, Lorelei! Bagaimana suasana di luar sana?",
  ui_story_5058_50580901_2_dialog_content = "Tidak ada tanda Eclipsite untuk saat ini, tetapi masih belum ada petunjuk mengapa mereka tiba-tiba muncul...",
  ui_story_5058_50580901_3_dialog_content = "Apa yang terjadi dengan para tamu?",
  ui_story_5058_50580901_4_dialog_content = "Kami membantu semuanya ke kamar mereka, tetapi manajer dan Shashona tidak terlihat di mana-mana...",
  ui_story_5058_50580901_5_dialog_content = "Cena dan ibu saya? Apakah kamu sudah memeriksa setiap sudut hotel?",
  ui_story_5058_50580901_6_dialog_content = "Ya, di mana-mana.",
  ui_story_5058_50580901_7_dialog_content = "Terima kasih sudah memberi tahu, Bopper. Tolong beritahu tim keamanan untuk mengatur pertahanan di sekitar hotel.",
  ui_story_5058_50580901_8_dialog_content = "Juga, ingatkan staf untuk menyiapkan dan mengantarkan makanan kepada tamu tepat waktu, tidak boleh terlambat satu detik pun...",
  ui_story_5058_50580901_9_dialog_content = "Groar!",
  ui_story_5058_50580901_10_dialog_content = "Apa?",
  ui_story_5058_50580901_11_dialog_content = "Ice Blossom!",
  ui_story_5058_50580901_12_dialog_content = "Wow, refleks kilat, Carleen! Kamu membunuh Eclipsite sebelum saya bahkan tahu itu ada di sana!",
  ui_story_5058_50580901_13_dialog_content = "Tapi bagaimana mereka mendapatkan...",
  ui_story_5058_50580901_14_dialog_content = "Di dalam... hotel...",
  ui_story_5058_50580901_15_dialog_content = "Lorelei...? Kamu...",
  ui_story_5058_50580901_16_dialog_content = "Mataku... tidak bisa menahannya terbuka...",
  ui_story_5058_50580901_17_dialog_content = "PlayerName…",
  ui_story_5058_50580901_18_dialog_content = "...",
  ui_story_5058_50580901_19_dialog_content = "Vice... Carleen...?!",
  ui_story_5058_50580901_20_dialog_content = "Apa... yang terjadi...",
  ui_story_5058_50580901_21_dialog_content = "PlayerName... PlayerName?",
  ui_story_5058_50580901_22_dialog_content = "Hah?",
  ui_story_5058_50580901_23_dialog_content = "Ketemu! Nakal kecil! Waktunya pulang sama Mama buat makan malam. Kamu tahu kan orang harus makan biar tumbuh, kanan?",
  ui_story_5058_50580901_24_dialog_content = "Mimpi lainnya?",
  ui_story_5058_50580901_25_dialog_content = "Lagi? Kali ini, meskipun...",
  ui_story_5058_50580901_26_option_content = "Ayo, bangun!",
  ui_story_5058_50580901_27_dialog_content = "Huff... Apa yang baru saja terjadi? Rasanya persis seperti saat aku pingsan di lembah.",
  ui_story_5058_50580901_28_dialog_content = "EveSemua orang keluar...",
  ui_story_5058_50580901_29_dialog_content = "Lorelei? Lorelei! Bangun!",
  ui_story_5058_50580901_30_dialog_content = "Ibu... ibu...",
  ui_story_5058_50580901_31_dialog_content = "Vice! Carleen!",
  ui_story_5058_50580901_32_dialog_content = "Harus masak... membuat hidangan baru...",
  ui_story_5058_50580901_33_dialog_content = "...",
  ui_story_5058_50580901_34_dialog_content = "Apakah semua orang dalam trance? Hei, apa itu yang berkedip di udara?",
  ui_story_5058_50580901_35_dialog_content = "Ini ada di mana-mana, di seluruh hotel! Apakah ini yang membuat orang pingsan?",
  ui_story_5058_50580901_36_dialog_content = "Apa yang akan aku lakukan? Aku bisa membangunkan mereka secara telepati... Tidak, buka jendela dan biarkan udara segar masuk.",
  ui_story_5058_50580901_37_dialog_content = "Tapi jika begitu, bukankah Eclipsite di luar bisa masuk?",
  ui_story_5058_50580901_38_dialog_content = "Hmm, tidakkah Lorelei menyebutkan sistem ventilasi? Ayo kita nyalakan itu!",
  ui_story_5058_50580901_39_dialog_content = "Masalahnya, aku tidak tahu di mana letak saklarnya.",
  ui_story_5058_50580901_40_dialog_content = "Lorelei pasti tahu! Ya, saya akan membangunkannya terlebih dahulu!",
  ui_story_5058_50580901_41_option_content = "Force Boost!",
  ui_story_5058_50580901_42_dialog_content = "Apakah kamu tertidur, Lorelei?",
  ui_story_5058_50580901_43_dialog_content = "Tidak, aku hanya mendengarkan Ibu bercerita dengan mata tertutup!",
  ui_story_5058_50580901_44_dialog_content = "(Ini harusnya memori Lorelei.)",
  ui_story_5058_50580901_45_dialog_content = "(Apakah gadis kecil itu Lorelei? Tapi ibunya tidak terlihat seperti itu Shashona!)",
  ui_story_5058_50580901_46_dialog_content = "(Dan pemuda itu di sana adalah sosok yang saya lihat saat saya pingsan di lembah!)",
  ui_story_5058_50580901_47_dialog_content = "Legenda mengatakan bahwa Lembah Denuo bebas dari Eclipsite karena kita berada di bawah perlindungan <color=#FFB400>Dewi Denuo</color>.",
  ui_story_5058_50580901_48_dialog_content = "Kupu-kupu? Maksud kamu yang di sekitar kita?",
  ui_story_5058_50580901_49_dialog_content = "Dewi Denuo bukanlah kupu-kupu biasa. Mereka memiliki sayap yang berkilau seperti berlian.",
  ui_story_5058_50580901_50_dialog_content = "EveSetiap orang yang melihat Dewi akan menerima berkat wahyu dan kebahagiaan yang tak tertandingi.",
  ui_story_5058_50580901_51_dialog_content = "Betulkah? Kapan saya bisa melihat satu?",
  ui_story_5058_50580901_52_dialog_content = "Oh anak kecil, tidak mudah melihat Dewi.",
  ui_story_5058_50580901_53_dialog_content = "Kisahnya mereka tinggal di Lembah Denuo tetapi jarang menampakkan diri kepada siapa pun.",
  ui_story_5058_50580901_54_dialog_content = "Saya rasa saya melihat Dewi Denuo muda beberapa hari yang lalu.",
  ui_story_5058_50580901_55_dialog_content = "Saya tidak bisa lepaskan pandangan dari kilauan cemerlang di sayapnya... Hanya satu kali melihat dan kamu tidak akan pernah lupa!",
  ui_story_5058_50580901_56_dialog_content = "Saya dengar Dewi Denuo muda jarang tumbuh dewasa dan terjebak dalam jaring laba-laba, jadi saya membebaskannya.",
  ui_story_5058_50580901_57_dialog_content = "Wow! Jadi kamu sudah menerima berkatnya?",
  ui_story_5058_50580901_58_dialog_content = "Mayjangan...?",
  ui_story_5058_50580901_59_dialog_content = "Ayo, Cena, jangan bilang kamu belum pernah lihat satu pun! Berbohong itu tidak baik!",
  ui_story_5058_50580901_60_dialog_content = "(Sebenarnya pemuda itu adalah Cena? Jadi mereka saling kenal sebelumnya?)",
  ui_story_5058_50580901_61_dialog_content = "<color=#e8d9bb>Whoosh—Whoosh!</color>",
  ui_story_5058_50580901_62_dialog_content = "Mam! Cena! Di mana kau?",
  ui_story_5058_50580901_63_dialog_content = "Badai pasir! Menelan seluruh desa!",
  ui_story_5058_50580901_64_dialog_content = "Kita pantas mendapatkannya karena telah membuat Dewi Denuo marah!",
  ui_story_5058_50580901_65_dialog_content = "Ibu... Jangan tinggalkan aku di belakang...",
  ui_story_5058_50580901_66_dialog_content = "Genggam tanganku, Lorelei!",
  ui_story_5058_50580901_67_dialog_content = "Cena...?",
  ui_story_5058_50580901_68_dialog_content = "Ini aku, PlayerName!",
  ui_story_5058_50580901_69_dialog_content = "PlayerName...?",
  ui_story_5058_50580901_70_option_content = "Bangun!",
  ui_story_5058_50580901_71_dialog_content = "Hah…?",
  ui_story_5058_50580901_72_dialog_content = "Kamu akhirnya bangun, Lorelei! Jangan panik, ini hanya aku!",
  ui_story_5058_50580901_73_dialog_content = "PlayerName? Apa yang terjadi?",
  ui_story_5058_50580901_74_dialog_content = "Aku tidak tahu, tapi tiba-tiba semua orang pingsan.",
  ui_story_5058_50580901_75_dialog_content = "Kemudian saya menyadari ada sesuatu yang aneh di udara.",
  ui_story_5058_50580901_76_dialog_content = "Sesuatu yang terus berkedip.",
  ui_story_5058_50580901_77_dialog_content = "Mereka pasti berkaitan dengan semua orang yang tidak sadar. Jika kita menghidupkan sistem ventilasi yang kamu sebutkan, apakah itu akan menghilangkan hal-hal tersebut?",
  ui_story_5058_50580901_78_dialog_content = "Saklar itu dekat saja. Ikuti aku!",
  ui_story_5058_50580901_79_dialog_content = "Graagh!",
  ui_story_5058_50580901_80_dialog_content = "Lebih banyak gerhana?",
  ui_story_5058_50580901_81_dialog_content = "Hanya kita berdua yang tersisa... Bantu aku, PlayerName!",
  ui_story_5058_50581001_1_dialog_content = "Graaaah!",
  ui_story_5058_50581001_2_dialog_content = "Ahhhh!",
  ui_story_5058_50581001_3_dialog_content = "Kamu tidak bisa membunuhku seperti itu!",
  ui_story_5058_50581001_4_dialog_content = "Belum lagi hidup ini bukan milikku lagi, jadi, maaf, tidak bisa kuberikan padamu!",
  ui_story_5058_50581001_5_dialog_content = "Tapi sangat segera, saat aku melihat <color=#FFB400>\"dia\"</color>... Di sisi lain, \"dia\" mungkin yang menarikmu ke sini.",
  ui_story_5058_50581001_6_dialog_content = "Saya masih ingin bertemu \"dia\", meskipun, dan menyesal secara pribadi...",
  ui_story_5058_50581001_7_dialog_content = "(Apakah Cena sudah gila? Siapa yang ingin dia temui?)",
  ui_story_5058_50581001_8_dialog_content = "Groar!",
  ui_story_5058_50581001_9_dialog_content = "Awas!",
  ui_story_5058_50581001_10_dialog_content = "Ny. Shashona?",
  ui_story_5058_50581001_11_dialog_content = "Apa yang sedang kamu lakukan, Cena? Kenapa kamu berusaha menjadi hero saat seharusnya kamu kembali ke hotel membantu Lorelei?",
  ui_story_5058_50581001_12_dialog_content = "Ini tidak ada hubungannya dengan kamu. Saya harus menghadapi apa yang mengganggu saya sebagian besar hidup saya sendirian. Saya harus melakukannya sendiri...",
  ui_story_5058_50581001_13_dialog_content = "Terima kasih telah membesarkan dan merawat Lorelei untukku...",
  ui_story_5058_50581001_14_dialog_content = "Dia sudah dewasa sekarang. Kamu harus mendengarkan apa yang ingin dia sampaikan, berhenti mengatur segalanya untuknya.",
  ui_story_5058_50581001_15_dialog_content = "Tepat sekali. Silakan berbalik.",
  ui_story_5058_50581001_16_dialog_content = "Apakah kamu memberikan kata-kata terakhirmu padaku?",
  ui_story_5058_50581001_17_dialog_content = "Aaaaaah!",
  ui_story_5058_50581001_18_dialog_content = "Ayo, serang aku!",
  ui_story_5058_50581001_19_dialog_content = "Mengisi Eclipsite seperti itu saja? Apakah kamu kehilangan akal, Cena?!",
  ui_story_5058_50581001_20_dialog_content = "Ini membuatku sakit kepala.",
  ui_story_5058_50581001_21_dialog_content = "Sayangnya, saya bukan tipe orang yang bisa diam saja dan menyaksikan orang lain mati.",
  ui_story_5058_50581001_22_dialog_content = "Oke, ayo coba peluru khusus buatanku yang baru dan lihat apakah kamu suka!",
  ui_story_5058_50581001_23_dialog_content = "<color=#e8d9bb>Dor! Dor! Dor!</color>",
  ui_story_5058_50581001_24_dialog_content = "Ugh!",
  ui_story_5058_50581001_25_dialog_content = "Aku mohon, Shashona, tinggalkan aku sendiri...",
  ui_story_5058_50581001_26_dialog_content = "Tinggalkan kamu sendirian? Bagaimana bisa itu selalu terucap dengan mudah dari lidahmu dan Lorelei?",
  ui_story_5058_50581001_27_dialog_content = "Lorelei dan aku berbeda. Kamu masih belum mengerti. Dia tidak pernah ingin menjauh dari kamu.",
  ui_story_5058_50581001_28_dialog_content = "Alasan dia ingin membangun taman hiburan adalah karena dia menghargai kenangan saat kamu membawanya ke sana.",
  ui_story_5058_50581001_29_dialog_content = "Apakah itu yang dia katakan padamu? Anak kecil itu...",
  ui_story_5058_50581001_30_dialog_content = "Aku tahu itu. Aku menyadarinya saat membaca rencana bisnisnya. Aku hanya...",
  ui_story_5058_50581001_31_dialog_content = "<color=#e8d9bb>Whoosh—Whoosh—</color>",
  ui_story_5058_50581001_32_dialog_content = "Angin bertiup di lembah...?",
  ui_story_5058_50581001_33_dialog_content = "<color=#e8d9bb>His—</color>",
  ui_story_5058_50581001_34_dialog_content = "Aku datang...",
  ui_story_5058_50581001_35_dialog_content = "\"Dia\" datang!",
  ui_story_5058_50581001_36_dialog_content = "Siapa yang datang?",
  ui_story_5058_50581001_37_dialog_content = "<color=#e8d9bb>Whoosh—Whoosh—</color>",
  ui_story_5058_50581001_38_dialog_content = "Desis—Desis—",
  ui_story_5058_50581001_39_dialog_content = "<color=#FFB400>Dewi Denuo</color>... Akhirnya, aku melihatmu!",
  ui_story_5058_50581001_40_dialog_content = "Aku meninggalkan desa dan menghabiskan setengah hidupku berkeliaran di seluruh Astra hanya untuk menyadari...",
  ui_story_5058_50581001_41_dialog_content = "Hatiku tak pernah meninggalkan Denuo!",
  ui_story_5058_50581001_42_dialog_content = "Aku lihat kamu datang untuk balas dendam, Dewi Denuo.",
  ui_story_5058_50581001_43_dialog_content = "Ya, seharusnya saya tidak selamat. Saya pikir saya bisa mendapatkan amnesti dengan membangun kembali lembah itu...",
  ui_story_5058_50581001_44_dialog_content = "Tolong berikan saya hukuman terakhir!",
  ui_story_5058_50581001_45_dialog_content = "Apakah itu Dewi Denuo yang menimpakan kutukan?",
  ui_story_5058_50581001_46_dialog_content = "Tenanglah, Cena! Ini hanya kupu-kupu yang lebih besar dari biasanya!",
  ui_story_5058_50581001_47_dialog_content = "Saya tidak percaya seekor kupu-kupu saja bisa mengatur hidup kita!",
  ui_story_5058_50581001_48_dialog_content = "<color=#e8d9bb>Whoosh—Whoosh—</color>",
  ui_story_5058_50581001_49_dialog_content = "Hiss!",
  ui_story_5058_50581001_50_dialog_content = "Apa yang sedang dirilis?",
  ui_story_5058_50581001_51_dialog_content = "Aahhhh!",
  ui_story_5058_50581001_52_dialog_content = "Lebih banyak Eclipsite muncul...",
  ui_story_5058_50581001_53_dialog_content = "Saya mengerti, kupu-kupu membawa Eclipsite ke lembah! Cena!",
  ui_story_5058_50581001_54_dialog_content = "Cena?",
  ui_story_5058_50581001_55_dialog_content = "Tolong hukum aku...",
  ui_story_5058_50581001_56_dialog_content = "Bangkitlah sekarang dan lawan Eclipsites!",
  ui_story_5058_50581002_1_dialog_content = "Ahh...",
  ui_story_5058_50581002_2_dialog_content = "Saya pusing... Apa yang terjadi...? Tidak bisa tahan...",
  ui_story_5058_50581002_3_dialog_content = "Cena... Cena...",
  ui_story_5058_50581002_4_dialog_content = "Berlari... Berlari...",
  ui_story_5058_50581002_5_dialog_content = "Hah?",
  ui_story_5058_50581002_6_dialog_content = "Berlari...",
  ui_story_5058_50581002_7_dialog_content = "Berlari...",
  ui_story_5058_50581002_8_dialog_content = "Mengapa kamu menyelamatkan aku? Orang seperti aku tidak layak untuk usaha itu...",
  ui_story_5058_50581002_9_dialog_content = "Berlari... Ambil Lorelei dan... berlari...!",
  ui_story_5058_50581002_10_dialog_content = "...",
  ui_story_5058_50581002_11_dialog_content = "Oh...",
  ui_story_5058_50581002_12_dialog_content = "Ny. Shashona?!",
  ui_story_5058_50581002_13_dialog_content = "Coco, Shashona... Kenapa kalian berdua menyelamatkan seseorang yang tidak pernah menganggap hidup dengan serius seperti saya?",
  ui_story_5058_50581002_14_dialog_content = "<size=45>Siul, siul, siul!</size>",
  ui_story_5058_50581002_15_dialog_content = "Groar!",
  ui_story_5058_50581002_16_dialog_content = "Tapi aku lah yang seharusnya tidak diampuni, bukan Shashona...",
  ui_story_5058_50581002_17_dialog_content = "Nyonya Shashona! Apa kau bisa mendengarku?! Shashona!",
  ui_story_5058_50581002_18_dialog_content = "Tidak...",
  ui_story_5058_50581002_19_dialog_content = "<color=#e8d9bb>*Menabrak*</color>",
  ui_story_5058_50581002_20_dialog_content = "Kemari, Shashona! Kemana ibumu pergi?",
  ui_story_5058_50581002_21_dialog_content = "Entahwah...",
  ui_story_5058_50581002_22_dialog_content = "Berhenti menangis! Kamu tidak tahu? Bagaimana bisa kamu tidak tahu? Ibumu pergi, mengerti?! Semua ini salahmu!",
  ui_story_5058_50581002_23_dialog_content = "*Hiks*",
  ui_story_5058_50581002_24_dialog_content = "Di mana dia menyimpan uangnya?",
  ui_story_5058_50581002_25_dialog_content = "Papa... Toko kita lagi berhutang. Mama bilang kita harus hemat setiap uang, bukan untuk kamu habiskan buat minum-minuman keras.",
  ui_story_5058_50581002_26_dialog_content = "Mengapa kamu masih mendengarkannya saat dia bahkan tidak menginginkanmu lagi? Aku paham kamu butuh pelajaran keras!",
  ui_story_5058_50581002_27_dialog_content = "<color=#e8d9bb>Cipok! Cipok!</color>",
  ui_story_5058_50581002_28_dialog_content = "...",
  ui_story_5058_50581002_29_dialog_content = "Anak yang malang... Jangan khawatir, aku berjanji akan merawatmu sampai sehat kembali.",
  ui_story_5058_50581002_30_dialog_content = "Sejak pertama kali aku melihatmu, aku tahu kamu adalah putri yang dikirim untukku dari atas, menggantikan masa kecilku...",
  ui_story_5058_50581002_31_dialog_content = "Saya merangkak keluar dari quagmire sedikit demi sedikit hanya setelah bertahun-tahun mimpi buruk.",
  ui_story_5058_50581002_32_dialog_content = "Mulai sekarang, aku akan membuat kamu menjadi gadis paling bahagia di dunia, tak akan terluka lagi.",
  ui_story_5058_50581002_33_dialog_content = "<color=#e8d9bb>Tik-tik-tik...</color>",
  ui_story_5058_50581002_34_dialog_content = "Di mana aku?",
  ui_story_5058_50581002_35_dialog_content = "Lorelei, sayangku, keluar dari hujan dan datang padaku!",
  ui_story_5058_50581002_36_dialog_content = "Mengapa kamu membiarkan saya berlindung di bawah payungmu?",
  ui_story_5058_50581002_37_dialog_content = "Karena... Saya pernah berada di luar saat hujan ketika saya masih anak-anak dan itu tidak terasa enak.",
  ui_story_5058_50581002_38_dialog_content = "Jadi saya tidak ingin kamu kehujanan atau terluka. Saya ingin kamu tidak perlu khawatir tentang apa pun selain tumbuh dengan aman dan sehat.",
  ui_story_5058_50581002_39_dialog_content = "Tapi siapa kamu? Kenapa kamu baik sekali padaku?",
  ui_story_5058_50581002_40_dialog_content = "Apakah kamu lupa bahwa aku adalah ibumu? Kamu punya ayah dan adik laki-laki juga. Kita adalah keluarga paling bahagia di dunia.",
  ui_story_5058_50581002_41_dialog_content = "Apakah ada yang kamu inginkan, sayang? Aku bisa memenuhi setiap keinginanmu!",
  ui_story_5058_50581002_42_dialog_content = "Bisakah saya membaca buku cerita?",
  ui_story_5058_50581002_43_dialog_content = "Ya!",
  ui_story_5058_50581002_44_dialog_content = "Bisakah saya mengenakan gaun cantik?",
  ui_story_5058_50581002_45_dialog_content = "Ya!",
  ui_story_5058_50581002_46_dialog_content = "Dan... dan...",
  ui_story_5058_50581002_47_dialog_content = "Aku bisa mengajak kamu ke taman hiburan baru!",
  ui_story_5058_50581002_48_dialog_content = "Taman hiburan! Bolehkah aku pergi? Apakah ayah dan kakak akan pergi bersama kita juga?",
  ui_story_5058_50581002_49_dialog_content = "Ya. Kita bisa pergi dulu karena ayah sedang ke luar negeri untuk urusan bisnis dan kakakmu sedang di sekolah. Kita bisa pergi bersama banyak kali saat mereka kembali.",
  ui_story_5058_50581002_50_dialog_content = "Bisakah saya menjalankan bisnis seperti ayah?",
  ui_story_5058_50581002_51_dialog_content = "Itu terlalu berisiko untukmu, sayang. Aku sudah melalui banyak hal dan menderita banyak untuk sampai di posisi sekarang.",
  ui_story_5058_50581002_52_dialog_content = "Jadi saya tidak ingin bayi saya mengalami hal yang sama...",
  ui_story_5058_50581002_53_dialog_content = "Baiklah... Hei, aku penasaran apa itu hal menyenangkan di sana...",
  ui_story_5058_50581002_54_dialog_content = "Pelankan, sayang.",
  ui_story_5058_50581002_55_dialog_content = "<color=#e8d9bb>Wuuss—</color>",
  ui_story_5058_50581002_56_dialog_content = "Payungku tertiup angin...",
  ui_story_5058_50581002_57_dialog_content = "Tidak apa-apa, Bu! Lihat, saya menemukan payung cantik yang bahkan lebih besar dari milikmu!",
  ui_story_5058_50581002_58_dialog_content = "Aku bisa menahan untuk kamu juga!",
  ui_story_5058_50581002_59_dialog_content = "Huh...",
  ui_story_5058_50581002_60_dialog_content = "Hujan akan segera berhenti. Aku ingin pergi ke sana!",
  ui_story_5058_50581002_61_dialog_content = "Di mana kamu, sayangku?",
  ui_story_5058_50581002_62_dialog_content = "Berharga? Laurie!<size=45>Lorelei!</size>",
  ui_story_5058_50581002_63_dialog_content = "Jangan tinggalkan aku... Jangan acuhkan aku...",
  ui_story_5058_50581002_64_dialog_content = "Tunggu, kenapa aku mengatakan itu?",
  ui_story_5058_50581002_65_dialog_content = "Aku paham, karena aku tidak bisa terpisah darimu...",
  ui_story_5058_50581002_66_dialog_content = "Aku yang membutuhkanmu di sekitar...",
  ui_story_5058_50581101_1_dialog_content = "<color=#e8d9bb>Klik!</color>",
  ui_story_5058_50581101_2_dialog_content = "Oke, sistem ventilasi sedang bekerja.",
  ui_story_5058_50581101_3_dialog_content = "Tapi mengapa pintu itu terbuka?",
  ui_story_5058_50581101_4_dialog_content = "Bukankah biasanya tutup?",
  ui_story_5058_50581101_5_dialog_content = "Ada ruang bawah tanah di sini khusus untuk pendingin udara.",
  ui_story_5058_50581101_6_dialog_content = "Kamu menyimpan pendingin udara di bawah tanah?",
  ui_story_5058_50581101_7_dialog_content = "Hanya sistem utama. Pipa-pipa terhubung ke luar ruangan.",
  ui_story_5058_50581101_8_dialog_content = "Karena memakan banyak ruang dan sangat berisik, saya mencoba mencari tahu persis di mana meletakkannya bahkan sebelum membangun hotel.",
  ui_story_5058_50581101_9_dialog_content = "Hingga Cena menyarankan menggali ruang bawah tanah untuk itu. Ini juga merupakan yurisdiksi miliknya.",
  ui_story_5058_50581101_10_dialog_content = "Kami tidak bisa menemukan Cena dan Shashona sama sekali. Apakah mereka mungkin ada di ruang bawah tanah?",
  ui_story_5058_50581101_11_dialog_content = "Bos, PlayerName... Kenapa semua orang pergi?",
  ui_story_5058_50581101_12_dialog_content = "Bopper? Kamu sudah bangun!",
  ui_story_5058_50581101_13_dialog_content = "Tapi mereka masih...",
  ui_story_5058_50581101_14_dialog_content = "Tolong bangunkan semua orang, Bopper, lalu periksa tamu-tamu.",
  ui_story_5058_50581101_15_dialog_content = "PlayerName dan saya akan pergi ke ruang bawah tanah untuk melihat apakah Cena ada di sana.",
  ui_story_5058_50581101_16_dialog_content = "Tentu!",
  ui_story_5058_50581101_17_dialog_content = "Hmm, sepertinya saya mendengar langkah kaki di ruang bawah tanah. Apakah itu Pak Cena?",
  ui_story_5058_50581101_18_dialog_content = "Mungkin saja?",
  ui_story_5058_50581101_19_dialog_content = "<color=#e8d9bb>Dug, dug, dug!</color>",
  ui_story_5058_50581101_20_dialog_content = "Graagh!",
  ui_story_5058_50581102_1_dialog_content = "<size=45>Cena? Ibu? Apa kau di sana?</size>",
  ui_story_5058_50581102_2_dialog_content = "Kau di sana...?",
  ui_story_5058_50581102_X2_dialog_content = "Apa kau di sana?",
  ui_story_5058_50581102_X3_dialog_content = "Kanan?",
  ui_story_5058_50581102_3_dialog_content = "Tidak heran Eclipsite bisa menyelinap ke hotel. Ini jelas terowongan dan siapa tahu kemana ini mengarah.",
  ui_story_5058_50581102_4_dialog_content = "Ketika saya meninggalkan ruang bawah tanah untuk Cena, saya tidak pernah menyangka dia akan menggali terowongan di belakang punggung saya.",
  ui_story_5058_50581102_5_dialog_content = "Aku melihat banyak meja, kursi, botol, dan kaleng di sekitar sini, tapi sepertinya mereka sangat tua.",
  ui_story_5058_50581102_6_dialog_content = "Sangat tua? Jangan bilang...",
  ui_story_5058_50581102_7_dialog_content = "Apakah itu tumpukan berkas di bawah bangku?",
  ui_story_5058_50581102_8_dialog_content = "Biar kulihat...",
  ui_story_5058_50581102_9_dialog_content = "\"Rumus untuk Denuo Incense?\"",
  ui_story_5058_50581102_10_dialog_content = "Saya baru saja bicara dengan Cena tentang hal itu pagi ini, tapi apakah dia sudah menyelidikinya sebelumnya, atau...",
  ui_story_5058_50581102_11_dialog_content = "Ini mengatakan bahwa komponen paling penting untuk dupa adalah... <color=#FFB400>Dewi Denuo</color>?!",
  ui_story_5058_50581102_12_dialog_content = "Apa?!",
  ui_story_5058_50581102_13_dialog_content = "Dan dokumen-dokumen itu milik... Desa Denuo.",
  ui_story_5058_50581102_14_dialog_content = "Apakah ini sisa-sisa Desa Denuo? Tapi saya tidak tahu kalau dulu para penduduk desa membuat dupa dari Dewi Denuo.",
  ui_story_5058_50581102_15_dialog_content = "Tidak mungkin Cena tidak tahu tentang itu, tapi kenapa dia tidak pernah memberitahu aku?",
  ui_story_5058_50581102_16_dialog_content = "Apakah kamu dan Cena dari desa?",
  ui_story_5058_50581102_17_dialog_content = "Maaf, kebetulan saya menangkap sepotong mimpi Anda saat mencoba membangunkan Anda.",
  ui_story_5058_50581102_18_dialog_content = "Lalu saya kira kamu juga menemukan bahwa Shashona bukan ibu kandung saya.",
  ui_story_5058_50581102_19_dialog_content = "Tapi tidak apa-apa, PlayerName, saya tidak bermaksud menyembunyikan masa lalu saya.",
  ui_story_5058_50581102_20_dialog_content = "Saya hanya khawatir jika mengungkitnya bisa membuat ibu saya Shashona merasa tidak enak.",
  ui_story_5058_50581102_21_dialog_content = "Dan kamu melihat betapa baiknya dia padaku juga, dan telah melakukan banyak hal untukku, jadi seharusnya aku tidak terus terikat pada masa lalu seperti sekarang ini.",
  ui_story_5058_50581102_22_dialog_content = "Namun kenangan-kenangan itu, bahagia atau sedih, tetap muncul sesekali.",
  ui_story_5058_50581102_23_dialog_content = "Jadi, kamu memang kenal Cena sejak dulu?",
  ui_story_5058_50581102_24_dialog_content = "Dia adalah tetangga kami. Saya memanggilnya Pak Cena.",
  ui_story_5058_50581102_25_dialog_content = "Suatu hari, badai pasir yang belum pernah terjadi sebelumnya melanda Denuo. Saya melihatnya menghancurkan seluruh desa dengan mata kepala sendiri.",
  ui_story_5058_50581102_26_dialog_content = "Aku terluka dalam bencana itu, tapi aku ingat itu adalah Cena yang menyelamatkan aku.",
  ui_story_5058_50581102_27_dialog_content = "Dan juga samar-samar bagaimana dia menyerahkan saya kepada ibu angkat saya...",
  ui_story_5058_50581102_28_dialog_content = "Saya pikir dia akan menyempatkan waktu untuk bertemu dengan saya, tetapi dia tidak pernah melakukannya hingga pertemuan kebetulan tepat sebelum membangun resor.",
  ui_story_5058_50581102_29_dialog_content = "Sebenarnya, ketika saya pingsan di lembah sebelumnya, entah mengapa saya melihat wajah Cena muda dalam mimpi.",
  ui_story_5058_50581102_30_dialog_content = "Terowongan bawah tanah, Denuo dupa, Eclipsite, benda aneh di udara, dan Dewi Denuo...",
  ui_story_5058_50581102_31_dialog_content = "Cena adalah kunci untuk semua itu.",
  ui_story_5058_50581102_32_dialog_content = "Waktu telah mengubahnya menjadi seseorang yang tidak sepenuhnya saya kenali.",
  ui_story_5058_50581102_33_dialog_content = "Tapi saya masih mau memercayai dia, kakak laki-laki yang menyelamatkan saya dalam bencana.",
  ui_story_5058_50581102_34_dialog_content = "Apa yang sedang dia lakukan, ya?",
  ui_story_5058_50581102_35_dialog_content = "<color=#e8d9bb>Buk, Buk, Buk...</color>",
  ui_story_5058_50581102_36_dialog_content = "Siapa di sana? Apakah itu seorang Eclipsite?",
  ui_story_5058_50581102_37_dialog_content = "Ini aku...",
  ui_story_5058_50581102_38_dialog_content = "Cena.",
  ui_story_5058_50581201_1_dialog_content = "Huh, kamu menemukan tempat ini.",
  ui_story_5058_50581201_2_dialog_content = "Kamu membaca file-file itu, saya mengerti...",
  ui_story_5058_50581201_3_dialog_content = "Saya punya banyak pertanyaan untukmu.",
  ui_story_5058_50581201_4_dialog_content = "Tunggu, apakah Cena sedang menggendong seseorang di punggungnya?",
  ui_story_5058_50581201_X4_dialog_content = "Ini Shashona!",
  ui_story_5058_50581201_5_dialog_content = "Ibu?!",
  ui_story_5058_50581201_6_dialog_content = "Apa yang kamu lakukan pada ibuku, Cena?!",
  ui_story_5058_50581201_7_dialog_content = "Aku…",
  ui_story_5058_50581201_8_dialog_content = "Astaga!!",
  ui_story_5058_50581201_9_dialog_content = "Heh, mereka masih terkejar.",
  ui_story_5058_50581201_10_dialog_content = "Mari kita singkirkan Eclipsite terlebih dahulu, Lorelei!",
  ui_story_5058_50581202_1_dialog_content = "Bopper mengatakan bahwa kamu dan Lorelei pergi ke ruang bawah tanah tetapi tidak pernah kembali, PlayerName. Carleen dan aku baru saja akan pergi memeriksa keadaanmu!",
  ui_story_5058_50581202_2_dialog_content = "Apakah ada Eclipsite lainnya di sana? Kau baik-baik saja?",
  ui_story_5058_50581202_3_dialog_content = "Oh, Vice, Carleen... Syukurlah kamu sudah bangun.",
  ui_story_5058_50581202_4_dialog_content = "Ada jalanan ke jantung lembah di ruang bawah tanah, tetapi kami telah menutupnya, jadi seharusnya tidak ada lagi Eclipsite.",
  ui_story_5058_50581202_5_dialog_content = "Sebuah jalanan di ruang bawah tanah...?",
  ui_story_5058_50581202_6_dialog_content = "Bagaimana tamu-tamunya, Bopper?",
  ui_story_5058_50581202_7_dialog_content = "Mereka semua telah bangun dari koma, tetapi... beberapa dari mereka meminta benda itu di udara.",
  ui_story_5058_50581202_8_dialog_content = "Mereka bilang mereka merasa baik setelah menghirupnya dan ingin kembali ke koma yang sama lagi!",
  ui_story_5058_50581202_9_dialog_content = "Persis seperti yang saya rasakan. Mungkin ini koma, tapi saya bangun dengan sangat segar.",
  ui_story_5058_50581202_10_dialog_content = "Aku juga! Tubuhku terasa ringan dan lembut seperti sedang terbang...",
  ui_story_5058_50581202_11_dialog_content = "Jika saya benar, barang itu mungkin memiliki koneksi dengan Dewi Denuo.",
  ui_story_5058_50581202_12_dialog_content = "Atau seharusnya aku bilang ke kamu... Cena?",
  ui_story_5058_50581202_13_dialog_content = "...",
  ui_story_5058_50581202_14_dialog_content = "Manajer umum Cena?! Kami mencari Anda ke mana-mana! Anda juga ada di ruang bawah tanah?",
  ui_story_5058_50581202_15_dialog_content = "Beritahu tamu bahwa tidak ada apa-apa di udara dan jual kepada mereka bahwa itu semua adalah halusinasi, Bopper.",
  ui_story_5058_50581202_16_dialog_content = "Kecanduan akan berhenti beberapa hari setelah mereka tiba di rumah.",
  ui_story_5058_50581202_17_dialog_content = "Apakah benda itu menyebabkan kecanduan?",
  ui_story_5058_50581202_18_dialog_content = "Aduh...",
  ui_story_5058_50581202_19_dialog_content = "Shashona? Apakah Eclipsite melukai dia? Saya akan segera mencari dokter...",
  ui_story_5058_50581202_20_dialog_content = "Tidak apa-apa, Bopper. Dokter rata-rata juga tidak bisa membantu, kok.",
  ui_story_5058_50581202_21_dialog_content = "Bisakah kamu ceritakan apa yang terjadi pada ibuku sekarang, Cena?",
  ui_story_5058_50581202_22_dialog_content = "Kamu benar, Lorelei, semua ini terjadi karena aku.",
  ui_story_5058_50581202_23_dialog_content = "Aku pergi mencari Dewi Denuo di lembah, tetapi gagal menyadari bahwa Ny. Shashona mengikutiku.",
  ui_story_5058_50581202_24_dialog_content = "Kemudian, kami bertemu dengan Dewi. Atau lebih tepatnya, seorang Dewi yang telah dewasa.",
  ui_story_5058_50581202_25_dialog_content = "Dewi Denuo?! Apakah ceritanya nyata? Apakah kamu mendapatkan berkat apa pun?",
  ui_story_5058_50581202_26_dialog_content = "Tidak pernah ada berkah atau perlindungan.",
  ui_story_5058_50581202_X26_dialog_content = "Dia mengaum, mengepakkan sayapnya, dan menghasilkan badai. Jika dia meninggalkan \"hadiah\" apa pun...",
  ui_story_5058_50581202_27_dialog_content = "Ini <color=#FFB400>serbuk</color> yang dia lepaskan. Banyak serbuk, bahkan cukup untuk masuk ke hotel melalui jalanan bawah tanah.",
  ui_story_5058_50581202_28_dialog_content = "Bubuk? Maksud kamu yang bercahaya di udara?",
  ui_story_5058_50581202_29_dialog_content = "Ya. Bubuk tersebut adalah zat neuro yang menyebabkan koma, halusinasi, atau pemulihan ingatan.",
  ui_story_5058_50581202_30_dialog_content = "Saya memiliki kekebalan tertentu sejak kecil, tetapi tidak untuk Bu Shashona...",
  ui_story_5058_50581202_31_dialog_content = "Dia menghirup terlalu banyak <color=#FFB400>serbuk</color> saat mencoba menyelamatkan aku.",
  ui_story_5058_50581202_32_dialog_content = "Tapi semua bubuknya sudah habis sekarang, kenapa ibu saya tidak bangun?",
  ui_story_5058_50581202_33_dialog_content = "Bukankah kamu membangunkanku dengan kemampuan psikis-mu, PlayerName? Bisakah kamu menyelamatkan ibuku, tolong?",
  ui_story_5058_50581202_34_dialog_content = "Tentu, saya akan mencoba.",
  ui_story_5058_50581202_35_option_content = "Force Boost!",
  ui_story_5058_50581202_36_dialog_content = "<color=#e8d9bb>Tik-tik-tik, tik-tik-tik…</color>",
  ui_story_5058_50581202_37_dialog_content = "Hujan, ya?",
  ui_story_5058_50581202_38_dialog_content = "*Hiks*",
  ui_story_5058_50581202_39_dialog_content = "Di mana kamu, Shashona?",
  ui_story_5058_50581202_40_dialog_content = "Apakah mimpinya mulai hancur?",
  ui_story_5058_50581202_41_dialog_content = "<size=45>Jawab aku, Shashona!</size>",
  ui_story_5058_50581202_42_dialog_content = "*Hiks*",
  ui_story_5058_50581202_43_dialog_content = "Dari mana asal suara itu?",
  ui_story_5058_50581202_44_dialog_content = "Sangat dingin... Jika ini terus berlanjut...",
  ui_story_5058_50581202_45_dialog_content = "Aku akan menjadi...",
  ui_story_5058_50581202_46_dialog_content = "<color=#e8d9bb>Plak!</color>",
  ui_story_5058_50581202_47_dialog_content = "Apa-apaan...",
  ui_story_5058_50581202_48_dialog_content = "Semua baik-baik saja, dia kembali.",
  ui_story_5058_50581202_49_dialog_content = "Oh, wajahku... Itu sakit.",
  ui_story_5058_50581202_50_dialog_content = "Berhenti menakut-nakuti kami seperti itu, PlayerName. Kami tidak bisa mendapatkan respons dari kamu!",
  ui_story_5058_50581202_51_dialog_content = "Jadi, saya harus mencoba menampar. Untungnya, itu berhasil.",
  ui_story_5058_50581202_52_dialog_content = "Jadi, bagaimana?",
  ui_story_5058_50581202_53_dialog_content = "Mimpinya hancur dan saya tidak bisa menemukannya sama sekali... Maaf.",
  ui_story_5058_50581202_54_dialog_content = "Kurasa dia mengambil lebih banyak bedak daripada yang kubayangkan.",
  ui_story_5058_50581202_55_dialog_content = "Jangan membuatku ketakutan seperti ini, Bu... Bangun!",
  ui_story_5058_50581202_56_dialog_content = "Kita belum pernah nongkrong di taman kita sendiri, dan masih banyak hal lainnya yang belum kita lakukan bersama...",
  ui_story_5058_50581202_57_dialog_content = "Mengapa kamu ngotot mencari Dewi Denuo, Cena?",
  ui_story_5058_50581202_58_dialog_content = "Terowongan di ruang bawah tanah dan file aneh... Saya percaya kamu berhutang penjelasan kepada Lorelei.",
  ui_story_5058_50581202_59_dialog_content = "Ada beberapa hal yang tidak sempat kubilang padamu sebelumnya, Lorelei.",
  ui_story_5058_50581202_60_dialog_content = "Karena kamu masih terlalu muda untuk memahami hal tersebut saat itu.",
  ui_story_5058_50581202_61_dialog_content = "EveSampai hari ini, saya masih berjuang apakah harus mengungkapkan kebenaran kepada Anda.",
  ui_story_5058_50581202_62_dialog_content = "Ketika aku melihat betapa semangatnya kamu untuk membangun kembali lembah itu...",
  ui_story_5058_50581202_63_dialog_content = "Nah, saya benar-benar berpikir mungkin saya bisa melupakan masa lalu dan memulai lagi, tapi ternyata saya salah.",
  ui_story_5058_50581202_64_dialog_content = "Dewi Denuo kembali.",
  ui_story_5058_50581202_65_dialog_content = "Kembali untuk <color=#FFB400>dendam</color>.",
  ui_story_5058_50581301_1_dialog_content = "Di lembah ini pernah berdiri sebuah desa kecil yang mandiri.",
  ui_story_5058_50581301_2_dialog_content = "Selama beberapa generasi, para penduduk desa percaya bahwa <color=#FFB400>Dewi Denuo</color> adalah dewa pelindung mereka, melindungi ngarai dari Eclipsite.",
  ui_story_5058_50581301_3_dialog_content = "Dikatakan bahwa orang yang melihat Dewi akan menerima berkat dan perlindungan darinya.",
  ui_story_5058_50581301_4_dialog_content = "Namun, tidak ada yang bisa memastikan bahwa Dewi itu nyata. Eveakhirnya, beberapa penduduk desa mengejek ide tersebut.",
  ui_story_5058_50581301_5_dialog_content = "Banyak yang mulai mengabaikan peringatan Dewi dalam cerita itu dan menjarah sumber daya lembah, mulai dari mineral, kemudian tanaman, bahkan...",
  ui_story_5058_50581301_6_dialog_content = "Apakah kamu menyimpan Dewi Denuo?",
  ui_story_5058_50581301_7_dialog_content = "Apakah itu seindah berlian seperti dalam cerita? Di mana kamu melihatnya?",
  ui_story_5058_50581301_8_dialog_content = "Bagaimana Anda bertanya, Ayah?",
  ui_story_5058_50581301_9_dialog_content = "Jika Dewi Denuo itu nyata, tentu saja kita harus memanfaatkannya.",
  ui_story_5058_50581301_10_dialog_content = "Tidak mungkin, Dewi adalah dewa pelindung kami!",
  ui_story_5058_50581301_11_dialog_content = "Kenapa, kamu nakal! Bagaimana berani pantat malasmu membantah saya! Apakah kamu pikir semua yang kamu dapatkan jatuh begitu saja dari langit?",
  ui_story_5058_50581301_12_dialog_content = "Saya bisa menjaga diri sendiri dengan baik sekarang, terima kasih!",
  ui_story_5058_50581301_13_dialog_content = "Baik, pergi dari hadapan mataku!",
  ui_story_5058_50581301_14_dialog_content = "Saya meninggalkan rumah dan diterima oleh Coco, ibu kandung Lorelei. Namun, yang mengejutkan, ayah saya dan orang lain masih menemukan di mana Dewi bersembunyi, kemudian menemukan banyak kupu-kupu bayi...",
  ui_story_5058_50581301_15_dialog_content = "Mereka ingin membuat contoh untuk dijual kepada orang kaya di Umbraton dan Lumopolis, hanya untuk secara tidak sengaja menemukan bahwa bubuk Dewi bisa menyebabkan koma yang nyaman.",
  ui_story_5058_50581301_16_dialog_content = "Jadi mereka menggunakannya untuk membuat dupa yang membuat ketagihan.",
  ui_story_5058_50581301_17_dialog_content = "Dupa Denuo...",
  ui_story_5058_50581301_18_dialog_content = "Benar. Dupanya menjadi sensasi seketika dan laris di seluruh Astra.",
  ui_story_5058_50581301_19_dialog_content = "Meskipun proses produksi memerlukan pengorbanan Dewi Denuo dan asap dupa berlebihan menyebabkan kerusakan saraf yang tidak dapat dipulihkan, para penduduk desa tetap memburu kupu-kupu seolah-olah mereka kerasukan.",
  ui_story_5058_50581301_20_dialog_content = "Denuo berkembang pesat, dan untuk mencegah orang luar mencuri formula tersebut, para penduduk desa menggali terowongan bawah tanah.",
  ui_story_5058_50581301_21_dialog_content = "Ini jalanan di belakang ruang bawah tanah!",
  ui_story_5058_50581301_22_dialog_content = "Terowongan menghubungkan bengkel desa ke jantung lembah untuk memudahkan ekspedisi kupu-kupu. Tetapi tidak ada yang mengharapkan...",
  ui_story_5058_50581301_23_dialog_content = "Tolong, semua orang, tolong tinggalkan Dewi Denuo sendirian!",
  ui_story_5058_50581301_24_dialog_content = "Belum pernah ada satu pun Eclipsite dalam sejarah Denuo, tapi sekarang...?",
  ui_story_5058_50581301_25_dialog_content = "Kami mendapatkan kumpulan mereka setiap hari.",
  ui_story_5058_50581301_26_dialog_content = "Ini peringatan dari Dewi Denuo! Kita mengambil begitu banyak dari lembah hingga kita bahkan memandang dewi pelindung kita!",
  ui_story_5058_50581301_27_dialog_content = "Haha, hahaha!",
  ui_story_5058_50581301_28_dialog_content = "Masih ada yang percaya bahwa Dewi Denuo adalah dewa pelindung kita? Saya tertawa terbahak-bahak.",
  ui_story_5058_50581301_29_dialog_content = "Sebuah kata nasihat, kupu-kupu tidak bisa melindungi jurang karena ia bahkan tidak bisa melindungi dirinya sendiri!",
  ui_story_5058_50581301_30_dialog_content = "Satu-satunya kebaikan yang mereka lakukan adalah serbuk yang mereka keluarkan saat mereka ketakutan.",
  ui_story_5058_50581301_31_dialog_content = "Eclipsite tertarik ke sini oleh Lumina yang kuat dalam bubuk.",
  ui_story_5058_50581301_32_dialog_content = "Jangan takut. Kami sudah membeli senjata paling canggih dengan uang yang kita dapat. Akan mudah membunuh Eclipsite.",
  ui_story_5058_50581301_33_dialog_content = "Kamu harus berterima kasih kepada kami karena telah mengusir Eclispites dan menjaga perdamaian untuk seseorang yang tidak peka terhadap waktu seperti kamu!",
  ui_story_5058_50581301_34_dialog_content = "Saya tidak butuh perlindungan Anda...",
  ui_story_5058_50581301_35_dialog_content = "Dan tolong berhenti merusak bibit yang saya tanam di lembah!",
  ui_story_5058_50581301_36_dialog_content = "Tunggu, apa dia bilang dia menanam pohon? Benar-benar lelucon...",
  ui_story_5058_50581301_37_dialog_content = "Saya hanya ingat betapa kerasnya ibu saya bekerja hanya untuk mencari nafkah.",
  ui_story_5058_50581301_38_dialog_content = "Aku tidak pernah tahu bahwa dia menanam pohon untuk ngarai yang semakin gersang bahkan sejak dulu!",
  ui_story_5058_50581301_39_dialog_content = "Tapi jika Coco tahu bahwa puluhan tahun kemudian, putrinya Lorelei menghidupkan kembali lembah itu, dia pasti akan bangga dan sangat gembira.",
  ui_story_5058_50581301_40_dialog_content = "Sayangnya, para penduduk desa menganggap dia bodoh karena tidak mengambil uang saat itu...",
  ui_story_5058_50581301_41_dialog_content = "Mereka tidak tahu bahwa Dewi yang murka akan segera menghujani kehancuran di Denuo.",
  ui_story_5058_50581301_42_dialog_content = "Hari itu, saya menyelinap ke tempat para penduduk desa menyimpan Dewi Denuo hanya untuk melihat semua kupu-kupu telah hilang...",
  ui_story_5058_50581301_43_dialog_content = "Semua kupu-kupu bayi yang mereka pelihara telah hilang, Coco...",
  ui_story_5058_50581301_44_dialog_content = "Siapa di desa yang akan melakukan hal seperti itu selain kamu dan aku?",
  ui_story_5058_50581301_45_dialog_content = "<color=#e8d9bb>Wuush, wuush...</color>",
  ui_story_5058_50581301_46_dialog_content = "Ini aneh. Biasanya tidak berangin sekitar waktu ini...",
  ui_story_5058_50581301_47_dialog_content = "Apakah kamu juga melihat sesuatu di angin, Cena?",
  ui_story_5058_50581301_48_dialog_content = "Bubuk?",
  ui_story_5058_50581301_49_dialog_content = "?!",
  ui_story_5058_50581301_50_dialog_content = "Ini Dewi Denuo... Dia marah karena menyadari anak-anaknya telah dibunuh!",
  ui_story_5058_50581301_51_dialog_content = "Angin ini tidak akan berhenti. Kita harus berlari menyelamatkan diri, Cena, sekarang!",
  ui_story_5058_50581301_52_dialog_content = "Oh tidak, Lorelei masih di rumah...",
  ui_story_5058_50581301_53_dialog_content = "Kami kembali untuk mengambil Lorelei agar bisa meninggalkan lembah melalui jalur yang ditandai dengan sedikit tumbuhan.",
  ui_story_5058_50581301_54_dialog_content = "Tapi di perjalanan, saya tidak menyadari ada batu besar yang goyah di atas...",
  ui_story_5058_50581301_55_dialog_content = "Coco mendorong saya keluar dari jalannya hanya untuk dirinya sendiri tertindih oleh batu.",
  ui_story_5058_50581301_56_dialog_content = "Mengapa kamu menyelamatkan aku? Orang seperti aku tidak layak untuk usaha itu...",
  ui_story_5058_50581301_57_dialog_content = "Nak bodoh... *Batuk-batuk*... Aku selalu menganggap kamu sebagai keluargaku.",
  ui_story_5058_50581301_58_dialog_content = "Tunggu sebentar, Coco. Aku akan mencari sesuatu untuk menggeser batu besar itu dari atas kamu!",
  ui_story_5058_50581301_59_dialog_content = "Aku sudah selesai... Even jika kamu memindahkan batu besar itu, *batuk-batuk*... Aku masih tidak bisa berjalan atau pergi.",
  ui_story_5058_50581301_60_dialog_content = "Terima kasih, Cena... telah membantu saya selama bertahun-tahun ini. *Batuk-batuk*... Saya punya satu permintaan terakhir untukmu...",
  ui_story_5058_50581301_61_dialog_content = "Berlari... Ambil Lorelei dan... berlari...!",
  ui_story_5058_50581301_62_dialog_content = "Lorelei... Lorelei?!",
  ui_story_5058_50581301_63_dialog_content = "Saat itulah saya menyadari bahwa Lorelei muda itu tersapu ke tanah dan pingsan.",
  ui_story_5058_50581301_64_dialog_content = "Saya mengambil Lorelei tetapi sebelum pergi, saya menoleh ke Coco hanya untuk melihat...",
  ui_story_5058_50581301_65_dialog_content = "Warna di wajahnya perlahan memudar di bawah beban batu yang berat.",
  ui_story_5058_50581301_66_dialog_content = "Ketidakberdayaan, penyesalan, kesalahan... Begitu banyak emosi yang menyerbu saya sekaligus. Saya percaya itu semua adalah hukuman dari Dewi Denuo kepada para penduduk desa.",
  ui_story_5058_50581301_67_dialog_content = "Dan saya adalah orang yang paling pantas dihukum. Jika saya tidak menemukan Dewi muda itu, tidak ada hal ini yang akan terjadi.",
  ui_story_5058_50581301_68_dialog_content = "Tepat ketika aku akan menyerah dan menyambut ajal di badai pasir, aku melirik Lorelei dan teringat permintaan terakhir Coco.",
  ui_story_5058_50581301_69_dialog_content = "Untuk Coco, untuk Lorelei, aku harus kabur...",
  ui_story_5058_50581301_70_dialog_content = "Badai pasir benar-benar menghancurkan Denuo. Hampir tidak ada yang selamat selain saya dan Lorelei.",
  ui_story_5058_50581301_71_dialog_content = "Tapi kemudian kamu menyerahkan aku kepada Shashona, ibu baru ku.",
  ui_story_5058_50581301_72_dialog_content = "Dia sudah sangat kaya. Lebih lagi, dia sangat menyukai kamu, berjanji untuk menyembuhkanmu hingga sehat kembali dan memperlakukanmu seperti keluarga sendiri.",
  ui_story_5058_50581301_73_dialog_content = "Itu jauh lebih baik daripada tinggal bersama orang miskin seperti aku.",
  ui_story_5058_50581301_74_dialog_content = "Belum lagi dia menepati janjinya.",
  ui_story_5058_50581301_75_dialog_content = "Jadi siapa yang membebaskan kupu-kupu bayi pada hari badai pasir itu?",
  ui_story_5058_50581301_76_dialog_content = "Ibu mereka. Siapa lagi kalau bukan?",
  ui_story_5058_50581301_77_dialog_content = "Dewi Denuo membebaskan anak-anaknya sebelum menghukum desa!",
  ui_story_5058_50581301_78_dialog_content = "Jadi, bukan hanya dia tidak melindungi orang-orang, tetapi malah berbalik dan menghukum mereka?",
  ui_story_5058_50581301_79_dialog_content = "Mengapa kamu tidak memberitahuku itu sejak awal?",
  ui_story_5058_50581301_80_dialog_content = "Kamu masih terlalu muda saat itu. Coco juga tidak ingin kamu tahu.",
  ui_story_5058_50581301_81_dialog_content = "Bagaimana dengan sekarang? Kamu tahu kebenarannya tapi setuju untuk menggunakan Dewi sebagai gimmick untuk mempromosikan taman!",
  ui_story_5058_50581301_82_dialog_content = "Mengapa kamu malah membiarkan kami pergi mencari kupu-kupu di lembah?",
  ui_story_5058_50581301_83_dialog_content = "Mengapa kamu memberitahu saya bahwa kamu akan membuat Dupa Denuo yang diinginkan oleh Dewan?",
  ui_story_5058_50581301_84_dialog_content = "Apakah kamu mencoba mengulangi tragedi itu lagi?",
  ui_story_5058_50581301_85_dialog_content = "Atau sebenarnya kamu menantikan hukuman yang disebut-sebut dari Dewi dan merencanakan semuanya?",
  ui_story_5058_50581301_86_dialog_content = "Nah, bagaimana seharusnya saya menjawab semua itu?",
  ui_story_5058_50581301_87_dialog_content = "Mayjadi ya, mungkin tidak...",
  ui_story_5058_50581301_88_dialog_content = "Sejak saya memberikanmu kepada Nyonya Shashona, saya telah berkeliaran di Astra...",
  ui_story_5058_50581301_X88_dialog_content = "Setelah semua yang telah saya alami, saya masih tidak bisa menghilangkan sandstorm dari pikiran saya.",
  ui_story_5058_50581301_89_dialog_content = "Mayseharusnya aku mati saat itu juga, bukan hidup seperti pengecut.",
  ui_story_5058_50581301_90_dialog_content = "Jadi...|Saya kembali.",
  ui_story_5058_50581301_X90_dialog_content = "Meskipun lebih dari sepuluh tahun telah berlalu, akhirnya saya mengumpulkan keberanian untuk kembali dan menghadapi penghakiman Dewi Denuo.",
  ui_story_5058_50581301_91_dialog_content = "Tetapi ketika saya tiba, saya menemukan bahwa Lembah Denuo telah menjadi gurun, dan Dewi Denuo tidak dapat ditemukan di mana pun.",
  ui_story_5058_50581301_92_dialog_content = "Tepat ketika saya berpikir untuk mengakhiri semuanya, saya menemukan bahwa seseorang ternyata mulai membangun kembali Lembah Denuo!",
  ui_story_5058_50581301_93_dialog_content = "Saat itu, saya tidak tahu apa-apa. Saya hanya tidak ingin melihat satu-satunya rumah yang pernah saya kenal menjadi tanah tandus.",
  ui_story_5058_50581301_94_dialog_content = "Pada saat itu, aku melihat Coco hidup melalui dirimu. Aku tahu jika dia ada di sana, dia pasti akan melakukan hal yang sama...",
  ui_story_5058_50581301_95_dialog_content = "Desa Denuo telah dihukum karena meninggalkan imannya, dan lembah itu menjadi terbuang sebagai akibatnya.",
  ui_story_5058_50581301_96_dialog_content = "Namun, mengingat Dewi Denuo tampaknya telah menghilang dari lembah, apakah hukumannya sudah berakhir?",
  ui_story_5058_50581301_97_dialog_content = "Maysetelah Maymembangun kembali Lembah, segalanya akan kembali seperti sebelumnya—kembali ke masa sebelum Dewi Denuo dicemooh.",
  ui_story_5058_50581301_98_dialog_content = "Jadi, saya membuat pilihan saya. Saya memilih untuk hidup... untuk membantu Anda mengembalikan lembah ke kejayaan sebelumnya...",
  ui_story_5058_50581301_99_dialog_content = "Saya ingin menyaksikan kebangkitan lembah yang megah dengan mata saya sendiri!",
  ui_story_5058_50581301_100_dialog_content = "Kamu lupa tentang jalanan bawah tanah...",
  ui_story_5058_50581301_101_dialog_content = "Saya pikir setiap jejak terakhir dari Desa Denuo telah hilang tersapu dalam badai pasir.",
  ui_story_5058_50581301_102_dialog_content = "Tahun-tahun kemudian, saya mengetahui bahwa terowongan yang digunakan para penduduk desa untuk menangkap Dewi Denuo masih utuh.",
  ui_story_5058_50581301_103_dialog_content = "Saya menemukan diri saya menghadapi dilema. Saya mempertimbangkan untuk membakar seluruh gua dan menguburnya selamanya...",
  ui_story_5058_50581301_104_dialog_content = "Tapi Desa Denuo adalah rumahku. Bagaimana bisa aku tega menghancurkan sisa-sisa terakhir dari rakyatku?",
  ui_story_5058_50581301_105_dialog_content = "Saya pikir mungkin suatu hari nanti, saya akan menyerahkan kebenaran tentang apa yang terjadi di desa itu ke tanganmu, Lorelei. Kamu bisa memutuskan sendiri apa yang akan terjadi pada reruntuhan di sana.",
  ui_story_5058_50581301_106_dialog_content = "Saya hanya tidak pernah menyangka hari ini akan datang begitu cepat! Saya kira saya tidak berpikir Dewi Denuo masih menyimpan dendam yang begitu abadi terhadap para penduduk desa...",
  ui_story_5058_50581301_107_dialog_content = "Dia kembali untuk membalas dendam! Kembali untuk menghukum saya, orang berdosa yang lolos dari kematian kejam di bawah pasir!",
  ui_story_5058_50581301_108_dialog_content = "Cukup! Cena, kamu terlalu serius menghadapi semua ini.",
  ui_story_5058_50581301_109_dialog_content = "Dendam, dosa... Semua ide liar ini hanyalah hasil dari pikiran yang terlalu aktif.",
  ui_story_5058_50581301_110_dialog_content = "Even jika Dewi-Dewi Denuo memang memiliki kekuatan mistis, itu bukan jenis kekuatan yang dapat menyebabkan badai pasir yang mampu menghancurkan seluruh desa.",
  ui_story_5058_50581301_111_dialog_content = "Maymungkin ini bukan semacam hukuman ilahi, tetapi lebih seperti penduduk desa Denuo menuai apa yang mereka tabur.",
  ui_story_5058_50581301_112_dialog_content = "Hewan dan tumbuhan di lembah menciptakan suaka bagi penghuni tanah tandus ini, tetapi ketika keseimbangan itu rusak, sangat wajar jika perlindungan mereka hilang.",
  ui_story_5058_50581301_113_dialog_content = "Lorelei, percaya atau tidak... Aku sudah memutuskan untuk mencari Dewi Denuo dan akhirnya menerima hukuman yang seharusnya kuterima.",
  ui_story_5058_50581301_114_dialog_content = "Jika apa yang kamu katakan itu benar... bukankah aku harus menerima semacam hukuman? Maksudku, aku juga bagian dari Desa Denuo saat itu.",
  ui_story_5058_50581301_115_dialog_content = "Kamu tidak ada hubungannya dengan semua itu. Kamu hanya seorang anak kecil saat itu, kamu bahkan tidak tahu apa yang sedang terjadi.",
  ui_story_5058_50581301_116_dialog_content = "Dan... Dan aku berjanji pada Coco bahwa aku akan pastikan kamu hidup lama dan bahagia!",
  ui_story_5058_50581301_117_dialog_content = "Bahagia? Bagaimana saya bisa bahagia ketika ibu saya dalam keadaan koma!",
  ui_story_5058_50581301_118_dialog_content = "Saya tidak menyangka sesuatu yang begitu serius terjadi pada Shashona, tetapi memang benar bahwa beberapa orang diketahui jatuh ke dalam keadaan vegetatif persisten setelah menghirup jumlah Denuo Incense yang berlebihan.",
  ui_story_5058_50581301_119_dialog_content = "Apa?!",
  ui_story_5058_50581301_120_dialog_content = "Tapi aku ingat... ada penawar yang bisa menetralisir racun di neraca Dewi Denuo, meskipun sulit untuk didapatkan.",
  ui_story_5058_50581301_121_dialog_content = "Saya tidak peduli seberapa sulitnya! Tolong, beritahu saya cara mendapatkannya!",
  ui_story_5058_50581301_122_dialog_content = "Nah, ini semacam lendir.",
  ui_story_5058_50581301_123_dialog_content = "Untuk lebih tepatnya, itu adalah lendir yang dihasilkan Dewi Denuo saat memproduksi telur.",
  ui_story_5058_50581401_1_dialog_content = "<color=#e8d9bb>*Crowd bergumam*</color>",
  ui_story_5058_50581401_2_dialog_content = "Ada apa? Sepertinya kita punya pelanggan yang tidak puas di tangan kita...",
  ui_story_5058_50581401_3_dialog_content = "Bos, ini staf...",
  ui_story_5058_50581401_4_dialog_content = "Everyone baru saja mendengar cerita tentang Dewi Denuo yang datang untuk membalas dendam, dan mereka semua ketakutan. Sejumlah besar dari mereka ingin berhenti dan segera keluar dari sini!",
  ui_story_5058_50581401_5_dialog_content = "Oh...",
  ui_story_5058_50581401_6_dialog_content = "Bos, situasi ini perlu diselesaikan segera... Bagaimana kalau kita tutup resort untuk sementara, untuk keselamatan staf dan tamu...?",
  ui_story_5058_50581401_7_dialog_content = "Tutup resor dan biarkan kita pergi, bos!",
  ui_story_5058_50581401_8_dialog_content = "Kita tidak boleh menderita kemarahan Dewi Denuo!",
  ui_story_5058_50581401_9_dialog_content = "EveSetiap orang, tolong tenang sejenak.",
  ui_story_5058_50581401_10_dialog_content = "Selesai saja, bos!",
  ui_story_5058_50581401_11_dialog_content = "Ayo pulang! Ayo pergi!",
  ui_story_5058_50581401_12_dialog_content = "Karyawan saya sendiri... bahkan tidak memercayai saya lagi.",
  ui_story_5058_50581401_13_dialog_content = "Mereka semua akan membelakangi saya?",
  ui_story_5058_50581401_14_dialog_content = "Akhirnya saya bisa sampai sejauh ini, tapi tidak pernah terpikirkan bahwa hal seperti ini akan terjadi... dan semua ini karena kecerobohan saya sendiri...",
  ui_story_5058_50581401_15_dialog_content = "Mungkin seharusnya aku mendengarkan Ibu sejak awal daripada berusaha keras membuktikan diri...",
  ui_story_5058_50581401_16_dialog_content = "Ini semua salah ku... Saya belum memiliki kemampuan untuk membuat bisnis seperti ini berhasil...",
  ui_story_5058_50581401_17_dialog_content = "Kamu tidak bisa berpikir seperti itu, Lorelei!",
  ui_story_5058_50581401_18_dialog_content = "Ya, Lorelei! Pembicaraan pesimis seperti ini sama sekali tidak seperti dirimu.",
  ui_story_5058_50581401_19_dialog_content = "Coba pikirkan bagaimana kamu berhasil membangun kembali lembah ini dan mendirikan resor mewah di sini... Jelas, kamu memang ahli dalam hal semacam ini!",
  ui_story_5058_50581401_20_dialog_content = "Saya sangat setuju, saya tidak pikir kamu perlu membuktikan dirimu kepada siapa pun!",
  ui_story_5058_50581401_21_dialog_content = "Tapi Mama tidak pernah mengatakan hal baik tentangku, dan sekarang dia koma, dan itu semua salah ku...",
  ui_story_5058_50581401_22_dialog_content = "Saya yakin Shashona tahu betapa hebatnya kamu.",
  ui_story_5058_50581401_23_dialog_content = "Sejak pertama kali bertemu dengannya, saya bisa langsung merasakan betapa bangganya dia dengan resor Anda!",
  ui_story_5058_50581401_24_dialog_content = "Tapi ibu... dia tidak pernah bilang kata baik tentang resor itu kepadaku.",
  ui_story_5058_50581401_25_dialog_content = "Oh, saya juga tidak akan pernah menebak... Jadi, ternyata Ms. Shashona yang cerdik itu berusaha keras menyembunyikan perasaan sebenarnya dari putrinya.",
  ui_story_5058_50581401_26_dialog_content = "Sepertinya dia hanya belum siap untuk—",
  ui_story_5058_50581401_27_dialog_content = "Tidak! Lorelei...",
  ui_story_5058_50581401_28_dialog_content = "Ibu?",
  ui_story_5058_50581401_29_dialog_content = "Jangan tinggalkan aku...",
  ui_story_5058_50581401_30_dialog_content = "Aku tak pernah berencana meninggalkanmu, Ibu... Kamu dengar aku?",
  ui_story_5058_50581401_31_dialog_content = "...",
  ui_story_5058_50581401_32_dialog_content = "Jadi, ini yang selama ini kamu takutkan?",
  ui_story_5058_50581401_33_dialog_content = "Ibu...",
  ui_story_5058_50581401_34_dialog_content = "Bos, staf... Mereka semua masih menunggu jawaban...",
  ui_story_5058_50581401_35_dialog_content = "Aku mengerti.",
  ui_story_5058_50581401_36_dialog_content = "Mam, aku tidak akan mundur sekarang.",
  ui_story_5058_50581401_37_dialog_content = "Saya tidak sampai di posisi sekarang ini untuk siapa pun selain diri saya sendiri... Saya punya mimpi sendiri.",
  ui_story_5058_50581401_38_dialog_content = "Saya memilih untuk mengikuti jalur terberat di depan saya untuk mewujudkan mimpi ini, dan saya menyadari sesuatu waktu yang lalu.",
  ui_story_5058_50581401_39_dialog_content = "Tidak peduli kesulitan apa yang datang, saya harus menghadapinya dengan tegar!",
  ui_story_5058_50581401_40_dialog_content = "Bukan sebagai seorang putri, bukan sebagai pengusaha pemula, bukan sebagai oportunis yang mencari keuntungan...",
  ui_story_5058_50581401_41_dialog_content = "Tetapi sebagai bos dengan karyawan yang harus dipimpin dan pelanggan yang harus dilayani! Seorang bos yang dengan berani menghadapi dan menyelesaikan masalahnya!",
  ui_story_5058_50581401_42_dialog_content = "Sepertinya Lorelei yang kita kenal dan cintai telah kembali!",
  ui_story_5058_50581401_43_dialog_content = "Terima kasih, PlayerName...",
  ui_story_5058_50581401_44_dialog_content = "Karyawan Denuo Valley Resort! Dengarlah!",
  ui_story_5058_50581401_45_dialog_content = "Saya tahu kalian semua merasa takut sekarang, dan pasti memiliki banyak pertanyaan. Saya gagal melakukan investigasi awal yang menyeluruh di area tersebut, dan saya minta maaf untuk itu.",
  ui_story_5058_50581401_46_dialog_content = "Jadi, pertama, saya hanya ingin mengatakan... Saya sangat minta maaf, semua orang!",
  ui_story_5058_50581401_47_dialog_content = "Membuat resor ini sukses... Yah, itu impianku.",
  ui_story_5058_50581401_48_dialog_content = "Dibutuhkan begitu banyak darah, keringat, dan air mata bagi kami untuk mengubah lembah ini bersama.",
  ui_story_5058_50581401_49_dialog_content = "Dan karena hal ini, Denuo Valley Resort bukan lagi sekadar impian saya.",
  ui_story_5058_50581401_50_dialog_content = "EveSetiap batu bata di tempat ini, setiap ubin, menanggung tanda abadi dari kerja keras setiap orang. Ini adalah impian kita bersama—ini adalah rumah kita!",
  ui_story_5058_50581401_51_dialog_content = "Jadi, kita telah menghadapi rintangan pertama. Saya tidak ingin menutup resor dan langsung menyerah hanya karena ini...",
  ui_story_5058_50581401_52_dialog_content = "Saya tidak bisa membelakangi mimpi kita, saya tidak akan meninggalkan rumah yang telah kita bangun dengan susah payah!",
  ui_story_5058_50581401_53_dialog_content = "Aku tahu kalian semua takut, aku tahu kalian cemas, dan jujur saja, ini adalah pertama kalinya aku menghadapi masalah seperti ini.",
  ui_story_5058_50581401_54_dialog_content = "Tapi saya ingin kalian semua tahu bahwa saya mengambil alih situasi ini, dan saya berjanji akan menyelesaikan masalah ini secepat mungkin.",
  ui_story_5058_50581401_55_dialog_content = "Meskipun masa depan mungkin tidak pasti, tolong, beri aku sedikit waktu lagi... Aku janji aku akan membuat ini benar!",
  ui_story_5058_50581401_56_dialog_content = "...",
  ui_story_5058_50581401_57_dialog_content = "Karena bos mengatakannya dengan begitu...",
  ui_story_5058_50581401_58_dialog_content = "Saya ingin keluarga saya mengunjungi resor itu!",
  ui_story_5058_50581401_59_dialog_content = "Dan aku ingin teman-temanku melihat tempat kerja keren yang aku bekerja di...",
  ui_story_5058_50581401_60_dialog_content = "Saya juga berharap Anda dapat menemukan kekuatan untuk kembali ke pos Anda dan melanjutkan melayani pelanggan kami saat ini dengan sebaik-baiknya.",
  ui_story_5058_50581401_61_dialog_content = "Saya perlu tahu bahwa kalian semua mendukung saya! Tolong, beri saya keberanian untuk melanjutkan dan mengurus semua ini!",
  ui_story_5058_50581401_62_dialog_content = "Saya percaya selama kita bekerja sama, kita pasti akan mengatasi hambatan kecil ini dan membuat resor kembali ke jalur yang benar!",
  ui_story_5058_50581401_63_dialog_content = "Aku percaya pada masing-masing dan setiap dari kalian... Apakah kalian akan percaya padaku?",
  ui_story_5058_50581401_64_dialog_content = "...",
  ui_story_5058_50581401_65_dialog_content = "Bos, saya... saya percaya padamu!",
  ui_story_5058_50581401_66_dialog_content = "Kami percaya pada kamu, Lorelei!",
  ui_story_5058_50581401_67_dialog_content = "Percaya kamu, percaya kamu, percaya kamu!",
  ui_story_5058_50581401_68_dialog_content = "Lorelei... sepertinya lebih dewasa dari sebelumnya, menurutmu?",
  ui_story_5058_50581401_69_dialog_content = "Saya pikir dia selalu menjadi seorang wanita pengusaha yang cukup matang, tetapi sekarang dia memiliki sedikit lebih kekuatan dan keyakinan daripada sebelumnya.",
  ui_story_5058_50581401_70_dialog_content = "PlayerName, apa yang sedang kalian bisikkan berdua?",
  ui_story_5058_50581401_71_dialog_content = "Dia baru saja memuji-muji Anda, Lorelei!",
  ui_story_5058_50581401_72_dialog_content = "Hah?",
  ui_story_5058_50581401_73_dialog_content = "Terima kasih, PlayerName... Terima kasih kalian semua...",
  ui_story_5058_50581401_74_dialog_content = "Tapi sekarang saya butuh bantuan dari kalian semua.",
  ui_story_5058_50581401_75_dialog_content = "Baik, kami akan mengurus Eclipsite yang tersisa di sekitar sini.",
  ui_story_5058_50581401_76_dialog_content = "Dan saya juga ingin mencari tahu dasar dari semua ini.",
  ui_story_5058_50581401_77_dialog_content = "Maksudmu…",
  ui_story_5058_50581401_78_dialog_content = "Saya perlu pergi jauh ke dalam lembah dan menemukan Dewi Denuo, mencari tahu apa yang dia inginkan, dan... menemukan penawar untuk ibu saya.",
  ui_story_5058_50581401_79_dialog_content = "Sepertinya kita menuju ke arah yang sama, ya.",
  ui_story_5058_50581401_80_dialog_content = "Ikutlah denganku. Hati-hati saja—debu sisik itu sepertinya menarik Eclipsite.",
  ui_story_5058_50581401_81_dialog_content = "Juga, tutupi hidung dan mulut Anda dengan kain basah agar Anda tidak jatuh sebelum kami tiba di sana.",
  ui_story_5058_50581501_1_dialog_content = "Rapid Torrent!",
  ui_story_5058_50581501_2_dialog_content = "Ugh...",
  ui_story_5058_50581501_3_dialog_content = "Ada banyak Eclipsite di sekitar sini!",
  ui_story_5058_50581501_4_dialog_content = "Mengapa debu skala tidak mempengaruhi Eclipsites?",
  ui_story_5058_50581501_5_dialog_content = "Saya menduga ini karena fisiologi mereka berbeda dari kita, meskipun mereka tertarik dan terangsang oleh Lumina dalam bubuk itu.",
  ui_story_5058_50581501_6_dialog_content = "Sudah jelas di mana konsentrasi debu skala tertinggi berada—di situlah Anda akan menemukan gugusan Eclipsite terbesar...",
  ui_story_5058_50581501_7_dialog_content = "Groar!",
  ui_story_5058_50581501_8_dialog_content = "Minggir!",
  ui_story_5058_50581501_9_dialog_content = "Rasanya semakin jauh kita pergi, semakin banyak debu sisik yang ada. Apakah itu berarti kita semakin dekat dengan Dewi Denuo?",
  ui_story_5058_50581501_10_dialog_content = "Tunggu, saya merasakan sesuatu yang penuh dengan Lumina menghantam ke arah kita...",
  ui_story_5058_50581501_11_dialog_content = "Mayapakah itu seorang Aurorian yang datang untuk membantu kita?",
  ui_story_5058_50581501_12_dialog_content = "Tapi saya tidak meminta orang lain untuk datang membantu kita.",
  ui_story_5058_50581501_13_dialog_content = "Yah, sepertinya hanya ada satu kemungkinan...",
  ui_story_5058_50581501_14_dialog_content = "Itu mereka!",
  ui_story_5058_50581501_15_dialog_content = "<color=#e8d9bb>Whoosh—Whoosh—</color>",
  ui_story_5058_50581501_16_dialog_content = "<size=45>Desis!</size>",
  ui_story_5058_50581501_17_dialog_content = "Hah? I-Ini...!",
  ui_story_5058_50581501_18_dialog_content = "Ini Dewi Denuo...",
  ui_story_5058_50581501_19_dialog_content = "!!!",
  ui_story_5058_50581501_20_dialog_content = "Tapi hal ini benar-benar berbeda dari stiker Dewi Denuo yang imut itu!",
  ui_story_5058_50581501_21_dialog_content = "Stiker itu menunjukkan kepada kamu bagaimana bentuk benda-benda ini ketika baru menetas. Dewi Denuo yang mengapung di depan kita sekarang ini adalah <color=#FFB400>ratu kupu-kupu</color> yang sudah dewasa, siap untuk bertelur...",
  ui_story_5058_50581501_22_dialog_content = "<size=45>Siul, siul, siul!</size>",
  ui_story_5058_50581501_23_dialog_content = "<color=#e8d9bb>Whoosh—Whoosh—</color>",
  ui_story_5058_50581501_24_dialog_content = "EveSemua orang, temukan tanaman untuk bersembunyi di belakangnya agar kamu tidak terhempas oleh sayap Denuo Goddess yang bergerak!",
  ui_story_5058_50581501_25_dialog_content = "Dewi Denuo, legenda mengatakan bahwa Anda memiliki kebijaksanaan yang tak tertandingi, jadi tentu saja Anda dapat memahami apa yang sedang saya sampaikan kepada Anda sekarang, benar?",
  ui_story_5058_50581501_26_dialog_content = "<size=45>Desis!</size>",
  ui_story_5058_50581501_27_dialog_content = "Hati-hati, Lorelei!",
  ui_story_5058_50581501_28_dialog_content = "Ugh...",
  ui_story_5058_50581501_29_dialog_content = "Cena?!",
  ui_story_5058_50581501_30_dialog_content = "Bisakah kamu ingat ada yang menyebutkan bahwa Dewi Denuo masih sekuat ini?",
  ui_story_5058_50581501_31_dialog_content = "Kurasa tidak.",
  ui_story_5058_50581501_32_dialog_content = "Uhuk, uhuk... Tampaknya kemarahan Dewi Denuo tidak akan mudah untuk diredakan...",
  ui_story_5058_50581501_33_dialog_content = "Keluar dari sini, cepat. Biarkan saya menangani ini sendiri.",
  ui_story_5058_50581501_34_dialog_content = "Apa sih kamu ngomongin!",
  ui_story_5058_50581501_35_dialog_content = "<size=45>Siul, siul, siul!</size>",
  ui_story_5058_50581502_1_dialog_content = "Dewi Denuo, ini semua adalah salah paham yang besar!",
  ui_story_5058_50581502_2_dialog_content = "Kami tidak ingin menyakiti kamu... Kami tidak bisa meskipun kami ingin!",
  ui_story_5058_50581502_3_dialog_content = "<size=45>Siul, siul, siul!</size>",
  ui_story_5058_50581502_4_dialog_content = "Mama saya koma... Dia menghirup terlalu banyak debu sisikmu, dan kamu adalah satu-satunya yang bisa—",
  ui_story_5058_50581502_5_dialog_content = "Tidak ada gunanya...",
  ui_story_5058_50581502_6_dialog_content = "Mengapa? Cena, apakah kamu tidak bisa berkomunikasi dengan serangga? Apakah kamu tahu apa yang dikatakan oleh Dewi Denuo?",
  ui_story_5058_50581502_7_dialog_content = "Dewi Denuo... dia hanya mengatakan \"jangan pernah maafkan, jangan pernah maafkan, jangan pernah maafkan\" berulang-ulang...",
  ui_story_5058_50581502_8_dialog_content = "!!!",
  ui_story_5058_50581502_9_dialog_content = "Sekarang kalian semua tahu, dia kembali untuk balas dendam!",
  ui_story_5058_50581502_10_dialog_content = "<size=45>Siul, siul, siul!</size>",
  ui_story_5058_50581502_11_dialog_content = "Ugh...",
  ui_story_5058_50581502_12_dialog_content = "Lorelei!!!",
  ui_story_5058_50581502_13_dialog_content = "Kamu baik-baik saja, Lorelei?!",
  ui_story_5058_50581502_14_dialog_content = "Uhuk, uhuk... Saya... Saya masih bertahan...",
  ui_story_5058_50581502_15_dialog_content = "Jika kita terpaksa mengerahkan tenaga seperti ini lebih lama lagi, saya khawatir situasi bisa berubah menjadi lebih buruk.",
  ui_story_5058_50581502_16_dialog_content = "Ayo, Lorelei! Biarkan aku membantumu berdiri!",
  ui_story_5058_50581502_17_dialog_content = "Eh... Apa itu yang mau jatuh dari pohon ini?",
  ui_story_5058_50581502_18_dialog_content = "Dewi Denuo, jika kamu ingin menghukum seseorang, hukum aku saja, dan hanya aku!",
  ui_story_5058_50581502_19_dialog_content = "Lebih dari sepuluh tahun lalu, saya kebetulan menyelamatkan seorang Dewi Denuo secara tidak sengaja dan ceroboh sehingga seluruh desa mengetahuinya...",
  ui_story_5058_50581502_20_dialog_content = "Wusss...?",
  ui_story_5058_50581502_21_dialog_content = "Benar, itu aku... Jika bukan karena tindakanku, penduduk Desa Denuo tidak akan pernah semena-mena menangkap Dewi Denuo...",
  ui_story_5058_50581502_22_dialog_content = "Saya yang seharusnya menghadapi hukuman ilahi di badai pasir itu! Tapi saya malah lari...",
  ui_story_5058_50581502_23_dialog_content = "Aku harus kabur! Seseorang yang sangat penting bagiku memberi misi, dan aku harus menyelesaikannya!",
  ui_story_5058_50581502_24_dialog_content = "Saya melarikan diri lebih dari sepuluh tahun lalu, dan jiwa saya tersiksa sejak itu. Saya berdiri di sini di hadapan Anda mencari penebusan!",
  ui_story_5058_50581502_25_dialog_content = "Tapi tolong biarkan saya menanggung dosa-dosa masa lalu sendirian.",
  ui_story_5058_50581502_26_dialog_content = "Ini tidak ada hubungannya dengan Lorelei dan anak-anak muda lainnya di sana, atau tamu-tamu di resor...",
  ui_story_5058_50581502_27_dialog_content = "Saya bersedia memberikan hidup saya untuk membuat ini benar!",
  ui_story_5058_50581502_28_dialog_content = "Tolong, berikan saja mereka penawar racun debu sisik itu dan biarkan mereka pergi...",
  ui_story_5058_50581502_29_dialog_content = "(Apakah terlihat seperti... Dewi Denuo telah... tenang?)",
  ui_story_5058_50581502_30_dialog_content = "Dewi Denuo, silahkan... berikan aku akhir yang paling menyakitkan yang bisa kau berikan dengan sayap mematikanmu...",
  ui_story_5058_50581502_31_dialog_content = "Mayseharusnya, aku mengakhiri hidupku di depan matamu dengan senjataku sendiri...",
  ui_story_5058_50581502_32_dialog_content = "Apa yang sedang kamu lakukan, Cena?!",
  ui_story_5058_50581502_33_dialog_content = "Saya menyadari ketika kita bertemu lagi saat itu bagaimana kamu selalu berusaha untuk tampil sebagai pria dewasa yang tahu banyak tentang dunia!",
  ui_story_5058_50581502_34_dialog_content = "Kenyataannya, kamu sama sekali belum dewasa! Yang kamu lakukan hanyalah menghindari masalahmu daripada mencoba untuk mengatasinya!",
  ui_story_5058_50581502_35_dialog_content = "Apakah satu-satunya hal yang kamu hidupi hanyalah penebusan? Kamu bahkan tidak melakukan kesalahan saat itu!",
  ui_story_5058_50581502_36_dialog_content = "Ibu... Coco menyelamatkanmu dulu, dan Shashona juga menyelamatkanmu.",
  ui_story_5058_50581502_37_dialog_content = "Dan alasan mereka melakukannya adalah karena mereka pikir kamu pantas diselamatkan! Tapi lihat dirimu! Mengapa kamu terus berusaha membuang hidupmu seperti ini?",
  ui_story_5058_50581502_38_dialog_content = "Anda ingin orang mengatakan bahwa ibu saya sama-sama bodoh yang menyerahkan hidup mereka dengan sia-sia ?!",
  ui_story_5058_50581502_39_dialog_content = "Tidak... Itu bukan...",
  ui_story_5058_50581502_40_dialog_content = "Dewi Denuo, tolong dengarkan aku. Yang ingin aku lakukan hanyalah menghapus kesalahpahaman di antara kita!",
  ui_story_5058_50581502_41_dialog_content = "Desis?",
  ui_story_5058_50581502_42_dialog_content = "Coco mengatakan padaku bahwa kamu memberikan berkat dan perlindungan kepada orang-orang yang kamu temui...",
  ui_story_5058_50581502_43_dialog_content = "Saya percaya apa yang dia katakan kepada saya, dan saya juga percaya bahwa kamu tidak akan pernah begitu kejam untuk menjatuhkan hukuman yang disebut-sebut sebagai hukuman ilahi yang begitu terpelintir.",
  ui_story_5058_50581502_44_dialog_content = "Saya kembali ke Lembah Denuo untuk menghidupkan kembali tempat ini! Saya tidak akan mengulangi kesalahan yang dilakukan penduduk desa dulu!",
  ui_story_5058_50581502_45_dialog_content = "Saya senang kamu juga kembali ke Lembah Denuo, karena ini berarti semua yang telah saya lakukan untuk memulihkan lembah ini tidak sia-sia...",
  ui_story_5058_50581502_46_dialog_content = "Fakta bahwa kamu akan meletakkan telur-telurmu di lembah lagi membuktikan bahwa aku telah membuat perbedaan!",
  ui_story_5058_50581502_47_dialog_content = "Sss, sss, sss!",
  ui_story_5058_50581502_48_dialog_content = "Dewi Denuo! Maksud saya tidak bermaksud menyakiti yang muda!",
  ui_story_5058_50581502_49_dialog_content = "Saya mengambil ini baru saja tanpa tahu apa itu... Di sini, biar saya kembalikan kepadamu!",
  ui_story_5058_50581502_50_dialog_content = "Aku paham... Kamu pikir kami ingin menyakiti anak kecil kamu, dan itu sebabnya kamu marah. Benar, 'kan?",
  ui_story_5058_50581502_51_dialog_content = "Sss, sss, sss, sss!",
  ui_story_5058_50581502_52_dialog_content = "Dia melihat... bahwa kami membawa jaring dan mencoba menangkap anak-anaknya.",
  ui_story_5058_50581502_53_dialog_content = "Ini semua salahku! Meskipun aku lahir di Lembah Denuo, aku hampir tidak tahu apa-apa tentang kamu...",
  ui_story_5058_50581502_54_dialog_content = "Saya membawa semua orang ke lembah ini... Sebenarnya, saya berharap bisa menemukan cara untuk membantu Dewi Denuo berkembang di sini lagi...",
  ui_story_5058_50581502_55_dialog_content = "Baru sekarang saya mengerti betapa naif dan arogannya saya berpikir seperti itu.",
  ui_story_5058_50581502_56_dialog_content = "Lembah ini adalah rumahku, dan resor ini adalah impian yang banyak dari kita sayangi... Itulah mengapa aku berjanji untuk melindungi tempat ini lebih penuh semangat daripada siapa pun!",
  ui_story_5058_50581502_57_dialog_content = "Aku memohon padamu—tolong percayalah padaku! Aku tahu aku bisa menemukan cara untuk melindungi habitat alamimu dan menjaga anak-anakmu agar tidak terganggu!",
  ui_story_5058_50581502_58_dialog_content = "Desis?",
  ui_story_5058_50581502_59_dialog_content = "Kau mau menanyakan sesuatu?",
  ui_story_5058_50581502_60_dialog_content = "Ya, saya rasa dia pantas untuk dipercayai. Ibunya, Coco, juga ingin melindungi Lembah Denuo dan kupu-kupunya pada suatu waktu!",
  ui_story_5058_50581502_61_dialog_content = "Saya percaya dia mewarisi ide-ide Coco... Itulah mengapa saya percaya padanya!",
  ui_story_5058_50581502_62_dialog_content = "Desis, desis...",
  ui_story_5058_50581502_63_dialog_content = "Dewi Denuo tampaknya tidak terlalu marah lagi!",
  ui_story_5058_50581502_64_dialog_content = "<color=#e8d9bb>Krak!</color>",
  ui_story_5058_50581502_65_dialog_content = "*Wusss...*",
  ui_story_5058_50581502_66_dialog_content = "Hah? Anak Anda akan keluar dari kepompongnya?! Ap-Apa yang harus kita lakukan...? Saya masih memegangnya di tangan saya!",
  ui_story_5058_50581502_67_dialog_content = "<color=#e8d9bb>Dewi Denuo mengambil kepompong yang bercahaya dari tangan Lorelei.</color>",
  ui_story_5058_50581502_68_dialog_content = "Kamu bisa keluar sekarang...",
  ui_story_5058_50581502_69_dialog_content = "Ibu...",
  ui_story_5058_50581502_70_dialog_content = "Bagus sekali, anak saya. Kamu sudah bertambah besar.",
  ui_story_5058_50581502_71_dialog_content = "Aku tumbuh! Saya ingin menjadi sebesar Anda, Bu!",
  ui_story_5058_50581502_72_dialog_content = "Oh, dan...",
  ui_story_5058_50581502_73_dialog_content = "Saya percaya nona muda ini! Jika bukan karena dia, aku akan jatuh dari pohon dan tidak pernah melihat Ibu lagi!",
  ui_story_5058_50581502_74_dialog_content = "Kupu-kupu kecil itu... mendarat di Lorelei?!",
  ui_story_5058_50581502_75_dialog_content = "...",
  ui_story_5058_50581502_76_dialog_content = "Lalu kita harus memberikan rasa terima kasih yang tulus kepada dia.",
  ui_story_5058_50581502_77_dialog_content = "Kamu ingin aku... mengulurkan tanganku?",
  ui_story_5058_50581502_78_dialog_content = "Hah? Apakah ini kepompong yang baru saja ditinggalkan kupu-kupu kecil tadi?",
  ui_story_5058_50581502_79_dialog_content = "Saya minta maaf karena telah melumpuhkan ibumu. Cairan di dalam kepompong adalah penawarnya.",
  ui_story_5058_50581502_80_dialog_content = "Kami akan pindah lebih dalam ke lembah. Saya percaya kamu akan menepati janji Anda.",
  ui_story_5058_50581502_81_dialog_content = "Apakah ini... lendir yang Cena bicarakan? Terima kasih, Dewi Denuo! Terima kasih!",
  ui_story_5058_50581502_82_dialog_content = "Aku janji aku akan menepati kata-kataku!",
  ui_story_5058_50581502_83_dialog_content = "Semoga berhasil.",
  ui_story_5058_50581502_84_dialog_content = "Lorelei... Kamu menerima berkat dari Dewi Denuo?!",
  ui_story_5058_50581502_85_dialog_content = "Kamu...",
  ui_story_5058_50581502_86_dialog_content = "Oh... Dewi Denuo, Cena telah melindungi lembah bersamaku selama ini! Dia tidak seburuk yang dia katakan...",
  ui_story_5058_50581502_87_dialog_content = "Tolong jangan—",
  ui_story_5058_50581502_88_dialog_content = "Hah?",
  ui_story_5058_50581502_89_dialog_content = "<color=#e8d9bb>Dewi Denuo menyentuh sayap transparan di punggung Cena.</color>",
  ui_story_5058_50581502_90_dialog_content = "Wusss... Aku terlihat berbeda sekarang dan begitu juga kamu, tapi aku masih ingat sayap-sayap itu.",
  ui_story_5058_50581502_91_dialog_content = "Betapa indahnya sepasang sayap itu.",
  ui_story_5058_50581502_92_dialog_content = "Terima kasih telah membebaskan saya dari jaring laba-laba sebelumnya.",
  ui_story_5058_50581502_93_dialog_content = "Itu... Itu kamu?",
  ui_story_5058_50581502_94_dialog_content = "Pasir badai dari dua belas tahun lalu tidak ada hubungannya dengan kami, dan saya minta maaf atas penderitaan Anda.",
  ui_story_5058_50581502_95_dialog_content = "Selama ini saya selalu mencari kamu, bukan untuk menghukum, tetapi untuk mengucapkan terima kasih.",
  ui_story_5058_50581502_96_dialog_content = "Terima kasih telah memberi saya kehidupan baru, dan semoga kamu menemukan tujuan hidupmu.",
  ui_story_5058_50581502_97_dialog_content = "A-aku akan...",
  ui_story_5058_50581502_98_dialog_content = "Saya sangat menantikan untuk melihat anak Anda dengan sayap yang seindah milik Anda.",
  ui_story_5058_50581502_99_dialog_content = "Selain dari Luke, tidak ada orang lain yang pernah menghargai sayapku seperti itu...",
  ui_story_5058_50581502_100_dialog_content = "Saatnya bagi kita untuk pergi, anak saya.",
  ui_story_5058_50581502_101_dialog_content = "Tunggu aku, Bu!",
  ui_story_5058_50581502_102_dialog_content = "Pergi begitu saja, seperti itu?",
  ui_story_5058_50581502_103_dialog_content = "Hah? Semua Eclipsite di sekitar sini juga sudah pergi?!",
  ui_story_5058_50581502_104_dialog_content = "Jadi... apakah semuanya sudah berakhir sekarang? Evesemuanya terjadi begitu tiba-tiba, saya bahkan belum sempat memproses semuanya...",
  ui_story_5058_50581502_105_dialog_content = "Haha… Hahahahaha!",
  ui_story_5058_50581502_106_dialog_content = "Apa ide besar, Cena?! Jangan tiba-tiba tertawa seperti itu, kamu membuatku merinding...",
  ui_story_5058_50581502_107_dialog_content = "Saya hanya bisa tertawa pada diri sendiri. EveMeskipun jelas saya memiliki sayap ini di punggung saya, saya masih tidak bisa memahami apa yang dipikirkan oleh Dewi Denuo, setelah sekian lama.",
  ui_story_5058_50581502_108_dialog_content = "Apakah kamu seorang Dewi Denuo, serangga biasa, atau demi-human seperti saya, pada dasarnya kita semua sangat sederhana di hati.",
  ui_story_5058_50581502_109_dialog_content = "Dan selama kamu tidak menyakiti mereka, mereka tidak akan menyerang tanpa alasan.",
  ui_story_5058_50581502_110_dialog_content = "Mereka bisa melupakan seribu dendam dalam semalam, tetapi akan mengingat satu tindakan kebaikan seumur hidup.",
  ui_story_5058_50581502_111_dialog_content = "Mereka bahkan bisa melupakan dendam mereka?",
  ui_story_5058_50581502_112_dialog_content = "Cena, apa yang dikatakan Dewi Denuo kepadamu sebelum dia pergi?",
  ui_story_5058_50581502_113_dialog_content = "Dia memberkati saya dengan...",
  ui_story_5058_50581502_114_dialog_content = "Keberanian untuk terus hidup.",
  ui_story_5058_50581601_1_dialog_content = "Apa kaubilang?!",
  ui_story_5058_50581601_2_dialog_content = "Hapus semua sensasi terkait Dewi Denuo?",
  ui_story_5058_50581601_3_dialog_content = "Sebagai investor yang dihargai, inilah hal pertama yang ingin saya sampaikan kepada Anda hari ini.",
  ui_story_5058_50581601_4_dialog_content = "Hal kedua yang ingin saya informasikan adalah bahwa saya tidak akan melanjutkan pengembangan Denuo Incense, dan yang ketiga, saya dapat mengkonfirmasi bahwa fase kedua dari rencana ekspansi resor untuk semua maksud dan tujuan telah dibatalkan.",
  ui_story_5058_50581601_5_dialog_content = "Apakah Anda bahkan tahu apa yang Anda katakan?",
  ui_story_5058_50581601_6_dialog_content = "Semua tiga cara tersebut adalah cara terbaik untuk memastikan resor akan mengembalikan investasi uang dan tetap beroperasi! Bisakah kamu menjalankan bisnis?",
  ui_story_5058_50581601_7_dialog_content = "Heh, jangan khawatir tentang itu sekarang! Dari suara-suara itu... kamu punya rencana lain di lengan baju, kan bos?",
  ui_story_5058_50581601_8_dialog_content = "Saya tahu ini mungkin sulit untuk kamu terima pada awalnya, tetapi setelah pertimbangan yang matang, saya memutuskan bahwa Denuo Valley Resort harus beroperasi di bawah filsafat bisnis yang lebih bijaksana.",
  ui_story_5058_50581601_9_dialog_content = "Apakah itu pemasaran, layanan, atau produk yang bersumber lokal, kita perlu menjaga konsep keberlanjutan lembah dalam pikiran setiap saat, dan mengikuti prinsip panduan pengembangan ekologis.",
  ui_story_5058_50581601_10_dialog_content = "Kegiatan yang disebutkan sebelumnya mungkin menghasilkan keuntungan jangka pendek, tetapi mereka mengabaikan dampak yang kita timbulkan pada lingkungan dan konsekuensi yang akan muncul cepat atau lambat.",
  ui_story_5058_50581601_11_dialog_content = "Inilah mengapa saya mengusulkan kita lanjutkan meningkatkan lingkungan di dalam lembah dan menciptakan ekosistem di mana Aurorian, hewan, dan tumbuhan dapat hidup berdampingan...",
  ui_story_5058_50581601_12_dialog_content = "Terus perbaiki lingkungan? Semua itu hanya untuk mendapatkan lebih banyak uang dari kita?",
  ui_story_5058_50581601_13_dialog_content = "Berdasarkan perhitungan saya, keuntungan dari operasi dasar resor, dikurangi berbagai pengeluaran, seharusnya cukup untuk mendukung rencana yang saya usulkan!",
  ui_story_5058_50581601_14_dialog_content = "Apakah kamu menganggap kami bodoh? Kamu sudah mendapatkan banyak dari kami! Apakah kamu pikir ini amal?",
  ui_story_5058_50581601_15_dialog_content = "Saya telah melakukan berbagai tes awal, dan saya sangat yakin bahwa reinkarnasi baru resor ini akan menjadi hit pasti! Semua yang perlu kita lakukan adalah membuka gerbang dan melihat tamu berbondong-bondong masuk!",
  ui_story_5058_50581601_16_dialog_content = "Pertama, kita perlu mencoba sebaik mungkin untuk membangun reputasi yang baik, mengamankan keuntungan untuk periode saat ini, dan terus meningkatkan lingkungan di lembah...",
  ui_story_5058_50581601_17_dialog_content = "Setelah kita yakin lingkungan alam lembah dapat terjaga sepenuhnya, kita dapat membangun suaka margasatwa untuk dinikmati para tamu kita.",
  ui_story_5058_50581601_18_dialog_content = "Tidak hanya akan hal ini memberikan pengalaman unik dan baru bagi tamu kami, tetapi juga akan memastikan bahwa resor menawarkan lingkungan yang indah bagi setiap orang yang berkunjung.",
  ui_story_5058_50581601_19_dialog_content = "Dan dengan itu, resor kami akan memiliki keunggulan kompetitif yang kuat atas semua Astra!",
  ui_story_5058_50581601_20_dialog_content = "Tak perlu dikatakan, semua ini dijamin akan menghasilkan keuntungan besar dari investasi Anda dalam jangka panjang!",
  ui_story_5058_50581601_21_dialog_content = "Heheh... Senang sekali melihat kamu menuliskan ide-ide sendiri dan menjalankannya, Lorelei!",
  ui_story_5058_50581601_22_dialog_content = "Saya selalu menjadi orang yang mendorong dan mendukung semangat kewirausahaan saat melihatnya!",
  ui_story_5058_50581601_23_dialog_content = "Even jika investasi saya tidak menghasilkan keuntungan dalam waktu dekat, itu tidak masalah bagi saya... Saya tidak keberatan menunggu beberapa hari lagi untuk uang saya.",
  ui_story_5058_50581601_24_dialog_content = "Tentu saja, saya akan terus mengawasi kemajuan Anda untuk memastikan Anda tetap melacak dan melakukan apa yang Anda tetapkan untuk dicapai. Jika tidak, saya mungkin harus menarik dukungan saya juga.",
  ui_story_5058_50581601_25_dialog_content = "Konyol! Bagaimana dengan kamu yang lain? Saya tidak pikir kamu akan terus tertipu oleh proyek bodoh ini!",
  ui_story_5058_50581601_26_dialog_content = "Santai saja. Aku senang untuknya dan ide-idenya.",
  ui_story_5058_50581601_27_dialog_content = "Tapi... Kamu tahu apa yang sedang kamu lakukan sekarang jelas melanggar kontrak yang kita tanda tangani, kan, Lorelei?",
  ui_story_5058_50581601_28_dialog_content = "Berdasarkan ketentuan, kamu harus membayar kami tiga kali lipat untuk pelanggaran tersebut.",
  ui_story_5058_50581601_29_dialog_content = "Tentu, benar. Bisakah kamu membelinya, Lorelei?",
  ui_story_5058_50581601_30_dialog_content = "Aku…",
  ui_story_5058_50581601_31_dialog_content = "H-Hanya tiga kali lagi?! Ahhh... Apa yang harus kubilang pada Ayah sekarang?!",
  ui_story_5058_50581601_32_dialog_content = "Gosokkan garam pada luka seorang teman yang setia, dan kamu pasti akan menemui akhir yang buruk.",
  ui_story_5058_50581601_33_dialog_content = "Jika kamu memberi tahu kami tentang ini sejak awal, Lorelei, kami tidak akan pernah berinvestasi...",
  ui_story_5058_50581601_34_dialog_content = "Ya, saya juga...",
  ui_story_5058_50581601_35_dialog_content = "Jangan khawatir, Lorelei!",
  ui_story_5058_50581601_36_dialog_content = "Siapa yang kalian pikir kalian pandang rendah? Bukan seperti kita tidak mampu membelinya sendiri—",
  ui_story_5058_50581601_37_dialog_content = "...",
  ui_story_5058_50581601_38_dialog_content = "Ehem... Saya yakin seratus persen bahwa putri saya bisa menangani ini dengan satu tangan diikat di belakang punggungnya!",
  ui_story_5058_50581601_39_dialog_content = "(Mama...)",
  ui_story_5058_50581601_40_dialog_content = "Saya dengan tulus meminta maaf kepada kalian semua, dan saya sepenuhnya menyadari bahwa tindakan saya melanggar ketentuan kontrak awal kita.",
  ui_story_5058_50581601_41_dialog_content = "Saya bertanggung jawab penuh dan tidak akan mencoba menyalahkan orang lain.",
  ui_story_5058_50581601_42_dialog_content = "Tapi saya juga membutuhkan kalian semua untuk percaya bahwa tekad saya untuk membangun kembali lembah ini sama teguhnya dengan tekad saya untuk menjalankan resor yang luar biasa!",
  ui_story_5058_50581601_43_dialog_content = "Saya sangat yakin bahwa saya dapat mengamankan keuntungan yang lebih baik pada investasi Anda. Hanya saja... Anda mungkin perlu menunggu sedikit lebih lama dari yang diharapkan.",
  ui_story_5058_50581601_44_dialog_content = "Saya mengerti dan mengapresiasi Anda.",
  ui_story_5058_50581601_45_dialog_content = "Tapi saya akan minta pengacara saya mengirimkan tagihan kepada Anda, Lorelei.",
  ui_story_5058_50581601_46_dialog_content = "Jangan bilang kami tidak pernah memberi Anda kesempatan... Mulailah khawatir tentang kebangkrutan Anda.",
  ui_story_5058_50581601_47_dialog_content = "Laurie...",
  ui_story_5058_50581601_48_dialog_content = "Fiuh... Tidak apa-apa, Ibu. Aku pikir mungkin keadaannya akan seperti ini.",
  ui_story_5058_50581601_49_dialog_content = "Tapi ini belum selesai. Saya tidak akan menggunakan kekayaan keluarga untuk menutupi perbedaan itu sampai saya setidaknya meminta bantuan dari guild terlebih dahulu...",
  ui_story_5058_50581601_50_dialog_content = "Yah, tidak ada gunanya mencoba menghentikan pemberontak sejati seperti kamu.",
  ui_story_5058_50581601_51_dialog_content = "Hah, kamu tidak salah... tapi aku tahu aku melakukan hal yang benar, dan itu cukup untukku.",
  ui_story_5058_50581601_52_dialog_content = "Saya suka cara kamu juga tidak tahan dengan orang-orang tua itu.",
  ui_story_5058_50581601_53_dialog_content = "Saya tahu ada seorang penghisap yang ternyata memiliki lebih dari beberapa Nightium untuk dibagi, dan juga memiliki rombongan yang cukup besar.",
  ui_story_5058_50581601_54_dialog_content = "Jika dia tahu bahwa aku telah berinvestasi di sini, aku yakin dia akan berlomba-lomba untuk memberikan pendanaan lebih banyak daripada aku.",
  ui_story_5058_50581601_55_dialog_content = "Tolong janji kamu akan memperkenalkan saya kepadanya!",
  ui_story_5058_50581601_56_dialog_content = "Sayapnya berkilau seperti permata di bawah cahaya matahari!",
  ui_story_5058_50581601_57_dialog_content = "Sial, seharusnya aku ikut bersama kalian...",
  ui_story_5058_50581601_58_dialog_content = "Hmm, bukankah kamu bilang lebih baik punya satu masalah lebih sedikit daripada satu sakit kepala lagi, lalu tidur nyenyak seperti log?",
  ui_story_5058_50581601_59_dialog_content = "Apakah salahku jika tempat tidur hotel ini begitu empuk dan berbau sangat enak? Aku belum pernah tidur di tempat yang nyaman seperti ini sebelumnya...",
  ui_story_5058_50581601_60_dialog_content = "Tidak masalah... Fia dan saya bekerja sebagai pakar binatang senior untuk resor ini, jadi kami mungkin masih berkesempatan bertemu Dewi Denuo suatu hari nanti.",
  ui_story_5058_50581601_61_dialog_content = "Master, apakah Anda benar-benar berencana untuk menghabiskan hari-hari Anda di sini selamanya?",
  ui_story_5058_50581601_62_dialog_content = "PlayerName, apa yang masih kamu lakukan di sini ngobrol-ngobrol?",
  ui_story_5058_50581601_63_dialog_content = "Lihat, aku dan Carleen sudah mengumpulkan banyak stiker!",
  ui_story_5058_50581601_64_dialog_content = "Mereka benar-benar mengguncang kampanye pemasaran mereka—bahkan kupu-kupu pada stiker ini telah digantikan...",
  ui_story_5058_50581601_65_dialog_content = "Namun aturannya tetap sama seperti sebelumnya—cukup kumpulkan stiker yang cukup dan kamu bisa menukarkannya dengan hadiah!",
  ui_story_5058_50581601_66_dialog_content = "Kami dengar bahwa hadiah utama adalah tiket masuk tahunan untuk Denuo Valley Resort.",
  ui_story_5058_50581601_67_dialog_content = "Jika kamu tidak mengumpulkan cukup stiker, PlayerName... Aku akan mengambil Carleen lain kali! Aku bahkan tidak akan repot-repot menanyakan padamu!",
  ui_story_5058_50581601_68_dialog_content = "Kamu benar-benar akan pergi tanpa aku?",
  ui_story_5058_50581601_69_dialog_content = "Ehem... Lihat, jika kamu tidak ingin ketinggalan, ayo main Fantasy Matrix bersama kami!",
  ui_story_5058_50581601_70_dialog_content = "Apa? Kamu masih main-main dengan itu?!",
  ui_story_5058_50581601_71_dialog_content = "Berikut adalah saran gratis—untuk selanjutnya, jangan pernah berpikir untuk membiarkan Sinsa merancang wahana taman bermain...",
  ui_story_5058_50581601_72_dialog_content = "Menemukannya.",
  ui_story_5058_50581601_73_dialog_content = "Cena, belum cukupkah yang sudah kamu lakukan?",
  ui_story_5058_50581601_74_dialog_content = "Bisakah kamu akhirnya bergabung bersama kami hari ini?",
  ui_story_5058_50581601_75_dialog_content = "Wanita, terima kasih semua atas banyaknya komentar dan saran yang penuh wawasan yang telah Anda ajukan ke resort!",
  ui_story_5058_50581601_76_dialog_content = "Berdasarkan keinginan Anda, Lorelei telah meminta saya untuk mempercepat penyesuaian pada peralatan dan berbagai layanan resort berdasarkan saran Anda.",
  ui_story_5058_50581601_77_dialog_content = "Ada yang berbeda tentang Cena...",
  ui_story_5058_50581601_78_dialog_content = "Hah? Masa? Belum pernah ya aku tunjukkan sisi keren dan kompetenku pada kalian, wanita?",
  ui_story_5058_50581601_79_dialog_content = "Sudah bertemu?",
  ui_story_5058_50581601_80_dialog_content = "Tidak.",
  ui_story_5058_50581601_81_dialog_content = "Yikes... Itu sangat kejam, Winona. Haha...",
  ui_story_5058_50581601_82_dialog_content = "Cena, jangan terbawa suasana ngobrol dengan tamu! Ingat, kita masih punya banyak pekerjaan yang harus dikerjakan!",
  ui_story_5058_50581601_83_dialog_content = "Oh, benar... Hampir saja aku lupa...",
  ui_story_5058_50581601_84_dialog_content = "Wanita, saya harus pergi! Tolong, jangan terlalu merindukanku—kita bisa mengenang masa lalu nanti!",
  ui_story_5058_50581601_85_dialog_content = "Haruskah kita terus menunggu?",
  ui_story_5058_50581601_86_dialog_content = "Nah, dia tampak cukup baik sehingga kita bisa berhenti khawatir.",
  ui_story_5058_50581601_87_dialog_content = "Sayang sekali. Bagaimana kalau kita pergi melihat si Caelestite?",
  ui_story_5058_50581601_88_dialog_content = "Hei, itu bukan ide yang buruk.",
  ui_story_5058_50581601_89_dialog_content = "Hmm? Aku baru pergi sebentar untuk mengambil es krim kadal! Kemana semua orang pergi?",
  ui_story_5058_50581601_90_dialog_content = "<size=45>Apakah mereka lupa padaku lagi?!</size>",
  ui_story_5058_50581601_91_dialog_content = "Pertama kali aku mengajakmu naik bianglala, kamu hampir tidak bisa melihat pemandangan, bahkan ketika berdiri.",
  ui_story_5058_50581601_92_dialog_content = "Aku ingat, aku ingat! Aku benar-benar marah dan mulai mengeluh tentang bagaimana roda langit tidak dirancang dengan baik, dan bahwa aku ingin mengeluh kepada manajer.",
  ui_story_5058_50581601_93_dialog_content = "Staf mengatakan mereka akan memberi saya boneka untuk membuat saya senang.",
  ui_story_5058_50581601_94_dialog_content = "Dan dari semua boneka lucu yang mereka minta kamu pilih, kamu malah memilih spesimen kerangka hewan besar yang dipajang!",
  ui_story_5058_50581601_95_dialog_content = "Hahaha! Saya benar-benar tidak tahu apa yang saya pikirkan saat itu...",
  ui_story_5058_50581601_96_dialog_content = "Saya benar-benar tidak percaya... Laurie kecilku telah tumbuh begitu besar.",
  ui_story_5058_50581601_97_dialog_content = "Mama, terima kasih sudah ada untukku di rapat dewan hari ini.",
  ui_story_5058_50581601_98_dialog_content = "Jika kamu tidak ada di sana, saya tidak yakin saya akan memiliki kepercayaan diri untuk berhasil.",
  ui_story_5058_50581601_99_dialog_content = "Jangan konyol—kamu anakku! Ibu macam apa yang tidak mendukung anak perempuannya, hah?!",
  ui_story_5058_50581601_100_dialog_content = "Dan aku tahu bahwa meskipun aku tidak ada di sampingmu, kamu memiliki kemampuan untuk mencapai apapun yang kamu tekadkan.",
  ui_story_5058_50581601_101_dialog_content = "Seperti bagaimana kamu dengan berani meminta penawar dari Dewi Denuo dan menyelamatkan aku...",
  ui_story_5058_50581601_102_dialog_content = "Jika bukan karena kamu, mungkin saja aku tidak akan pernah bisa berdamai dengan Dewi Denuo.",
  ui_story_5058_50581601_103_dialog_content = "Benar. Mungkin seluruh pengalaman ini adalah kesempatan yang diberikan kepada kita oleh langit, atau mungkin oleh Dewi Denuo sendiri...",
  ui_story_5058_50581601_104_dialog_content = "Aku terjebak dalam mimpi buruk yang panjang dan menyakitkan—sebuah mimpi di mana aku harus menghadapi diri sejatiku.",
  ui_story_5058_50581601_105_dialog_content = "Itulah saatnya aku menyadari bahwa aku belum menjadi ibu yang baik untukmu...",
  ui_story_5058_50581601_106_dialog_content = "Aku tidak memberitahumu tentang kampung halaman dan orang-orang yang kamu cintai, dan bahkan aku menghambat pertumbuhanmu...",
  ui_story_5058_50581601_107_dialog_content = "Mam, jangan bilang begitu tentang dirimu sendiri!",
  ui_story_5058_50581601_108_dialog_content = "Aku gadis paling beruntung di dunia, dan kamu tahu mengapa? Karena aku memiliki dua ibu yang baik hati dan cantik!",
  ui_story_5058_50581601_109_dialog_content = "Waow, waow, waow... Jika kalian berdua ingin memiliki percakapan hati ke hati antara ibu dan anak perempuan, itu sangat baik, tetapi mengapa kalian menyeret saya ke dalam ini?",
  ui_story_5058_50581601_110_dialog_content = "Saya bilang ke wanita-wanita itu, saya akan kembali sebentar! Bayi-bayi cantik itu menunggu saya, demi apapun!",
  ui_story_5058_50581601_111_dialog_content = "Tentu saja aku harus menyeretmu ikut.",
  ui_story_5058_50581601_112_dialog_content = "Apakah kamu lupa janji antara aku, kamu, dan Coco?",
  ui_story_5058_50581601_113_dialog_content = "Janji? Janji apa?",
  ui_story_5058_50581601_114_dialog_content = "Oh, akan segera dimulai... Tiga... dua...",
  ui_story_5058_50581601_115_dialog_content = "Satu!",
  ui_story_5058_50581601_116_dialog_content = "<color=#e8d9bb>Whoosh—Bang!</color>",
  ui_story_5058_50581601_117_dialog_content = "Itu…",
  ui_story_5058_50581601_118_dialog_content = "Pertunjukan kembang api?",
  ui_story_5058_50581601_119_dialog_content = "<color=#e8d9bb>Whuzz—Bukk, bukk!</color>",
  ui_story_5058_50581601_120_dialog_content = "\"Kembang api meluncur ke langit malam seperti kupu-kupu yang berkepak...\"",
  ui_story_5058_50581601_121_dialog_content = "Apakah kembang api di Lumopolis benar-benar seindah itu?",
  ui_story_5058_50581601_122_dialog_content = "Saya dengar mereka bahkan lebih indah daripada kupu-kupu!",
  ui_story_5058_50581601_123_dialog_content = "Mama, aku juga ingin pergi ke Lumopolis untuk menonton kembang api!",
  ui_story_5058_50581601_124_dialog_content = "Tapi Lumopolis jauh sekali!",
  ui_story_5058_50581601_125_dialog_content = "Apa yang perlu ditakuti? Ayo pergi dan tonton bersama-sama! Aku tahu kita akan sampai di sana suatu hari nanti!",
  ui_story_5058_50581601_126_dialog_content = "Betulkah? Kamu berdua tidak merindukan rumah?",
  ui_story_5058_50581601_127_dialog_content = "Di mana pun kamu berada, Coco, di situlah rumahku.",
  ui_story_5058_50581601_128_dialog_content = "Hei! Apakah kamu mencoba mencuri ibuku, Cena?! Enak saja! Ibu sepenuhnya milikku!",
  ui_story_5058_50581601_129_dialog_content = "Saya bahkan tidak mencoba mengatakan bahwa Coco itu ibu saya!",
  ui_story_5058_50581601_130_dialog_content = "Dia... wanita yang cantik!",
  ui_story_5058_50581601_131_dialog_content = "Haha, memang terdengar menyenangkan punya anak seumuran kamu!",
  ui_story_5058_50581601_132_dialog_content = "Ny. Coco! Wanita tercantik yang saya kenal!",
  ui_story_5058_50581601_133_dialog_content = "Luke, sudah lama sekali tidak mendengar kabar darimu.",
  ui_story_5058_50581601_134_dialog_content = "\"Kamu nggak akan bisa menebak di mana aku bekerja sekarang!\"",
  ui_story_5058_50581601_X134_dialog_content = "\"Saya bekerja di Denuo Valley Resort—tempat yang kamu sebutkan dalam suratmu!\"",
  ui_story_5058_50581601_135_dialog_content = [[
Jika saya memberitahu kamu bahwa Lembah Denuo adalah kampung halaman misterius yang pernah saya sebutkan sebelumnya,
seberapa terkejutkah kamu?]],
  ui_story_5058_50581601_136_dialog_content = "\"Tapi saya punya sesuatu yang lebih mengejutkan untuk diberitahu kepada kamu...\"",
  ui_story_5058_50581601_X136_dialog_content = "\"Saya melihat Dewi Denuo!\"",
  ui_story_5058_50581601_137_dialog_content = "Dan itu benar, AKU SELAMAT! Aku tahu apa yang kamu pikirkan sekarang, \"Kenapa dia menulis bahwa dia masih hidup dengan huruf kapital semua?\"",
  ui_story_5058_50581601_138_dialog_content = "Sayangnya, saya tidak bisa memuat semua detail dalam satu surat...",
  ui_story_5058_50581601_139_dialog_content = "Jika kamu memiliki waktu, kamu harus datang mengunjungi saya di resor. Saya akan menunggu kamu, dan siap berbagi semua pengalaman saya sejak kembali ke kampung halaman.",
  ui_story_5058_50581601_140_dialog_content = "\"Evetiap malam sebelum aku menutup mata untuk tidur, aku menantikan apa yang mungkin besok bawa. Rasanya...\"",
  ui_story_5058_50581601_X140_dialog_content = "<size=45>\"Luar Biasa!\"</size>"
}
return config
